local _, ns = ...
local E = ns.DB.entries
E["npc:bailiff-conacher"] = {t="npc",n="Bailiff Conacher",z="redridge",s="Bailiff Conacher serves in the Lakeshire Town Hall as the chief enforcement officer under Magistrate Solomon. Tasked with maintaining civil order and administering local decrees, he turns to independent champions to enforce the laws of Stormwind across the embattled Redridge Mountains.",h="Bailiff Conacher serves in the Lakeshire Town Hall as the chief enforcement officer under Magistrate Solomon.",sec={{t="Justice in Lakeshire",b="Within the Lakeshire Town Hall, Bailiff Conacher works closely with Magistrate Solomon to uphold lawful authority in the Redridge Mountains. With the town besieged on all fronts by Blackrock orcs and local gnolls, Conacher cannot rely on standard civic procedures or royal garrisons. Instead, he issues legal decrees that grant passing travelers the authority to administer capital justice on behalf of the realm.",sp=0},{t="Applying Solomon's Law",b="When the dark mage Morganth occupied the Tower of Ilgalar and subjugated the local Shadowhide gnolls to his will, the Court of Lakeshire deemed the beasts complicit in high treason. Since aiding a fugitive and criminal of the Kingdom of Stormwind carries a sentence of death, Conacher invokes Solomon's Law. He directs adventurers to scour the ridges for Shadowhide gnolls, demanding their pendants as legal proof that the crown's law has been carried out.",sp=0}},faq={{q="Who is Bailiff Conacher?",a="Bailiff Conacher is an officer of the Court of Lakeshire who assists Magistrate Solomon in upholding civil authority and Stormwind law in the Redridge Mountains.",al={"bailiff conacher role","who is conacher","conacher lore"}},{q="Where can Bailiff Conacher be found?",a="He is located inside the Lakeshire Town Hall on the north side of the bridge in the Redridge Mountains.",al={"bailiff conacher location","where is conacher","conacher redridge"}},{q="What is Solomon's Law?",a="It is the judicial application of Stormwind law decreed by Magistrate Solomon. Under this decree, aiding known criminals such as the rogue sorcerer Morganth is punishable by death, legally marking the allied Shadowhide gnolls for execution.",al={"what is solomons law","solomon law gnolls","shadowhide law"}},{q="Why does Conacher ask for Shadowhide pendants?",a="The pendants serve as verifiable proof that a Shadowhide gnoll has been slain in enforcement of Lakeshire's legal sentence against those aiding Morganth.",al={"why collect pendants","shadowhide pendants purpose"}}},ang={["faction:Alliance"]="Bailiff Conacher represents the fragile reach of Stormwind's legal system in a border town largely abandoned to fend for itself."},kw={"bailiff","conacher","lakeshire","morganth","redridge","shadowhide","solomon","town hall"},rel={"npc:magistrate-solomon","quest:91","subzone:lakeshire-town-hall","subzone:lakeshire","subzone:tower-of-ilgalar","quest:249","topic:gnoll","zone:redridge"},src={"Bailiff Conacher"}}
E["npc:barkeep-daniels"] = {t="npc",n="Barkeep Daniels",z="redridge",s="Barkeep Daniels tends the counter at the Lakeshire Inn, serving weary town guards, local fishermen, and visiting travelers. With the Blackrock clan raiding across the Redridge Mountains and cutting off supply routes, keeping the tavern fully stocked has become an uphill battle.",h="Barkeep Daniels tends the counter at the Lakeshire Inn, serving weary town guards, local fishermen, and...",sec={{t="Keeping Spirits High in Lakeshire",b="Behind the counter of the Lakeshire Inn stands Barkeep Daniels, pouring drinks and greeting whoever wanders in from the bridge. Lakeshire has spent months under constant pressure from gnolls and the Blackrock orcs, and the town's defenders rely on the tavern to unwind after grim patrols. Unfortunately for Daniels, the severed roads and relentless attacks have disrupted trade throughout the region. Finding himself dangerously low on liquor during a time when the town needs good cheer most, he is eager for any passing adventurer willing to fetch shipments from safer settlements.",sp=0}},faq={{q="Who is Barkeep Daniels?",a="Barkeep Daniels is the human tavern keeper working the counter at the Lakeshire Inn. He handles drink orders for local townsfolk, traveling adventurers, and the beleaguered town guard.",al={"daniels redridge","lakeshire barkeep","who is daniels"}},{q="Why is he running low on drinks?",a="Ongoing raids by the Blackrock orcs and neighboring gnoll tribes have choked off supply caravans and trade routes into the Redridge Mountains. With deliveries cut off and stressed defenders drinking through current stores, Daniels is struggling to replenish his shelves.",al={"why out of booze","dry times quest lore","why no alcohol"}},{q="What does he need help with?",a="Through the task 'Dry Times', Daniels looks for willing travelers to venture out and bring back fresh supplies of liquor from outside Redridge to keep the inn's patrons satisfied.",al={"barkeep daniels quest","what does he want","daniels errand"}}},ang={["faction:Alliance"]="Maintaining morale in Lakeshire is essential for the Alliance, as the settlement serves as the kingdom's battered buffer against Blackrock stronghold in the north."},kw={"barkeep daniels","bartender","daniels","dry times","lakeshire inn","redridge innkeeper"},rel={"subzone:lakeshire-inn","subzone:lakeshire","zone:redridge","quest:116"},src={"Barkeep Daniels"}}
E["npc:chef-breanna"] = {t="npc",n="Chef Breanna",z="redridge",s="Chef Breanna is the head cook at Lakeshire's local dining house in the Redridge Mountains. Tasked with feeding the garrison of Stormwind soldiers stationed to protect the embattled lakeside town, she relies on hearty, local ingredients to keep the defenders on their feet.",h="Chef Breanna is the head cook at Lakeshire's local dining house in the Redridge Mountains.",sec={{t="Feeding Lakeshire's Defenders",b="Operating out of a restaurant house in northwestern Lakeshire alongside her assistants Crystal Boughman and Gretchen Vogel, Chef Breanna bears the heavy responsibility of provisioning the entire local battalion. With Lakeshire besieged by Blackrock orcs, gnolls, and murlocs, maintaining the strength and morale of Stormwind's understaffed garrison is essential. Her signature dish, Redridge Goulash, relies on the wild game and beasts roaming the surrounding ridges, turning dangerous wilderness predators into fuel for the town's weary guard.",sp=0}},faq={{q="Who is Chef Breanna?",a="Chef Breanna is the town cook in Lakeshire, running the local kitchen house in the northwestern corner of the settlement. She is tasked with feeding the Stormwind soldiers defending the Redridge Mountains.",al={"chef breanna","breanna lakeshire","who is breanna"}},{q="What does Chef Breanna need help with?",a="She needs local game meat to brew Redridge Goulash for the garrison. Adventurers help her by foraging for boar ribs, spider meat, and vulture meat from the wilderness surrounding Lakeshire.",al={"breanna quest","redridge goulash ingredients","what does she want"}},{q="Who works with Chef Breanna?",a="Her bustling establishment employs Crystal Boughman and Gretchen Vogel, who help her manage the restaurant house and tend to hungry townsfolk and soldiers.",al={"breanna helpers","crystal boughman","gretchen vogel"}}},ang={["profession:Cooking"]="Breanna's resourceful recipe for Redridge Goulash showcases how a frontier chef can turn dangerous local predators—spiders, vultures, and boars—into a hearty meal to sustain a military outpost.",["faction:Alliance"]="Without Chef Breanna provisioning the soldiers holding the bridge and town perimeter, Lakeshire's strained garrison would quickly succumb to exhaustion against the relentless orc and gnoll incursions."},kw={"breanna","chef breanna","cook","garrison","goulash","lakeshire","redridge goulash"},rel={"quest:92","subzone:lakeshire","zone:redridge","topic:stormwind-kingdom"},src={"Chef Breanna"}}
E["npc:darcy-parker"] = {t="npc",n="Darcy Parker",z="redridge",s="Darcy is a waitress serving drinks and warm meals at the Lakeshire Inn. Amid the constant threats looming over Redridge, she keeps her spirits up by looking after local defenders—particularly Guard Parker.",h="Darcy is a waitress serving drinks and warm meals at the Lakeshire Inn.",sec={{t="A Friendly Face at the Inn",b="Behind the busy counter of the Lakeshire Inn, Darcy works day and night to keep the town's weary militia fed and watered. Lakeshire sits under constant pressure from gnolls and Blackrock orcs, making the tavern one of the few places of warmth left in the settlement. Darcy takes a personal interest in the guards posted around town, frequently recruiting traveling adventurers to run hot meals and friendly errands out to those stationed along the borders.",sp=0},{t="Romance on the Guard Post",b="Darcy's warmth extends especially toward Guard Parker, who patrols the roads near Three Corners. Convinced he works too hard on an empty stomach, she regularly sends travelers out with lunch to keep him on his feet. Her affections have not gone unnoticed—Darcy keeps a watchful eye on Martie Jainrose, whom she considers a jealous rival for Parker's favor, turning the defense of Lakeshire into the backdrop for an earnest small-town romance.",sp=0}},faq={{q="Who is Darcy?",a="Darcy is a human waitress working inside the Lakeshire Inn in the Redridge Mountains. She prepares food for the town's defenders and regularly asks passing travelers to help deliver meals to guards stationed on duty.",al={"who is darcy","darcy parker npc","lakeshire waitress"}},{q="What is Darcy's relationship with Guard Parker?",a="Darcy holds a deep affection for Guard Parker. She goes out of her way to pack him fresh lunches and send them along via travelers so he stays fed while patrolling the roads near Three Corners.",al={"darcy and guard parker","guard parker darcy","who does darcy like"}},{q="Why is Darcy suspicious of Martie Jainrose?",a="Darcy believes Martie Jainrose is the jealous type and views her as romantic competition for the attention of Guard Parker, adding a bit of personal rivalry to daily life in town.",al={"darcy and martie","martie jainrose","darcy rival"}},{q="Where can Darcy be found?",a="She can be found serving patrons inside the Lakeshire Inn, situated right in the heart of Lakeshire by the northern shore of Lake Everstill in Redridge.",al={"darcy location","where is darcy","find darcy"}}},ang={["faction:Alliance"]="Darcy represents the resilient everyday folk of Lakeshire, keeping spirits high and bellies full while the town waits on aid from Stormwind."},kw={"darcy","darcy parker","guard parker","lakeshire","lakeshire inn","martie jainrose","redridge","waitress"},rel={"npc:watch-captain-parker","npc:martie-jainrose","subzone:lakeshire-inn","subzone:lakeshire","zone:redridge","quest:129","quest:131"},src={"Darcy Parker"}}
E["npc:deputy-feldon"] = {t="npc",n="Deputy Feldon",z="redridge",s="Deputy Feldon is a member of the Redridge town guard stationed just south of the Great Lakeshire Bridge. Tasked with watching the primary road into Lakeshire, he keeps a nervous vigil against the aggressive gnoll packs creeping toward the town perimeter.",h="Deputy Feldon is a member of the Redridge town guard stationed just south of the Great Lakeshire Bridge.",sec={{t="A Guard on Edge",b="Standing watch near the southern approach to the Lakeshire bridge, Deputy Feldon represents an overextended town guard fighting to keep basic trade and travel routes open. With the Blackrock orcs pressing from the north and gnoll packs overrunning the southern hills, guardsmen like Feldon are stretched to their limits. Unable to leave his post without compromising the town's perimeter, he relies on passing adventurers to cull the gnolls encroaching on the roadway before they can cut Lakeshire off entirely.",sp=0}},faq={{q="Who is Deputy Feldon?",a="Deputy Feldon is an officer of the Lakeshire town guard stationed just south of the bridge connecting the town to the main southern road in Redridge Mountains.",al={"feldon","who is feldon","deputy feldon role"}},{q="Why is Deputy Feldon worried about gnolls?",a="Gnoll packs have grown increasingly bold, creeping close to the southern edge of town and harassing travelers. Feldon fears that if their numbers are not pruned back, they will completely choke off the southern road into Lakeshire.",al={"why gnolls","feldon gnoll problem","encroaching gnolls"}},{q="Why doesn't Feldon deal with the gnolls himself?",a="The Lakeshire guard is severely understaffed and facing simultaneous threats from orcs and gnolls. Feldon cannot abandon his sentry post at the bridge without leaving the entrance to the town unguarded.",al={"why doesn't feldon fight","feldon duty"}},{q="Where can Deputy Feldon be found?",a="He stands watch on the road just south of the Great Lakeshire Bridge, keeping watch over the southern approaches to the town.",al={"feldon location","where is feldon"}}},ang={["faction:Alliance"]="Feldon embodies the desperate state of Stormwind's outer territories, where local guardsmen must beg passing champions for help maintaining the king's peace."},kw={"bridge","deputy feldon","feldon","gnolls","guard","lakeshire","redridge"},rel={"subzone:lakeshire","zone:redridge","quest:244","quest:246","topic:gnoll"},src={"Deputy Feldon"}}
E["npc:foreman-oslow"] = {t="npc",n="Foreman Oslow",z="redridge",s="Foreman Oslow is Lakeshire's beleaguered master builder, tasked with repairing the ruined Everstill Bridge in the heart of Redridge Mountains. Beset by Blackrock orc artillery and gnoll raiders, his reconstruction efforts have stalled due to lost shipments and sunken equipment. He relies heavily on traveling adventurers to retrieve his gear and secure materials so Lakeshire can reconnect its vital trade route.",h="Foreman Oslow is Lakeshire's beleaguered master builder, tasked with repairing the ruined Everstill Bridge in...",sec={{t="A Town Cut in Two",b="Standing by the fractured masonry of the Everstill Bridge, Foreman Oslow faces an uphill battle. The bridge is the lifeline of Lakeshire, spanning the expanse of Lake Everstill and linking the western roads toward Elwynn to the eastern shores. Blackrock orcs, sweeping down from the crags of Stonewatch, targeted the crossing to cripple the town's logistics and military movement, leaving the settlement splintered and vulnerable.",sp=0},{t="Sunken Steel and Stolen Stone",b="Every attempt Oslow makes to rebuild seems plagued by misfortune. When the bridge fell, his replacement tools were shipped overland from Goldshire and loaded onto a lake ferry. Orc catapult crews caught the vessel in their sights, sending his heavy iron toolbox straight to the muddy bed of Lake Everstill. To compound matters, local Redridge gnolls ambushed his supply wagons, making off with timber and mortar rivets necessary to raise the arches.",sp=0}},faq={{q="Who is Foreman Oslow?",a="Foreman Oslow is a human stonemason and builder stationed in Lakeshire. He is the head craftsman responsible for the maintenance and reconstruction of the Everstill Bridge.",al={"foreman oslow","who is oslow","lakeshire builder"}},{q="Why is the Everstill Bridge broken?",a="The Everstill Bridge was shattered by the Blackrock orcs of Redridge Mountains. Destroying the span severed Lakeshire's main thoroughfare, severely weakening the town's defenses and cutting off easy transit between the eastern and western shores.",al={"why is the bridge broken","who broke lakeshire bridge","everstill bridge destroyed"}},{q="Where are Oslow's lost tools?",a="Oslow's heavy toolbox rests at the bottom of Lake Everstill. The boat transporting them from Goldshire was struck and sunk by a Blackrock catapult barrage.",al={"where are the tools","lost tools location","oslow toolbox"}},{q="Why hasn't the bridge been repaired yet?",a="Between orc catapult fire sinking his tools in the lake and gnolls stealing building supplies from incoming shipments, Oslow lacks the necessary materials and equipment to resume construction without outside help.",al={"why is bridge not fixed","lakeshire bridge delay"}},{q="Where did Oslow's supplies come from originally?",a="His replacement tools were originally carted in on a wagon from Goldshire in Elwynn Forest before being transferred to a lake ferry to bypass the broken span.",al={"supply wagon origin","where did tools come from"}},{q="What threats is Oslow dealing with?",a="Oslow faces constant harassment from two fronts: the Blackrock clan orcs entrenched in the nearby heights, whose siege engines bombard the lake, and prowling gnolls who pick off supply convoys.",al={"oslow enemies","who attacks the bridge"}}},ang={["faction:Alliance"]="Lakeshire's severed bridge leaves the eastern frontier exposed, making Oslow's restoration efforts a strategic necessity for securing the Alliance border.",["profession:Mining"]="Oslow relies on raw materials, metalwork, and quarry shipments to rebuild broken masonry, keeping him intimately tied to local mineral deliveries."},kw={"blackrock","everstill bridge","foreman oslow","goldshire","lakeshire","oslow","redridge","toolbox"},rel={"quest:89","quest:125","subzone:lakeshire","zone:redridge","topic:gnoll","subzone:goldshire","quest:347","quest:345"},src={"Foreman Oslow"}}
E["npc:gath-ilzogg"] = {t="npc",n="Gath'Ilzogg",z="redridge",s="Gath'Ilzogg is the fearsome Blackrock orc warlord who commands the invasion force occupying Stonewatch Keep in the Redridge Mountains. Under his brutal leadership, the orcs seized the fortress and launched devastating raids against the town of Lakeshire, earning him an urgent bounty from the town's desperate magistrate.",h="Gath'Ilzogg is the fearsome Blackrock orc warlord who commands the invasion force occupying Stonewatch Keep...",sec={{t="The Scourge of Stonewatch",b="Gath'Ilzogg marched north out of the Burning Steppes under orders to secure Redridge for the Blackrock clan. Aided by the foul sorcery of the renegade human warlock Morganth, Gath'Ilzogg's warband battered the defenders of Stonewatch Keep and seized the high ground overlooking the entire region. From this entrenched redoubt, he oversees aggressive raids into the valleys and down toward the bridge of Lakeshire, steadily suffocating the human settlement. He rarely fights alone, keeping elite Blackrock guards and a vicious black dragon whelp named Singe close at hand.",sp=0},{t="A Fragile Hold",b="Despite his conquest of Stonewatch, Gath'Ilzogg's victory created new complications. Morganth quickly turned on his former orcish allies, raising an army of Shadowhide gnolls under Lieutenant Fangore that prey on Blackrock patrols and human travelers alike. Concurrently, Magistrate Solomon placed an open bounty on the warlord's head, pleading for any Alliance mercenaries or adventurers to scale the ramparts of Stonewatch Keep and end Gath'Ilzogg's terror before the town falls entirely.",sp=1}},faq={{q="Who is Gath'Ilzogg?",a="Gath'Ilzogg is an orc warlord belonging to the Blackrock clan. He leads the vanguard that invaded Redridge and successfully captured Stonewatch Keep from the Alliance.",al={"gath'ilzogg lore","who is gathilzogg","blackrock boss redridge"}},{q="Where can Gath'Ilzogg be found?",a="He is entrenched at the very top of Stonewatch Keep, located in the eastern crags of the Redridge Mountains.",al={"gath'ilzogg location","where is gathilzogg","find gathilzogg"}},{q="Why does Gath'Ilzogg have a dragon whelp?",a="Gath'Ilzogg is accompanied by a black dragon whelp named Singe, widely believed to be a gift from Lord Victor Nefarius to reward the warlord for successfully seizing Stonewatch Keep.",al={"why whelp next to gathilzogg","singe dragon","black dragon whelp gathilzogg"}},{q="Why is there a bounty on his head?",a="Magistrate Solomon of Lakeshire posted a high-priority bounty for Gath'Ilzogg's head because the warlord's constant raids and occupation of Stonewatch directly threaten Lakeshire with complete destruction.",al={"wanted gath'ilzogg","who wants gathilzogg dead","magistrate solomon bounty"}},{q="What happened between Gath'Ilzogg and Morganth?",a="The human warlock Morganth initially aided Gath'Ilzogg with dark magic to conquer Stonewatch. However, once the fortress fell, Morganth betrayed the orcs and raised an army of Shadowhide gnolls to attack both humanity and the Blackrock clan.",al={"morganth gathilzogg alliance","why are gnolls attacking orcs","morganth betrayal"}}},ang={["faction:Alliance"]="Taking down Gath'Ilzogg breaks the backbone of the Blackrock offensive threatening Lakeshire and answers the desperate call of Magistrate Solomon.",["race:Orc"]="Gath'Ilzogg represents the old, warmongering ways of the Blackrock clan under the Dark Horde, wholly separate from Thrall's new Horde in Kalimdor."},kw={"blackrock","gath'ilzogg","gathilzogg","lakeshire","morganth","singe","solomon","stonewatch","stonewatch keep"},rel={"quest:169","subzone:stonewatch-keep","subzone:stonewatch","npc:magistrate-solomon","quest:249","topic:blackrock-clan","subzone:lakeshire","zone:redridge"},src={"Gath'Ilzogg"}}
E["npc:general-marcus-jonathan"] = {t="npc",n="General Marcus Jonathan",z="redridge",s="General Marcus Jonathan is the High Commander of Stormwind Defense, stationed directly at the gates in the Valley of Heroes. A veteran of the Second War, he oversees the garrison protecting the capital and manages military requests from the kingdom's frontier settlements.",h="General Marcus Jonathan is the High Commander of Stormwind Defense, stationed directly at the gates in the...",sec={{t="Commander of the Gates",b="Mounted atop his steed in the Valley of Heroes, General Marcus Jonathan stands as the first line of defense and the highest-ranking military officer overseeing the city gates. He fought in the Second War alongside renowned soldiers like Reginald Windsor under the command of General Turalyon. In this era of rising tension, Jonathan must balance the immediate security of the capital with the increasingly desperate calls for aid from frontier towns like Lakeshire.",sp=0},{t="A Strained Command",b="While towns like Lakeshire beg for Stormwind soldiers to repel Blackrock orcs and gnolls, Jonathan assures local magistrates of his commitment to help, yet he privately confides that the court has grown distant and the boy-king's regency behaves strangely.",sp=1}},faq={{q="Where can I find General Marcus Jonathan?",a="He is stationed on horseback right inside the main gates of Stormwind City, overlooking the entrance bridge in the Valley of Heroes.",al={"marcus jonathan location","where is general jonathan","stormwind gate commander"}},{q="What is Marcus Jonathan's military history?",a="Marcus Jonathan is a veteran who served under General Turalyon during the Second War. He fought alongside comrades such as Reginald Windsor before eventually rising to become the High Commander of Stormwind Defense.",al={"marcus jonathan past","marcus jonathan lore","did marcus fight in the second war"}},{q="What is the coin in the Dalaran fountain about?",a="As a young private visiting Dalaran, Marcus Jonathan tossed a copper coin into the fountain wishing that he would grow a glorious, bushy mustache someday—a wish his prominent facial hair confirms came true.",al={"marcus jonathan coin","dalaran fountain coin marcus"}}},ang={["faction:Alliance"]="Marcus Jonathan embodies Stormwind's martial pride at the capital's gate.",["class:Warrior"]="As the supreme commander of Stormwind's gates and a Second War veteran, Jonathan represents the pinnacle of standard martial duty within the kingdom's infantry ranks."},kw={"general jonathan","lakeshire","magistrate solomon","marcus jonathan","reginald windsor","stormwind army","stormwind defense","valley of heroes"},rel={"subzone:valley-of-heroes","zone:stormwind","quest:120","npc:magistrate-solomon","subzone:lakeshire","topic:stormwind-army","topic:second-war","zone:redridge"},src={"General Marcus Jonathan"}}
E["npc:guard-howe"] = {t="npc",n="Guard Howe",z="redridge",s="Guard Howe is a town guardsman stationed near the southern foot of the Lakeshire bridge in the Redridge Mountains. Driven by a personal vendetta against the Blackrock orcs encroaching on the valley, he offers bounties to any adventurer willing to cut down the invaders.",h="Guard Howe is a town guardsman stationed near the southern foot of the Lakeshire bridge in the Redridge...",sec={{t="A Grudge on the Bridge",b="Positioned just south of the large stone bridge spanning Lake Everstill, Guard Howe stands watch over the heart of Lakeshire. Like many in the beleaguered town, he sees the encroaching Blackrock orcs as an existential threat to Redridge. Harbouring a bitter desire for revenge against the clan, Howe actively recruits passing mercenaries to hunt orcs in the eastern hills, offering pay in exchange for tangible proof of their defeat.",sp=0}},faq={{q="Who is Guard Howe?",a="Guard Howe is a human town guard stationed just south of the bridge in Lakeshire within the Redridge Mountains. He helps protect the settlement and directs capable fighters to strike back against the invading Blackrock orcs.",al={"guard howe","howe lakeshire","who is howe"}},{q="Why does Guard Howe want Blackrock orcs killed?",a="Howe harbors a personal vendetta against the Blackrock clan, who have pushed deep into the Redridge Mountains and placed Lakeshire under relentless pressure. He seeks vengeance and offers bounties to anyone who thins their ranks.",al={"why blackrock bounty","howe orcs","why does howe hate orcs"}},{q="Is Guard Howe related to anyone else in the region?",a="He shares a surname with Soloman Howe, suggesting they may be kin, though he keeps his focus strictly on his duties guarding the town and fighting the orcs.",al={"howe relatives","soloman howe relation"}}},ang={["faction:Alliance"]="Lakeshire receives little direct aid from Stormwind, leaving frontline guards like Howe to rely on visiting Alliance champions to keep the Blackrock orcs from overrunning the town."},kw={"blackrock bounty","blackrock orcs","guard howe","howe","lakeshire","redridge"},rel={"quest:128","subzone:lakeshire","zone:redridge"},src={"Guard Howe"}}
E["npc:lord-ello-ebonlocke"] = {t="npc",n="Lord Ello Ebonlocke",z="redridge",s="Lord Ello Ebonlocke is the mayor of Darkshire and the leader of its governing council, stationed inside the Darkshire Town Hall. Surrounded by darkness and creeping horrors, he struggles daily to maintain order and protect his besieged citizens despite receiving little aid from Stormwind.",h="Lord Ello Ebonlocke is the mayor of Darkshire and the leader of its governing council, stationed inside the...",sec={{t="A Beleaguered Mayor",b="Seated in the gloom of the Darkshire Town Hall, Lord Ello Ebonlocke bears the heavy burden of governing a settlement on the brink of ruin. Once part of the prosperous rural haven known as Grand Hamlet, Darkshire is now smothered by perpetual shadow and besieged by ravenous ghouls, skeletal abominations, and feral beasts. Ello presides over the Council of Darkshire, striving against impossible odds to keep the remnants of civilization functioning while Stormwind turns a blind eye to their plight.",sp=0},{t="A Divided Frontier",b="Because Stormwind's garrison refuses to spare soldiers for the borderlands, Darkshire relies almost entirely on local volunteer militias like the Night Watch, commanded by his relative, Althea Ebonlocke. When neighboring leaders like Magistrate Solomon of Lakeshire plead for reinforcements to combat Blackrock orcs, Lord Ebonlocke must make agonizing choices. As he solemnly explains to messengers from Redridge, Darkshire cannot spare a single blade: sending their guards beyond the forest's edge would leave their own homes to be instantly overrun by the surrounding evils.",sp=0},{t="Blind to the Hermit's Designs",b="Beyond patrolling the roads, Lord Ebonlocke frequently relies on wandering adventurers to handle peculiar matters around the woods. In his earnest desire to assist all residents of Duskwood, he coordinates communications with solitary figures like the hermit Abercrombie. Regrettably, Ebonlocke's lack of true insight into the hermit's cryptic writings blinds him to the grisly, stitched nightmare festering just beyond the town borders until it is nearly too late.",sp=1}},faq={{q="Who is Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke is the mayor of Darkshire and head of the Council of Darkshire. From his seat in the town hall, he oversees the defense, civic affairs, and survival of Duskwood's remaining human populace.",al={"who is ello","mayor of darkshire","ello ebonlocke lore"}},{q="How is he related to Commander Althea Ebonlocke?",a="Commander Althea Ebonlocke, the stalwart leader of the Night Watch, is Lord Ello's close kin. While he governs the civic and diplomatic affairs of Darkshire, she directs the militia that actively guards the settlement.",al={"althea ebonlocke relation","is althea ello's daughter"}},{q="Why does Lord Ebonlocke refuse to send troops to Lakeshire?",a="When Magistrate Solomon requests aid against the Blackrock orcs in Redridge, Lord Ebonlocke is forced to refuse. Darkshire is so hard-pressed by undead and monstrosities that stripping the town of guards would cause it to be completely overrun before the militia even reached the forest border.",al={"why no help for redridge","messenger to darkshire","magistrate solomon ello ebonlocke"}},{q="Where can Lord Ello Ebonlocke be found?",a="He is located inside the Darkshire Town Hall, which stands at the center of Darkshire in eastern Duskwood.",al={"ello ebonlocke location","where is mayor ebonlocke"}},{q="Why doesn't Stormwind send troops to help Lord Ebonlocke?",a="Stormwind is embroiled in internal political strife following King Varian Wrynn's disappearance. With the kingdom's resources constrained, the House of Nobles has largely abandoned the southern regions, forcing local leaders like Lord Ebonlocke to organize their own defenses.",al={"why won't stormwind help duskwood","stormwind neglect"}},{q="What is Lord Ebonlocke's involvement with Abercrombie?",a="Lord Ebonlocke assists in handling communications with the hermit Abercrombie, helping arrange translations of strange notes.",al={"ello abercrombie note","translate abercrombie's note"},sp=1}},ang={["faction:Alliance"]="Lord Ebonlocke represents the forgotten edges of the Alliance, where isolated mayors must lead their people through nightmare conditions without imperial aid.",["race:Human"]="For humans traveling from Stormwind, speaking with Lord Ebonlocke is a sobering reminder of how far the southern provinces have fallen into ruin and abandonment."},kw={"abercrombie","althea","council","darkshire","duskwood","ebonlocke","ello","lakeshire","mayor"},rel={"subzone:darkshire-town-hall","subzone:darkshire","zone:duskwood","npc:althea-ebonlocke","topic:night-watch","quest:145","npc:magistrate-solomon","npc:abercrombie"},src={"Lord Ello Ebonlocke"}}
E["npc:magistrate-solomon"] = {t="npc",n="Magistrate Solomon",z="redridge",s="Magistrate Solomon is the elected ruler and chief magistrate of Lakeshire, presiding over local affairs from the town hall. Besieged by Blackrock orcs and relentless gnoll clans, he spends his days frantically pleading for military aid from an indifferent and distracted Stormwind.",h="Magistrate Solomon is the elected ruler and chief magistrate of Lakeshire, presiding over local affairs from...",sec={{t="A Town Under Siege",b="Magistrate Solomon governs Lakeshire during the darkest hour in its recent history. The tranquil lakeside settlement is surrounded by hostility: Redridge and Shadowhide gnolls prowl the surrounding hills, while Blackrock orcs descend from the north in organized warbands. Solomon works alongside Marshal Marris to maintain civil order and muster a defense, but Lakeshire's local guards and militia are stretched to their absolute breaking point.",sp=0},{t="Appeals to Deaf Ears",b="Desperate to secure reinforcements, Solomon has dispatched messengers across the kingdom—pleading for aid from Westfall, Darkshire, and the capital of Stormwind itself. His petitions have yielded bitter disappointment. Westfall struggles under the grip of the Defias Brotherhood, Duskwood is consumed by its own creeping terrors, and Stormwind City refuses to deploy troops to the eastern frontier, leaving Lakeshire entirely to its own devices.",sp=0},{t="The Court's Refusal",b="When evidence emerges that the Blackrock orcs are allied with the black dragonflight, Solomon forwards the warning straight to Highlord Bolvar Fordragon. Despite the magnitude of the threat, royal advisor Lady Katrana Prestor dismisses Solomon's pleas as wild exaggeration. Constrained by her counsel and Stormwind's thinly spread forces, Bolvar declines to commit the Stormwind Army, offering Solomon only royal sanction to deputize independent mercenaries.",sp=1}},faq={{q="Who is Magistrate Solomon?",a="Magistrate Solomon is the elected civil leader of Lakeshire and presiding judge of the Court of Lakeshire. Operating from the town hall, he oversees local administrative matters and orchestrates the town's desperate defense against invading gnolls and orcs.",al={"magistrate solomon lore","who is solomon","lakeshire leader"}},{q="Why can't Stormwind send troops to help him?",a="Stormwind's military is already stretched thin across several troubled regions. When Solomon appeals for aid, Highlord Bolvar Fordragon is heavily influenced by royal advisor Lady Katrana Prestor, who questions Solomon's reports and actively discourages committing regular kingdom troops to Redridge.",al={"why no stormwind army","why won't stormwind help lakeshire","bolvar aid redridge"},sp=1},{q="Did Ironforge try to send help?",a="Yes. At Solomon's plea, King Magni Bronzebeard dispatched a relief contingent headed by Princess Moira Bronzebeard. However, the expedition never made it to Redridge, having been ambushed and captured in the Burning Steppes.",al={"dwarf reinforcements lakeshire","ironforge help redridge","moira bronzebeard lakeshire"},sp=1},{q="What threats are troubling Lakeshire?",a="Lakeshire faces simultaneous pressure from the Redridge and Shadowhide gnolls who terrorize the hills and roads, as well as the aggressive Blackrock orcs raiding south from Stonewatch Keep and the Burning Steppes.",al={"what is attacking lakeshire","redridge enemies","why is solomon worried"}},{q="Who works with Solomon to defend the town?",a="Solomon coordinates primarily with Marshal Marris, who directs the local town guard. Because regular reinforcements never arrive, the two officials are forced to enlist and deputize traveling adventurers to push back the encroaching threats.",al={"lakeshire defenders","marshal marris and solomon"}},{q="Why does Solomon send couriers to Darkshire and Westfall?",a="Knowing Stormwind's court has stalled, Solomon attempts to form mutual aid pacts with neighboring Alliance settlements. Unfortunately, Westfall is paralyzed by the Defias Brotherhood and Darkshire is overwhelmed by the undead and feral beasts, leaving neither able to spare a single defender.",al={"messenger to darkshire","messenger to westfall","solomon aid other towns"}}},ang={["faction:Alliance"]="Solomon's political abandonment illustrates the deep fractures within the Alliance of Stormwind, showing how outer provinces are left entirely to rely on freelance heroes.",["race:Human"]="For human travelers, speaking to Solomon reveals the grim state of the kingdom outside the safety of Elwynn Forest's inner borders.",["race:Dwarf"]="Dwarven visitors may find a tragic connection in Solomon's history, as Ironforge's effort to answer his distress call resulted in the ambush and capture of Princess Moira Bronzebeard."},kw={"blackrock","bolvar","lakeshire","magistrate solomon","marris","prestor","redridge","solomon","town hall"},rel={"subzone:lakeshire-town-hall","subzone:lakeshire","npc:marshal-marris","zone:redridge","topic:stormwind-army","quest:120","quest:169"},src={"Magistrate Solomon"}}
E["npc:marshal-marris"] = {t="npc",n="Marshal Marris",z="redridge",s="Marshal Marris is the beleaguered military officer commanding the town watch at Lakeshire. Stationed near the town's bridge, he coordinates defense operations against the massive Blackrock orc invasion pressing down from the heights of the Redridge Mountains. With Stormwind's army absent, he relies on visiting adventurers to blunt the horde's advances.",h="Marshal Marris is the beleaguered military officer commanding the town watch at Lakeshire.",sec={{t="A Town Under Siege",b="Lakeshire stands on the brink of collapse, caught between the gnolls to the west and the terrifying military might of the Blackrock clan to the east. Marshal Marris oversees the guard line at the town's primary bridge, but his resources are depleted and his soldiers are spread impossibly thin. With the kingdom of Stormwind withholding royal reinforcements, Marris carries the heavy burden of keeping the township from being overwhelmed by brute force.",sp=0},{t="Breaking the Blackrock Vanguard",b="Recognizing that defense alone will not save Redridge, Marris orchestrates decisive offensive strikes against the orc encampments. He directs mercenaries to cull the Blackrock warriors, dismantle their shadowcasters, and ultimately hunt down Tharil'zun, the menacing commander entrenched inside the ruins of Stonewatch Keep. His orders aim to break the command structure of the orcs before an all-out assault crushes Lakeshire completely.",sp=0}},faq={{q="Who is Marshal Marris?",a="Marshal Marris is the senior military commander in charge of defending Lakeshire. He can be found standing guard near the western end of the town's bridge, trying to keep the settlement fortified against hostile incursions.",al={"marris","marshal marris lore","who is the guard at lakeshire bridge"}},{q="Why is Marshal Marris hiring independent adventurers?",a="The Kingdom of Stormwind has failed to send adequate garrison reinforcements to the Redridge Mountains, leaving Lakeshire's local guard hopelessly outnumbered. Facing gnoll warbands and an entrenched invasion of Blackrock orcs, Marris is forced to enlist mercenary heroes to carry out critical strikes.",al={"why does marris need help","why no stormwind army"}},{q="What threats is Marshal Marris fighting against?",a="While gnolls plague the outskirts, Marris is primarily focused on the Blackrock orcs who have seized Stonewatch Keep. These orcs, commanded by Tharil'zun and bolstered by shadow magic, represent an imminent existential threat to Lakeshire and the greater kingdom.",al={"marris enemies","who is attacking lakeshire"}},{q="Is Marshal Marris related to Nathanos Marris?",a="They share a surname common to the human kingdoms of Lordaeron and Stormwind, but no official record confirms a direct familial relationship between Marshal Marris in Redridge and the famed ranger Nathanos Marris from the north.",al={"is marris related to nathanos","marris family"}},{q="What is Marris's plan to defeat the Blackrock clan?",a="Marris implements a war of attrition and decapitation. He directs combatants to cull the Blackrock infantry, gather magical components from their shadow magic users, and breach Stonewatch Keep to execute their leader, Tharil'zun.",al={"marris plan","how to beat blackrock orcs"}},{q="Where can Marshal Marris be found?",a="Marris is stationed in Lakeshire within the Redridge Mountains, positioned prominently along the bridge near the center of town.",al={"marris location","where is marshal marris"}}},ang={["faction:Alliance"]="Marshal Marris embodies the plight of the rural Alliance territories, left vulnerable by Stormwind's political paralysis and forced to fight for survival on their own.",["race:Human"]="For humans of the kingdom, Marris represents the stoic, beleaguered frontier guard holding the line against the remnants of the Old Horde.",["class:Warrior"]="Marris appreciates straightforward martial discipline, sending capable front-line fighters into the jaws of Stonewatch to trade blows with seasoned Blackrock veterans."},kw={"blackrock","bridge","lakeshire","marris","marshal marris","redridge","stonewatch","tharil'zun"},rel={"subzone:lakeshire","zone:redridge","quest:19","quest:20","quest:115","quest:219"},src={"Marshal Marris"}}
E["npc:martie-jainrose"] = {t="npc",n="Martie Jainrose",z="redridge",s="Martie Jainrose is Lakeshire's local herbalist, tending to her garden along the edge of Lake Everstill in the Redridge Mountains. Beside cultivating remedies and flowers for the beleaguered town, she contends with wild beasts trampling her plots and harbors a quiet affection for Guard Parker.",h="Martie Jainrose is Lakeshire's local herbalist, tending to her garden along the edge of Lake Everstill in the...",sec={{t="A Garden by the Lake",b="Residing in Lakeshire, Martie Jainrose works diligently as the settlement's resident herbalist. Even as Blackrock orcs, gnolls, and local brigands threaten the region, Martie focuses on keeping the town supplied with fresh herbs and floral arrangements. Her daily labors are often disrupted by local wildlife—most notably the monstrous boar Bellygrub, who frequently ravages her prized garden beds. Beyond her herbal pursuits, Martie is known to hold a gentle fondness for Guard Parker, occasionally sending bouquets of handpicked daffodils to brighten his watchful watch over the town.",sp=0}},faq={{q="Who is Martie Jainrose?",a="Martie Jainrose is a human herbalist living in Lakeshire within the Redridge Mountains. She tends a garden beside Lake Everstill, cultivating flora and preparing herbal remedies for the local residents.",al={"martie jainrose","who is martie","lakeshire herbalist"}},{q="What trouble does Martie have with the local wildlife?",a="A massive and notoriously stubborn wild boar named Bellygrub has taken to raiding her garden plots, trampling her delicate plantings and eating her herbs before she can harvest them.",al={"martie boar problem","bellygrub garden","who is destroying her garden"}},{q="Who does Martie fancy in Lakeshire?",a="Martie has romantic feelings for Guard Parker, one of the town guards stationed nearby. She frequently arranges bunches of fresh daffodils to be delivered to him while he stands watch.",al={"martie crush","martie guard parker","delivering daffodils romance"}}},ang={["profession:Herbalism"]="For practicing herbalists traveling through Redridge, Martie represents a familiar kinship, tending fragile flora despite the harsh predations of wild boars and encroaching enemies.",["faction:Alliance"]="Martie's perseverance in Lakeshire reflects the resilience of Redridge's folk, striving to maintain ordinary domestic life even while Stormwind leaves the town largely to fend for itself."},kw={"bellygrub","daffodils","guard parker","herbalist","lakeshire","martie jainrose","redridge"},rel={"subzone:lakeshire","zone:redridge","quest:131","quest:130"},src={"Martie Jainrose"}}
E["npc:nida"] = {t="npc",n="Nida",z="redridge",s="Nida is a young human girl living in the lakeside town of Lakeshire in the Redridge Mountains. Distraught after dropping a cherished gift from her father into the lake, she spends her time crying along the town's docks.",h="Nida is a young human girl living in the lakeside town of Lakeshire in the Redridge Mountains.",sec={{t="A Child's Lost Keepsake",b="Amid the mounting threats of gnoll invasions and Blackrock orc warbands pressing down on Lakeshire, the children of the town still face everyday childhood troubles. Nida accidentally dropped a necklace given to her by her father into the murky waters of Lake Everstill. Terrified that her father will be angry with her, the distraught girl waits by the town pier in tears, hoping someone brave enough will plunge into the lake to retrieve it.",sp=0}},faq={{q="Who is Nida?",a="Nida is a young human child residing in Lakeshire in the Redridge Mountains, often found tearfully wandering near the docks.",al={"who is nida","nida lakeshire","crying girl lakeshire"}},{q="Why is Nida crying?",a="Nida lost a precious necklace that her father bought for her. It slipped into the waters of Lake Everstill, and she is terrified of her father's anger once he discovers it is missing.",al={"why is she crying","why is nida sad","nida crying sound"}},{q="Who is trying to help her find the necklace?",a="Her playmate Shawn notices her distress and asks passing adventurers to dive into Lake Everstill to retrieve the sunken necklace for her.",al={"who helps nida","nida friend","who gives nida quest"}},{q="Where is the lost necklace located?",a="The necklace rests beneath the surface of Lake Everstill, submerged near the town's docks where Nida dropped it.",al={"where is nidas necklace","necklace location lake everstill"}}},ang={["faction:Alliance"]="Even as the Redridge Mountains struggle with larger regional crises, helping Nida recovers a small sense of warmth and innocence for the troubled residents of Lakeshire."},kw={"child","lake everstill","lakeshire","necklace","nida","redridge","shawn"},rel={"quest:3741","subzone:lakeshire","zone:redridge"},src={"Nida"}}
E["npc:smith-argus"] = {t="npc",n="Smith Argus",z="redridge",s="Smith Argus is the resident blacksmith and trainer stationed in the heart of Goldshire in Elwynn Forest. From his open-air forge near the Lion's Pride Inn, he repairs traveler gear, teaches novice smiths their fundamentals, and coordinates with craftsmen across southern Azeroth. His network ties Goldshire's local trade directly to logistical hubs like Stormwind and distant frontiers like Redridge.",h="Smith Argus is the resident blacksmith and trainer stationed in the heart of Goldshire in Elwynn Forest.",sec={{t="The Anvil of Goldshire",b="Situated just outside the Lion's Pride Inn, Smith Argus maintains one of the busiest anvils in Elwynn Forest. While Goldshire faces growing perils from nearby gnolls, kobolds, and Defias bandits, Argus keeps local militia and passing adventurers properly equipped. In addition to mending dented armor and forging sturdy implements, he serves as an apprentice blacksmithing trainer, initiating fledgling craftsmen into the fundamentals of working copper and bronze.",sp=0},{t="Inter-Town Trade and Demands",b="Argus is not an isolated village smith; his workshop is a vital link in the Kingdom of Stormwind's regional supply chain. When craftsmen in neighboring settlements require specialized gear or raw materials, they look to Goldshire's central position. Farrier Verner Osgood in Redridge relies on Argus for shipments of crafted horseshoes to keep pack animals and cavalry moving, while metalworkers in Stormwind's Dwarven District regularly coordinate deliveries through him via the local gryphon couriers.",sp=0}},faq={{q="Where can I find Smith Argus?",a="Smith Argus is located in Goldshire in central Elwynn Forest. You can find him working at the outdoor anvil and forge set up behind the armor shop, near the Lion's Pride Inn.",al={"argus location","where is smith argus","smith argus elwynn"}},{q="What services does Smith Argus provide?",a="Argus acts as an Apprentice Blacksmithing trainer, teaching new players the basics of metallurgy and early metal recipes. He also offers full equipment repair services and sells blacksmithing supplies such as mining picks and smithing hammers.",al={"what does argus teach","argus trainer","goldshire blacksmith trainer"}},{q="Why does a blacksmith in Redridge send me to Smith Argus?",a="Verner Osgood, a craftsman in Lakeshire, has a high demand for horseshoes to keep supply wagons and mounts moving against the Blackrock orc threat. He contracts Argus in Goldshire to forge and supply the necessary iron footwear.",al={"the price of shoes quest","verner horseshoes","why argus horseshoes"}},{q="What is Argus's connection to Stormwind City?",a="Argus coordinates supply runs with dwarven smiths in Stormwind City, such as Elmore Smith. He often relies on the local Goldshire gryphon master to send and receive urgent dispatches and heavy shipments quickly.",al={"elmore's task","stormwind gryphon argus"}},{q="Can Smith Argus train advanced or expert blacksmithing?",a="No. Argus only teaches Apprentice Blacksmithing. To learn Journeyman or Expert techniques, aspiring smiths must seek more advanced masters in larger settlements or the Dwarven District of Stormwind City.",al={"argus expert blacksmith","how high can argus train"}},{q="Does Smith Argus belong to any particular guild?",a="Argus is a loyal subject of the Kingdom of Stormwind and a member of the local craftsmen community serving the Alliance in Elwynn Forest.",al={"argus faction","argus guild"}}},ang={["profession:Blacksmithing"]="For Alliance characters starting in Elwynn, Argus is often the very first teacher of the forge, providing initial recipes for rough copper gear and essential utility items.",["profession:Mining"]="Miners frequent Argus's forge not only to purchase basic mining picks, but to utilize his anvil and forge for smelting raw copper nuggets into usable ingots.",["race:Human"]="Argus represents the hardworking tradesmen who keep Elwynn running despite the kingdom's broader political neglect and bandit unrest."},kw={"blacksmith","elwynn forest","forge","goldshire","horseshoes","lion's pride","smith argus","trainer","verner osgood"},rel={"subzone:goldshire","zone:elwynn","quest:118","quest:119","quest:1097","quest:6181","zone:redridge"},src={"Smith Argus"}}
E["npc:verner-osgood"] = {t="npc",n="Verner Osgood",z="redridge",s="Verner Osgood is the resident blacksmith of Lakeshire, stationed just outside the town smithy. Balancing local civilian trade with the crushing demands of the Stormwind military, he works tirelessly to keep horses shod and defenders armed amid relentless gnoll raids.",h="Verner Osgood is the resident blacksmith of Lakeshire, stationed just outside the town smithy.",sec={{t="The Anvil of Lakeshire",b="Standing by the forge in central Lakeshire, Verner Osgood represents the strained industrial backbone of the Redridge Mountains. Tasked with crafting basic supplies like horseshoes for local mounts, Verner finds his stock constantly co-opted to manufacture weapons and armor for the Stormwind Guard. With the kingdom stretching its borders thin and local garrisons lacking supplies, independent smiths like Verner must carry the logistical burden of the realm's defense.",sp=0},{t="A Plague of Gnolls",b="Verner's troubles extend far beyond a shortage of iron. The gnolls infesting the Redridge hills routinely ambush livestock, carrying off working horses whenever they stray outside the town perimeter. Driven to exasperation by the destruction of his livelihood, Verner actively recruits traveling adventurers to cull the marauding packs and hunt down their ferocious packleader, Yowler.",sp=0}},faq={{q="Who is Verner Osgood?",a="Verner Osgood is the local blacksmith operating the forge in Lakeshire. He handles metalwork and horse shoeing for the town while attempting to meet the heavy equipment demands of the local garrison.",al={"verner osgood","lakeshire blacksmith","who is verner"}},{q="Why is Verner low on horseshoes and iron?",a="The town's supply of iron is continually requisitioned to forge weapons and armor for the Stormwind Guard stationed in Redridge, leaving Verner with barely enough metal to care for the local horses.",al={"verner out of iron","price of shoes quest lore","why no horseshoes"}},{q="What problem does Verner have with the gnolls?",a="Gnoll raiding parties roam closely around Lakeshire, snatching away Verner's horses whenever they wander away from town. He seeks retribution and safety by hiring adventurers to eliminate the beasts.",al={"verner gnoll problem","why does verner hate gnolls"}},{q="Who is Yowler and why does Verner want him dead?",a="Yowler is the menacing leader of the local gnoll packs in the hills. Verner wants him slain to break the coordination of the raiders who terrorize the township and slaughter his horses.",al={"who is yowler","verner yowler quest"}},{q="What is Verner's connection to Magistrate Solomon?",a="Verner operates under the civic authority of Magistrate Solomon in Lakeshire, balancing civilian craft with the civic and martial needs commanded by the magistrate's beleaguered administration.",al={"verner magistrate solomon","verner and the town leadership"}},{q="Does Verner have family in Stormwind?",a="He shares a surname with several other tradesmen in the Kingdom of Stormwind, such as Donal and Basil Osgood, suggesting an established lineage of working-class human craftsmen across the region.",al={"verner relatives","osgood family"}}},ang={["profession:Blacksmithing"]="Verner embodies the gritty reality of rural smithing, balancing civilian shoeing with the harsh quotas demanded by garrison defense.",["faction:Alliance"]="Towns like Lakeshire depend on local craftsmen like Verner to survive as Stormwind's military aid remains dangerously constrained.",["race:Human"]="Osgood represents the enduring resilience of the Kingdom of Stormwind's common folk, holding ground against gnolls and shortages alike."},kw={"blacksmith","gnolls","horses","lakeshire","magistrate solomon","redridge","verner osgood","yowler"},rel={"subzone:lakeshire","zone:redridge","quest:118","quest:126","quest:124","npc:magistrate-solomon","topic:stormwind-guard","topic:gnoll"},src={"Verner Osgood"}}
E["npc:watch-captain-parker"] = {t="npc",n="Watch Captain Parker",z="redridge",s="Guard Parker is a vigilant town guardsman stationed at the Three Corners outpost in the Redridge Mountains. Tasked with patrolling the roads and monitoring aggressive gnoll packs, he serves as an early line of defense for travelers heading into Lakeshire.",h="Guard Parker is a vigilant town guardsman stationed at the Three Corners outpost in the Redridge Mountains.",sec={{t="On Guard at Three Corners",b="Positioned at the vital junction known as Three Corners, Parker keeps watch over the roads connecting Elwynn Forest, Duskwood, and Redridge. With Stormwind's military resources stretched thin and little official reinforcement reaching the region, solo watchmen like Parker carry the burden of keeping the crossroads clear of bandits, prowling predators, and raiding gnolls.",sp=0},{t="Assessing the Gnoll Threat",b="Parker's immediate concern is the surging gnoll population in southern Redridge. As packs encroach closer toward the roadway, he enlists able-bodied travelers to scout their numbers and thin their ranks. The Redridge pack's growing boldness poses an immediate danger to supply convoys and refugees seeking shelter in Lakeshire.",sp=0},{t="A Touch of Warmth",b="Life on a lonely roadside post can be grim, but small kindnesses still find their way to Three Corners. Darcy, the server from the Lakeshire Inn, periodically ensures Parker receives a warm lunch. Touched by the gesture, Parker enlists the aid of passing adventurers to deliver freshly gathered wild flowers back to her in Lakeshire as a token of his appreciation.",sp=0}},faq={{q="Where is Guard Parker located?",a="Parker is stationed at Three Corners, a roadway intersection situated in southwestern Redridge Mountains near the border crossings to Duskwood and Elwynn Forest.",al={"parker location","where is parker","find guard parker"}},{q="Why is Parker stationed all the way out at Three Corners?",a="He is tasked with patrolling the southern roads and keeping a watchful eye on encroaching gnoll packs to keep regional travel and supply routes open into Lakeshire.",al={"parker duties","why is parker alone","three corners guard"}},{q="What threats is Parker monitoring in Redridge?",a="Parker keeps tabs on the encroaching Redridge gnoll pack threatening the highway, while staying alert to the broader dangers facing the zone, including Blackrock orcs at Stonewatch and Shadowhide gnolls near the Tower of Ilgalar.",al={"redridge threats","what enemies are near parker","gnoll threat redridge"}},{q="What is Parker's relationship with Darcy?",a="Darcy works at the Lakeshire Inn and frequently sends hot meals to Parker at his remote post. In return, Parker sends back wildflowers through passing travelers to express his gratitude and affection.",al={"darcy and parker","who is darcy","a free lunch quest lore"}},{q="Why doesn't Parker receive reinforcements from Stormwind?",a="With King Varian Wrynn missing and the capital caught up in internal political paralysis, Stormwind has largely left Redridge to fend for itself, forcing local guards and magistrates to rely on roaming adventurers.",al={"why no stormwind army","stormwind aid redridge","parker reinforcements"}},{q="What quests does Guard Parker offer?",a="Parker asks adventurers to help cull the aggressive gnolls encroaching on the roads and helps arrange a delivery of fresh flowers back to Darcy at the Lakeshire Inn.",al={"parker quests","quests from parker"}}},ang={["faction:Alliance"]="Parker represents the strained, solitary frontier defense of an Alliance that cannot spare troops to protect its own borders.",["race:Human"]="For humans of the kingdom, Parker is a reminder of the ordinary sentries striving to hold the kingdom's outlying villages together during a national crisis.",["profession:Herbalism"]="Parker's search for fresh blooms to send to Darcy highlights the quiet value of the local flora blooming across the Redridge hillsides."},kw={"darcy","gnolls","guard parker","lakeshire","parker","redridge","three corners","watch captain parker"},rel={"subzone:three-corners","zone:redridge","subzone:lakeshire","subzone:lakeshire-inn","quest:129","quest:130","quest:244","topic:gnoll"},src={"Watch Captain Parker"}}
E["quest:115"] = {t="quest",n="Shadow Magic",z="redridge",s="Shadow Magic is a desperate task given by Marshal Marris to disrupt the dark arts bolstering the Blackrock invasion of Redridge. Blackrock shadowcasters have brought demon-tainted midnight orbs to the battlefield, weaponizing dark energies against the beleaguered defenders of Lakeshire. Securing and destroying these cursed relics is vital to holding the town's defensive line.",h="Shadow Magic is a desperate task given by Marshal Marris to disrupt the dark arts bolstering the Blackrock...",sec={{t="A Sinister Arsenal",b="While brute force has always been the hallmark of the Blackrock clan, their recent incursions into the Redridge Mountains display a far more insidious threat. The invaders have bolstered their ranks with shadowcasters wielding dark powers. These casters do not rely on sorcery alone; they channel their fel and shadow energies through demon-tainted artifacts known as midnight orbs. The artifacts have inflicted terrible losses upon the local town militia, tilting an already desperate war further in favor of the invaders.",sp=0},{t="Containing the Taint",b="Marshal Marris, coordinating Lakeshire's strained defense from the town center, understands that ordinary steel cannot easily overcome dark relics. Allowing the Blackrock orcs to retain their midnight orbs risks the complete collapse of Redridge's eastern borders. By ordering adventurers to slay the shadowcasters and seize the orbs, Marris seeks not to repurpose this dangerous magic, but to take it straight to the furnace or arcane authorities in Stormwind where the demonic taint can be safely destroyed.",sp=0}},faq={{q="What are midnight orbs?",a="Midnight orbs are demon-tainted conduits carried by Blackrock shadowcasters. They focus dark magic to inflict devastating blows against the mortal defenders of Redridge.",al={"midnight orb","what is a midnight orb","what do midnight orbs do"}},{q="Why does Marshal Marris want these orbs?",a="Marshal Marris wants the orbs removed from the battlefield entirely to cripple the offensive power of the Blackrock shadowcasters. He intends to have the demonic relics safely disposed of and destroyed.",al={"why collect midnight orbs","marris orbs","marris plan for orbs"}},{q="Who are the Blackrock shadowcasters?",a="They are spellcasters among the Blackrock orcs who practice shadow and fel-tainted magic, providing magical artillery and curses to support the clan's brute warriors.",al={"blackrock shadowcasters","who uses shadow magic","blackrock casters"}},{q="Where are the shadowcasters found?",a="Blackrock shadowcasters are deployed in the camps and fortified positions of the Blackrock clan throughout northeastern Redridge Mountains.",al={"where are shadowcasters","shadowcaster location","blackrock shadowcaster camps"}},{q="Will Lakeshire study or use the orbs?",a="No. Marshal Marris considers them dangerous and demon-tainted, stating firmly that the world would be better off without them. His explicit goal is their immediate destruction.",al={"will lakeshire use the orbs","can the alliance use the orbs","are orbs useful"}},{q="Why is demonic magic appearing in Redridge?",a="The Blackrock clan has a long history of consorting with dark and fel entities, dating back to the Old Horde. Their spellcasters continue to utilize demonic relics and shadow magic to bolster their conquests.",al={"why demons in redridge","blackrock demonic taint","fel in redridge"}}},ang={["faction:Alliance"]="Lakeshire stands on the brink of overrun with virtually no reinforcements from Stormwind; depriving the Blackrock clan of their dark artillery is crucial for the survival of the region.",["class:Warlock"]="The midnight orbs demonstrate the enduring fel roots of the Blackrock clan, offering warlocks a glimpse into the raw demonic channeling wielded by orcish spellcasters.",["class:Paladin"]="Confronting shadowcasters and securing demon-tainted relics directly fulfills the holy duty to purge demonic corruption from the mortal realm."},kw={"blackrock orcs","demon-tainted","lakeshire","marshal marris","midnight orb","redridge","shadow magic","shadowcaster"},rel={"npc:marshal-marris","zone:redridge","subzone:lakeshire"},m={start="Marshal Marris",level="23",faction="Alliance",id=115},src={"Shadow Magic"}}
E["quest:116"] = {t="quest",n="Dry Times",z="redridge",s="Dry Times is a task given by Barkeep Daniels of Lakeshire to resupply the town inn with liquor during an ongoing siege. With the Blackrock orc invasion severing trade routes, Daniels relies on adventurous couriers to fetch specialty alcohol from across Stormwind's territories.",h="Dry Times is a task given by Barkeep Daniels of Lakeshire to resupply the town inn with liquor during an...",sec={{t="A Town Under Siege",b="Lakeshire sits on the front line of an aggressive push by the Blackrock clan orcs descending from Stonewatch Keep. With regular supply lines choked and the roads unsafe, the town's local innkeeper, Barkeep Daniels, faces an imminent crisis of empty casks. To keep spirits high among frightened villagers and beleaguered town guards, he turns to outside travelers to bypass the road blockades and restock his shelves.",sp=0},{t="A Grand Tour of the Kingdom",b="Restocking Daniels's cellar is no simple delivery; it requires an ambitious journey across the breadth of the kingdom of Stormwind. A courier must secure a cask of Merlot from the capital itself, Sweet Rum from the Lion's Pride Inn in Goldshire, potent Moonshine from gloomy Darkshire in Duskwood, and a special keg of Thunderbrew Lager brewed by Grimbooze Thunderbrew out in the hills of Westfall.",sp=0}},faq={{q="Why is Lakeshire running out of alcohol?",a="The Blackrock orc invasion of Redridge has completely disrupted regular trade and supply caravans. Barkeep Daniels's normal shipments are long overdue, threatening to leave his tavern completely dry while the town is under immense wartime stress.",al={"why dry times","why no booze lakeshire","barkeep daniels problem"}},{q="Where do I find all the drinks Barkeep Daniels needs?",a="You must collect four items from across the kingdom: Merlot from the taverns in Stormwind City, Sweet Rum from Goldshire in Elwynn Forest, Moonshine from Darkshire in Duskwood, and a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the hills of Westfall.",al={"dry times drink locations","where to buy merlot moonshine rum","where to get drinks for daniels"}},{q="Who is Grimbooze Thunderbrew?",a="Grimbooze Thunderbrew is a dwarven brewer residing in the hills of Westfall. Barkeep Daniels considers his Thunderbrew Lager essential stock, but getting it requires completing a separate errand for Grimbooze to secure a fresh keg.",al={"grimbooze location","where is grimbooze thunderbrew","westfall thunderbrew"}},{q="Who is Barkeep Daniels?",a="Daniels is the barkeep running the inn in Lakeshire. Desperate to keep his tavern stocked and his patrons pacified amidst the looming threat of the Blackrock orcs, he hires travelers to personally retrieve supplies.",al={"barkeep daniels","lakeshire innkeeper","who gives dry times"}},{q="Why does Daniels need drinks from so many different regions?",a="Daniels caters to a diverse crowd of refugees, local militiamen, and passing adventurers, requiring a wide variety of stock ranging from dwarven lager to fine capital wine and potent regional spirits from Duskwood and Elwynn.",al={"why so many drinks","why visit duskwood and westfall"}},{q="What reward does Barkeep Daniels give for making the run?",a="In addition to reimbursing your travel expenses with a purse of coins, Daniels presents a hand-crafted cloak sewn by his wife as thanks for braving the contested roads of the realm.",al={"dry times reward","what does daniels give"}}},ang={["faction:Alliance"]="This errand illustrates how the breakdown of road security in Redridge affects daily life, requiring Alliance couriers to knit together severed trade routes between Stormwind, Elwynn, Westfall, Duskwood, and Redridge.",["race:Dwarf"]="Even during an orc invasion, human taverns rely on dwarven brewing expertise, sending couriers all the way to Westfall to secure Grimbooze Thunderbrew's renowned lager."},kw={"barkeep daniels","dry times","grimbooze thunderbrew","lakeshire","merlot","moonshine","redridge","sweet rum","thunderbrew lager"},rel={"npc:barkeep-daniels","quest:117","npc:grimbooze-thunderbrew","subzone:lakeshire","zone:redridge","subzone:darkshire","subzone:goldshire","zone:westfall"},m={start="Barkeep Daniels",level="15",faction="Alliance",id=116},src={"Dry Times"}}
E["quest:118"] = {t="quest",n="The Price of Shoes",z="redridge",s="Verner Osgood, the smith in Lakeshire, has depleted his supply of iron patching together equipment for the beleaguered town guard. With no metal left to shoe the local horses, he sends a courier across Elwynn Forest to enlist help from Smith Argus in Goldshire.",h="Verner Osgood, the smith in Lakeshire, has depleted his supply of iron patching together equipment for the...",sec={{t="A Frontier Strained to the Limit",b="Lakeshire sits directly in the crosshairs of gnolls, orcs, and murlocs, yet Stormwind offers precious little reinforcement. The local garrison has to fight daily to keep the township from falling, and that relentless combat wears gear down quickly. Verner Osgood spends nearly every waking hour repairing dented breastplates, reshaping dulled swords, and keeping the town guards clad in iron, exhausting his raw materials in the process.",sp=0},{t="Supply Lines to Elwynn",b="When a frontier settlement runs completely out of iron, even mundane tasks ground to a halt. Without horseshoes, messengers cannot ride swift relays and draft animals cannot haul supplies across the rocky paths of Redridge. Verner must swallow his pride and appeal to the heartland, sending travelers west down the Three Corners road to Goldshire, where Smith Argus still enjoys regular access to the royal realm's deep mineral stores.",sp=0}},faq={{q="Why is Verner out of iron?",a="The local guards in Lakeshire face constant assaults from Redridge's hostile wildlife, gnolls, and Blackrock orcs. Verner has been pouring all his iron stock into repairing their battered armor and weapons, leaving none behind for civilian needs.",al={"why no iron","verner out of metal","lakeshire iron shortage"}},{q="Who is Smith Argus?",a="Smith Argus is the resident blacksmith of Goldshire in Elwynn Forest. Located near the bustling center of the kingdom, his forge has far easier access to raw ingots and supplies than frontier towns like Lakeshire.",al={"argus goldshire","who is argus","blacksmith in goldshire"}},{q="Why does Lakeshire lack supplies from Stormwind?",a="Stormwind's rulers are entangled in political inertia while King Varian Wrynn remains missing. With the House of Nobles withholding troops and funds, frontier towns like Lakeshire are largely left to fend for themselves using whatever regional trade they can muster.",al={"why no help from stormwind","lakeshire ignored","stormwind neglect"}},{q="Why are horseshoes so critical in Redridge?",a="Redridge's rocky, unforgiving terrain quickly destroys the hooves of unshod beasts. Without shoes, messenger couriers, supply wagons, and patrol mounts become lame, cutting Lakeshire off from the rest of the kingdom.",al={"why need horseshoes","why shoes matter"}},{q="What happens after reaching Smith Argus?",a="Argus accepts Verner's note and provides a shipment of horseshoes for you to carry back to Lakeshire, opening up further tasks to help secure the embattled settlement.",al={"next quest","what after argus"}},{q="Where is Smith Argus located in Goldshire?",a="He can be found working the outdoor forge near the Lion's Pride Inn in Goldshire, just off the main road through Elwynn Forest.",al={"where is argus","argus location"}}},ang={["profession:Blacksmithing"]="The request highlights the harsh material realities of frontier smithing, where a craftsman's forge must prioritize surviving soldiers over ordinary farmsteads.",["faction:Alliance"]="Lakeshire's reliance on Goldshire underscores how thinly stretched the kingdom's logistics are under the regency in Stormwind."},kw={"elwynn","goldshire","horseshoes","iron","lakeshire","redridge","smith argus","verner osgood"},rel={"npc:verner-osgood","npc:smith-argus","quest:119","zone:redridge","subzone:goldshire","topic:stormwind-guard","topic:stormwind-kingdom","quest:124"},m={start="Verner Osgood",["end"]="Smith Argus",level="18",faction="Alliance",id=118},src={"The Price of Shoes"}}
E["quest:120"] = {t="quest",n="Messenger to Stormwind",z="redridge",s="Magistrate Solomon of Lakeshire is desperate for military aid as gnolls and Blackrock orcs encircle the town. Unable to spare garrison troops, he dispatches an adventurer to carry 'The State of Lakeshire' directly to General Marcus Jonathan in Stormwind City.",h="Magistrate Solomon of Lakeshire is desperate for military aid as gnolls and Blackrock orcs encircle the town.",sec={{t="A Cry Across the Mountains",b="Lakeshire stands on the brink of collapse. Gnoll packs contest every road, Blackrock orcs raid from the north, and the local guardsmen are stretched beyond their limits. Magistrate Solomon cannot afford to send fighting men on a days-long ride to the capital, leaving an independent traveler to carry his official plea for regular troops to the city gates.",sp=0},{t="Bureaucracy and the High Seat",b="Delivering the magistrate's report brings an adventurer face-to-face with General Marcus Jonathan, commander of Stormwind's defense. While Jonathan respects Solomon's leadership and acknowledges the urgency, army protocol prevents him from mobilizing without a royal directive. The defense of Redridge must await formal consultation with the young King Anduin and the regency council.",sp=0}},faq={{q="Why does Magistrate Solomon need a messenger?",a="Lakeshire is under constant siege from Blackrock orcs and gnolls. Every local guardsman is needed to defend the town and hold the bridge, so Solomon entrusts traveling adventurers with his urgent appeals for aid.",al={"why send me","why a messenger","solomon messenger"}},{q="What is in 'The State of Lakeshire' report?",a="It is an official accounting of the crisis engulfing the Redridge Mountains, detailing the mounting enemy numbers, casualties, and the town's imminent fall if regular soldiers are not sent from the capital.",al={"state of lakeshire","solomon report","what is the letter"}},{q="Who is General Marcus Jonathan?",a="General Marcus Jonathan is the commander of the Stormwind City Guard and high-ranking leader within the Stormwind Army. He monitors the city gates and reports directly to Highlord Bolvar Fordragon and the crown.",al={"marcus jonathan","who is the general","general of stormwind"}},{q="Why doesn't General Jonathan send soldiers right away?",a="General Jonathan cannot deploy the army on his own authority. He must bring Solomon's report before the King and the regency council to obtain an official royal mandate before any troops can march.",al={"why no troops","where are reinforcements","jonathan response"}},{q="Is the road between Lakeshire and Stormwind safe?",a="No. The paths through Redridge and into Elwynn are plagued by aggressive gnoll bands and Defias highwaymen, making the journey perilous for lone messengers.",al={"road to stormwind","safe travel","redridge road"}},{q="Does Stormwind end up sending help?",a="Political inertia and turmoil in the capital delay any real army response, leaving Lakeshire and its magistrate to rely almost entirely on mercenaries and volunteers.",al={"do reinforcements arrive","help for lakeshire"},sp=1}},ang={["faction:Alliance"]="This mission exposes the growing strain between the prosperous capital and the neglected border settlements fighting for survival on the kingdom's edges.",["race:Human"]="Redridge is ancestral Stormwind territory; seeing fellow humans abandoned behind bureaucratic red tape stings any patriot of the kingdom.",["class:Paladin"]="Bearing cries of the desperate to leaders paralyzed by court politics tests the core virtues of duty, protection, and righteous action."},kw={"general marcus jonathan","lakeshire","magistrate solomon","messenger to stormwind","redridge mountains","reinforcements","stormwind army","the state of lakeshire"},rel={"npc:magistrate-solomon","npc:general-marcus-jonathan","subzone:lakeshire","zone:redridge","topic:stormwind-army","topic:stormwind-kingdom"},m={start="Magistrate Solomon",["end"]="General Marcus Jonathan",level="14",faction="Alliance",id=120},src={"Messenger to Stormwind"}}
E["quest:122"] = {t="quest",n="Underbelly Scales",z="redridge",s="Verner Osgood needs black dragon whelp underbelly scales to clear a trade debt with Smith Argus of Goldshire. Gathering these materials requires hunting the young drakes wandering the crags south of Lakeshire. Securing the scales settles Verner's account and provides enough raw hide to craft a piece of gear.",h="Verner Osgood needs black dragon whelp underbelly scales to clear a trade debt with Smith Argus of Goldshire.",sec={{t="A Frontier Debt",b="Running a forge on the outskirts of Lakeshire requires scarce supplies, and Verner Osgood frequently trades with craftsmen beyond the Redridge Mountains. After receiving a shipment of horseshoes from Smith Argus in Goldshire, Verner finds himself short on conventional coin. Instead, Argus demands payment in valuable dragonhide: specifically, the softer, highly prized underbelly scales of the black dragon whelps nesting in the region. Without them, Verner risks having collectors sent out from Elwynn Forest to claim what he owes.",sp=0},{t="Brood of the Black Flight",b="The presence of black dragon whelps in the Redridge Mountains is an alarming sign for the local defenders. While gnolls and orcs openly contest the roads, the brood of the Black Dragonflight nests in the high peaks and wanders the skies south of Lake Everstill. The underbelly scales of these young predators are tough yet pliable, making them prized crafting components for armorers, smiths, and leatherworkers across the kingdom who are daring enough to harvest them.",sp=0}},faq={{q="Why does Verner Osgood need dragon scales?",a="Verner owes Smith Argus of Goldshire for a shipment of horseshoes. Argus demanded payment in underbelly scales taken from black dragon whelps rather than regular coin. Verner needs the scales delivered quickly before Argus sends collectors to enforce the debt.",al={"why dragon scales","verner debt","argus scales"}},{q="Where are the black dragon whelps found in Redridge?",a="Black dragon whelps commonly roam the rocky crags and valleys south of Lakeshire. They tend to wander freely across the southern foothills, meaning hunters often have to patrol the trails and ridges to spot them in flight.",al={"whelp locations","where are whelps","dragon whelp location redridge"}},{q="Who is Smith Argus?",a="Smith Argus is the resident blacksmith stationed at Goldshire in Elwynn Forest. He provides metalwork and forged goods to surrounding settlements, including horseshoes for Verner Osgood in Redridge.",al={"argus goldshire","who is argus","smith argus"}},{q="Why are black dragon whelps in Redridge Mountains?",a="The Black Dragonflight maintains a presence throughout the Burning Steppes and the surrounding peaks of Redridge. Their whelps hunt and wander southward through the mountain passes into the Redridge foothills.",al={"why are there dragons in redridge","black dragons redridge","black flight redridge"}},{q="What makes underbelly scales special?",a="While dorsal scales on drakes are thick and rigid, underbelly scales are supple and flexible while maintaining high heat and puncture resistance. This makes them ideal for specialized leatherworking, tailored reinforcement, and exotic trade goods.",al={"why underbelly scales","scale value","dragonhide quality"}},{q="Does clearing this debt lead to other tasks for Verner?",a="This task is part of Verner Osgood's requests after you bring him his horseshoe shipment. Aside from this optional gathering job, Verner directs adventurers to address the growing gnoll threat in Redridge through hunting their scouts and leaders.",al={"what comes next","verner questline","osgood follow up"}}},ang={["profession:Blacksmithing"]="Smith Argus's demand highlights how rare reagents like dragon scales are leveraged as high-value barter between smiths when standard coin is scarce.",["faction:Alliance"]="The creeping threat of the Black Dragonflight south of Lakeshire is another burden on an already overstretched garrison struggling to hold Redridge.",["race:Human"]="Trade routes between Elwynn and Redridge keep towns like Lakeshire supplied, but frontier craftsmen must often pay steep prices to city merchants."},kw={"black dragon whelp","dragonflight","goldshire","lakeshire","redridge","smith argus","underbelly scales","verner osgood"},rel={"npc:verner-osgood","quest:118","quest:119","quest:124","quest:126","zone:redridge","subzone:lakeshire","subzone:goldshire"},m={start="Verner Osgood",level="18",faction="Alliance",id=122},src={"Underbelly Scales"}}
E["quest:124"] = {t="quest",n="A Baying of Gnolls",z="redridge",s="Verner Osgood, the stable master in Lakeshire, finds his business under siege by gnolls raiding south from the Redridge foothills. Already strained by Blackrock orc incursions, he asks travelers to clear out the brutes and mystics threatening his livestock.",h="Verner Osgood, the stable master in Lakeshire, finds his business under siege by gnolls raiding south from...",sec={{t="Horses on the Ridge",b="Running a stable in Lakeshire has become increasingly hazardous. Blackrock orcs command the heights of the region, while packs of gnolls roam the surrounding ridges. For Verner Osgood, the situation reached a breaking point when aggressive gnoll raiding bands crept close to the northern borders of his paddocks, preying on any horses that wandered too close to the bluffs.",sp=0},{t="A Coordinated Menace",b="These are not just scattered scavengers. The packs operating directly north of the town combine savage muscle with primitive spellcraft, employing tough brutes to overwhelm prey alongside mystics wielding wild magic. Thinning their numbers offers brief respite to the settlement, though it quickly becomes apparent that their aggression is driven by a larger power lurking higher in the hills.",sp=1}},faq={{q="Why does Verner Osgood need help with gnolls?",a="Gnolls from the northern ridges have begun encroaching on Verner's stables, snatching horses whenever they stray from the paddocks. Between that threat and the Blackrock orc invasion, he cannot safeguard his stock without outside aid.",al={"verner problem","why verner wants gnolls killed","lakeshire stable gnolls"}},{q="Where are these gnolls located?",a="The Redridge brutes and mystics prowl along the elevated ridges and foothills directly north and east of Lakeshire, overlooking the town and the road toward the Everstill Bridge.",al={"where are redridge brutes","redridge mystic location","gnolls north of stables"}},{q="Why are gnolls an issue alongside the Blackrock orcs?",a="While the Blackrock clan is the primary military force menacing Redridge, local gnoll packs exploit the distraction. With Lakeshire's defenders stretched thin and Stormwind offering minimal reinforcements, indigenous predators have expanded unchecked right up to the village perimeter.",al={"orcs and gnolls redridge","why both gnolls and orcs"}},{q="What comes after dealing with these gnolls?",a="After thinning out the brutes and mystics, Verner notes that the howling in the hills continues, pointing toward a larger leadership threat that must be addressed in the surrounding heights.",al={"baying of gnolls follow up","what next after baying of gnolls"},sp=1},{q="Why are mystics particularly dangerous?",a="Redridge mystics practice rudimentary nature and elemental magic, turning erratic, feral incantations against trespassers. Their presence among the brutes suggests an organized clan structure rather than lone wild scavengers.",al={"redridge mystics lore","gnoll shamans redridge"}},{q="Is Stormwind sending soldiers to protect Lakeshire's stables?",a="No. Stormwind's royal court has left Redridge largely to defend itself amid ongoing political turmoil and troop shortages, forcing Magistrate Solomon and citizens like Verner Osgood to recruit wandering adventurers.",al={"stormwind guard redridge","why no guards helping verner"}}},ang={["faction:Alliance"]="Every small community in the southern kingdom is feeling the strain of Stormwind's neglect, leaving humble tradesmen like Verner to hire private help to protect essential supply lines.",["class:Hunter"]="The wild beasts and feral packs of Redridge have grown brazen in the absence of organized culls, making them a volatile threat to domestic animals and travelers."},kw={"gnolls","horses","lakeshire","redridge brute","redridge mountains","redridge mystic","stables","verner osgood"},rel={"npc:verner-osgood","quest:126","quest:122","quest:119","quest:89","topic:gnoll","zone:redridge"},m={start="Verner Osgood",level="20",faction="Alliance",id=124},src={"A Baying of Gnolls"}}
E["quest:125"] = {t="quest",n="The Lost Tools",z="redridge",s="With Lakeshire under pressure from hostile forces, town maintenance and defense rely entirely on local labor. Foreman Oslow's essential tools, shipped from Goldshire, were lost when Blackrock catapult fire sank his transport boat into Lake Everstill. Retrieving the sunken chest from the lakebed is critical to rebuilding the town's shattered bridge.",h="With Lakeshire under pressure from hostile forces, town maintenance and defense rely entirely on local labor.",sec={{t="A Delivery Gone Awry",b="Lakeshire's lifeline to Elwynn Forest has been severed by the destruction of the Great Bridge. When a replacement shipment of stonemasonry and carpentry tools was dispatched overland from Goldshire, it could not cross directly into town. The crew transferred the supplies into a rowboat to cross Lake Everstill, only for the vessel to be struck directly by a Blackrock orc catapult. The boat was obliterated, and Oslow's heavy ironbound toolbox plunged directly to the deep lake floor.",sp=0},{t="Hazards of the Deep",b="Reclaiming the toolbox is far more perilous than a standard dive. The waters of Lake Everstill are infested with aggressive murloc tribes prowling the shallows, while predatory threshers hunt the murky depths. Despite the danger, recovering the tools is necessary if Foreman Oslow is to resume repair work on the bridge and keep Lakeshire from falling completely into ruin.",sp=0}},faq={{q="Why were the tools sent by boat in the first place?",a="The main road into Lakeshire crosses a stone bridge spanning Lake Everstill, but Blackrock orcs blew out a large span of it. Because supply wagons coming from Goldshire could no longer cross, the crew had to unload the tools and attempt to ferry them across the water.",al={"why boat","how did the tools sink","why lake transport"}},{q="How did the boat sink?",a="While crossing the lake, the transport boat came under fire from Blackrock orcs, who struck it directly with a catapult projectile from the surrounding heights, sinking the boat and its cargo instantly.",al={"who destroyed the boat","how did it get hit"}},{q="Who is Foreman Oslow?",a="Foreman Oslow is Lakeshire's chief builder and overseer. He is responsible for public works and civil maintenance in town, most urgently the critical task of reconstructing the ruined bridge.",al={"foreman oslow","oslow role"}},{q="What threats are in Lake Everstill?",a="The lake is populated by hostile murloc tribes patrolling near the shores and ruins, as well as vicious, carnivorous lake threshers that hunt in the open water and deeper depths.",al={"what's in the lake","lake monsters","lake everstill danger"}},{q="Why does Lakeshire need these tools so badly?",a="Lakeshire is effectively under siege, cut off from immediate reinforcements and regular shipments. Without heavy tools, Oslow cannot rebuild the bridge or repair the defenses needed to hold off attacking orcs and gnolls.",al={"why are tools important","bridge repair tools"}},{q="Where does the quest lead next?",a="Once his toolbox is recovered, Foreman Oslow enlists adventurers to collect the raw building materials needed to repair the Great Bridge in the follow-up quest, The Everstill Bridge.",al={"next quest","what after lost tools"},sp=1}},ang={["faction:Alliance"]="Lakeshire stands as the Alliance's Eastern bastion against the Blackrock clan; ensuring civilian builders have their equipment is vital to maintaining the Kingdom of Stormwind's frontier.",["profession:Blacksmithing"]="Quality tools are hard to forge under siege conditions, making the recovery of specialized smithing and construction implements from Goldshire indispensable to the town."},kw={"catapult","foreman oslow","goldshire","lake everstill","lakeshire","murloc","redridge","thresher","toolbox"},rel={"npc:foreman-oslow","subzone:lake-everstill","quest:89","subzone:lakeshire","zone:redridge","subzone:goldshire","topic:murloc"},m={start="Foreman Oslow",level="16",faction="Alliance",id=125},src={"The Lost Tools"}}
E["quest:126"] = {t="quest",n="Howling in the Hills",z="redridge",s="Howling in the Hills is an Alliance bounty offered by Verner Osgood in Lakeshire to hunt down Yowler, the fearsome alpha leading the Redridge gnolls. With Stormwind's military stretched too thin fighting the Blackrock orcs to defend the local borders, Lakeshire relies on visiting adventurers to break the gnoll pack's command.",h="Howling in the Hills is an Alliance bounty offered by Verner Osgood in Lakeshire to hunt down Yowler, the...",sec={{t="The Voice in the Heights",b="Even after culling the lesser gnolls raiding the paths around Lakeshire, their ominous calls continue to echo through the Redridge ridges. Verner Osgood, Lakeshire's hardworking farrier, recognizes that killing scouts and scavengers will never stem the tide as long as their pack leader remains alive. Rising above the rabble is Yowler, an exceptionally cunning and massive gnoll whose calls direct the pack across the hills. Verner tasks adventurers with hunting down the beast and severing his paw to ensure the howling is silenced once and for all.",sp=0},{t="A Town Abandoned by the Army",b="This contract highlights the grim reality facing the eastern borders of the kingdom of Stormwind. With the missing King Varian Wrynn and regency disputes paralyzing high command, royal soldiers are focused almost exclusively on the entrenched Blackrock orc clans in the north. Everyday settlements like Lakeshire are left completely undefended against native menaces like gnolls, forcing townsfolk like Verner Osgood to organize their own bounties to prevent their homes from being overrun.",sp=0}},faq={{q="Who is Yowler?",a="Yowler is the fierce leader of the Redridge gnolls prowling the hills outside Lakeshire. Verner Osgood notes that Yowler is far stronger and more dangerous than common mongrels, serving as the unifying alpha who directs the pack against travelers and local homesteads.",al={"yowler","who is the gnoll boss","yowler lore","yowler gnoll"}},{q="Why is Verner Osgood issuing this bounty instead of the town guard?",a="Lakeshire's official leadership and the local militia are completely overwhelmed by the encroaching Blackrock orcs. Verner Osgood, a local craftsman and stable master whose livelihood depends on safe roads, frequently steps up to hire wandering mercenaries to eliminate immediate local dangers.",al={"why verner","why not magistrate solomon","why osgood hiring"}},{q="Where are the Stormwind soldiers who should be protecting Lakeshire?",a="Stormwind's standing forces are committed elsewhere. The army's presence in Redridge is tied down monitoring and containing the Blackrock clan orcs further up in the mountains, leaving townspeople with zero support against local wildlife, murlocs, and gnolls.",al={"where is the army","why no stormwind guards","stormwind military lakeshire"}},{q="What happens to the Redridge gnolls once Yowler is dead?",a="Killing Yowler scatters the command structure of the gnoll pack, blunting coordinated raids on the town's borders. However, gnolls remain a stubborn and enduring nuisance throughout the craggy heights of Redridge.",al={"did gnolls leave","what happens after yowler dies"}},{q="What prerequisite quests lead up to this contract?",a="The quest chain begins with Verner Osgood sending you on errands to secure horse gear in 'The Price of Shoes' and 'Return to Verner.' After dealing with underbelly hides and thinning the pack in 'A Baying of Gnolls,' Verner grants you the bounty to hunt Yowler directly.",al={"yowler quest pre reqs","unlock howling in the hills","chain for howling in the hills"}},{q="Why does Verner need Yowler's paw as proof?",a="Bounties on dangerous beasts require indisputable physical evidence before payment is rendered. Bringing back Yowler's severed paw proves to Verner and the uneasy residents of Lakeshire that the terrifying beast echoing through the hills has truly fallen.",al={"why yowler paw","yowlers paw proof"}}},ang={["faction:Alliance"]="Lakeshire's reliance on mercenaries rather than royal soldiers reveals the deep administrative strain currently weakening the kingdom of Stormwind.",["class:Hunter"]="Tracking down a dominant alpha like Yowler in his mountain lair demands a keen eye for territorial markings and pack behavior.",["class:Warrior"]="Taking on Yowler means confronting an opponent who rules his brutal pack through sheer physical dominance, demanding a direct clash of brute force."},kw={"blackrock","gnolls","lakeshire","paw","redridge","stormwind army","verner osgood","yowler"},rel={"npc:verner-osgood","quest:124","quest:122","subzone:lakeshire","zone:redridge","topic:gnoll","topic:stormwind-army","topic:stormwind-kingdom"},m={start="Verner Osgood",level="21",faction="Alliance",id=126},src={"Howling in the Hills"}}
E["quest:127"] = {t="quest",n="Selling Fish",z="redridge",s="Dockmaster Baren manages the bustling pier at Lakeshire, but finding fresh stock for his trade has grown difficult. He pays travelers to haul in spotted sunfish, a prized local staple of Lake Everstill that has become dangerous to gather due to the encroaching murlocs.",h="Dockmaster Baren manages the bustling pier at Lakeshire, but finding fresh stock for his trade has grown...",sec={{t="A Staple of Lake Everstill",b="Lake Everstill is known throughout the surrounding lands for its spotted sunfish, a delicate catch that remains in perpetual demand among the townspeople and passing merchants. Yet despite the abundance beneath the lake's surface, the town's supplies regularly run thin. With Lakeshire stretched to its limits under various local threats, even basic commerce requires the help of freelance adventurers.",sp=0},{t="Trouble on the Shallows",b="Normally, local anglers would have little trouble satisfying Dockmaster Baren's orders. However, the rise of aggressive murloc tribes along the shallows and banks has driven ordinary townsfolk away from the water. Travelers looking to fulfill Baren's request must either cast their own lines while watching their backs, or claim the catch directly from the foraging murlocs that plague the shores.",sp=0}},faq={{q="Who is Dockmaster Baren?",a="Dockmaster Baren oversees the docks and boat traffic on Lake Everstill in Lakeshire. He manages the town's aquatic trade and relies on capable travelers to help secure fresh fish and clear out threats around the water.",al={"baren","who is the dockmaster","dockmaster baren"}},{q="Why are spotted sunfish in such high demand?",a="Lake Everstill is famed for its spotted sunfish, making them a staple delicacy and an important trade good for Lakeshire. Dockmaster Baren's stocks run low because ordinary town anglers cannot safely fish while the lake remains infested with hostiles.",al={"why sunfish","spotted sunfish lore","why does lakeshire want fish"}},{q="How do murlocs end up with the sunfish?",a="The murloc tribes along Lake Everstill actively forage and hunt the shallows. When they kill or drive away local fishermen, they gather the fish for their own camps, making their stores ripe for the taking by adventurers who would rather fight than cast a line.",al={"murloc fish","why do murlocs drop fish","murlocs stealing fish"}},{q="Where can spotted sunfish be found?",a="Spotted sunfish inhabit the waters of Lake Everstill in Redridge Mountains. They can be reeled in directly with a fishing rod or looted from the murlocs dwelling around the lake's banks and shallows.",al={"where are sunfish","lake everstill fish location","how to get spotted sunfish"}},{q="How does this quest fit with Murloc Poachers?",a="Dockmaster Baren offers both tasks simultaneously. Since murlocs prowl the lake and poach its resources, dealing with the poachers naturally overlaps with reclaiming the spotted sunfish they have hauled from the water.",al={"murloc poachers connection","baren other quest","dockmaster quests"}},{q="Is fishing required to help Dockmaster Baren?",a="No, you do not need fishing gear or skill. While angling is a peaceful way to gather spotted sunfish, Dockmaster Baren openly suggests taking them by force from the murloc tribes that hunt the lake.",al={"do i need fishing","can i do this without fishing pole","fishing required"}}},ang={["profession:Cooking"]="Lakeshire's reputation for fine freshwater delicacies like spotted sunfish makes the local waters an enduring point of interest for aspiring cooks.",["faction:Alliance"]="With the Kingdom of Stormwind offering little military aid to Redridge, even sustaining the local food supply relies on independent Alliance travelers lending a hand."},kw={"dockmaster baren","lake everstill","lakeshire","murloc","redridge","selling fish","spotted sunfish"},rel={"subzone:lakeshire","subzone:lake-everstill","quest:150","topic:murloc","zone:redridge"},m={level="21",faction="Alliance",id=127},src={"Selling Fish"}}
E["quest:128"] = {t="quest",n="Blackrock Bounty",z="redridge",s="Blackrock Bounty is a defense contract issued by Guard Howe in Lakeshire on behalf of Magistrate Solomon. With Stormwind failing to dispatch reinforcements, the town pays independent adventurers to cull the elite Blackrock Champions massing in the northern mountains. Striking down these battlefield unit commanders is aimed at disrupting the orc clan's coordinated assault on Redridge.",h="Blackrock Bounty is a defense contract issued by Guard Howe in Lakeshire on behalf of Magistrate Solomon.",sec={{t="Holding the Sovereign Line",b="Redridge has long fallen under the sovereign rule of the Kingdom of Stormwind, but the Blackrock clan does not honor human borders. Pouring down through the mountain passes leading from the Burning Steppes, the orcs have established heavily fortified encampments across northern Redridge. With King Varian Wrynn missing and the regency in Stormwind withholding royal soldiers, local leaders like Magistrate Solomon have been forced to put up bounties from the town's dwindling coffers to protect Lakeshire.",sp=0},{t="Targeting the Champions",b="Guard Howe identifies the Blackrock Champions as the backbone of the invading vanguard. Serving as squad leaders and battle-hardened veterans within their warbands, these champions coordinate troop movements and drive the lesser grunt forces forward. By putting a price on their heads, Lakeshire's defenders hope to break the clan's tactical leadership and stall a full-scale push south before the township's outer perimeter collapses.",sp=0}},faq={{q="Why is Guard Howe offering bounties instead of sending the town guard?",a="Lakeshire's local garrison is stretched to the breaking point. Between patrolling Lake Everstill, guarding the bridges, and holding off gnolls and orc raiders, the guards cannot spare a force large enough to assault fortified orc warcamps directly without leaving the town defenseless.",al={"why bounties","where is town guard","guard howe bounty"}},{q="Where are the Blackrock Champions located?",a="They are stationed in the sprawling Blackrock camps in northern Redridge Mountains, just to the west of the high road that climbs toward the Burning Steppes.",al={"where are champions","champion location","blackrock champion camp"}},{q="Why are the Blackrock orcs invading Redridge?",a="Operating out of Blackrock Mountain to the north, the Blackrock clan views the surrounding hills as strategic territory to conquer and pillage. With Stormwind's defense fragmented, they seek to drive out human settlements and claim dominion over the mountain passes.",al={"why blackrock in redridge","why orcs attacking lakeshire","blackrock invasion"}},{q="Why doesn't Stormwind send royal soldiers to clear them out?",a="King Varian Wrynn is missing, and the royal court under Regent Bolvar Fordragon and Lady Prestor insists that the kingdom's armies cannot be spared. Lakeshire has repeatedly petitioned the capital for aid, only to be denied and left to hire passing mercenaries.",al={"why no stormwind army","where is stormwind help","magistrate solomon reinforcements"}},{q="What role do Champions serve within the Blackrock clan?",a="Champions act as frontline tactical leaders. Each Blackrock combat squad relies on a champion to direct attacks, enforce brutal discipline, and lead charges into Alliance territory.",al={"what are blackrock champions","champion rank","blackrock leader unit"}},{q="Who authorized this bounty contract?",a="Magistrate Solomon, the civic leader of Lakeshire, authorized the bounty and tasked Guard Howe with recruiting capable fighters to carry out the culling.",al={"who pays bounty","who wants champions dead","magistrate solomon bounty"}}},ang={["faction:Alliance"]="Lakeshire stands as Stormwind's eastern shield; if the Blackrock orcs break through these mountain camps, the core farmlands of the Alliance will be directly exposed to invasion.",["race:Human"]="The Blackrock clan destroyed the original Kingdom of Stormwind in the First War. For human defenders, stopping their return south is a bitter, ancestral necessity.",["class:Warrior"]="Blackrock Champions are heavily armored, seasoned veteran brawlers who test a warrior's discipline and endurance in martial combat."},kw={"blackrock","bounty","burning steppes","champion","guard howe","lakeshire","magistrate solomon","redridge","stormwind"},rel={"npc:guard-howe","npc:magistrate-solomon","subzone:lakeshire","zone:redridge","topic:blackrock-clan","topic:stormwind-kingdom","zone:burningsteppes"},m={start="Guard Howe",level="25",faction="Alliance",id=128},src={"Blackrock Bounty"}}
E["quest:129"] = {t="quest",n="A Free Lunch",z="redridge",s="A Free Lunch is an Alliance errand originating in Lakeshire, where the inn cook Darcy asks an adventurer to take a prepared meal to Guard Parker. Parker patrols the perilous southern road heading toward Duskwood, keeping Lakeshire's approaches clear of hostile gnolls and Blackrock orcs.",h="A Free Lunch is an Alliance errand originating in Lakeshire, where the inn cook Darcy asks an adventurer to...",sec={{t="A Meal for the Road",b="Daily life in Redridge is fraught with tension, but Darcy, a local of Lakeshire, tries to support those defending the town in her own way. Having packed a hearty meal for Guard Parker, she finds herself unable to deliver it personally. The wilderness just beyond the town gates swarms with aggressive Redridge gnolls and roaming orc warbands, making travel outside the town perimeter far too dangerous for an unarmored civilian. Instead, she relies on passing travelers to carry the ration out along the road toward Darkshire.",sp=0},{t="Guarding the Border",b="Guard Parker is stationed along the road south of Lakeshire, keeping watch over the route that connects Redridge to Duskwood. The guard detail in Redridge is stretched dangerously thin, with the Stormwind army failing to supply adequate reinforcements against the rising Redridge gnoll packs and the Blackrock clan entrenched in the mountains. Standing solitary watch amidst such hostile territory leaves sentries like Parker thoroughly worn down, making simple gestures of civilian care and hot food an essential boost to troop morale.",sp=0}},faq={{q="Where can Guard Parker be found?",a="Guard Parker patrols the southern dirt road leading out of Lakeshire toward the border of Duskwood and the town of Darkshire.",al={"guard parker location","where is parker","find guard parker"}},{q="Why doesn't Darcy deliver the lunch herself?",a="Darcy is an ordinary civilian and considers the outskirts of Lakeshire far too perilous to wander alone. Hostile gnolls and Blackrock orcs prowl right along the roadways just outside town.",al={"why cant darcy go","darcy redridge"}},{q="What threats is Guard Parker dealing with?",a="Parker must hold the southern roadway against roaming gnoll packs native to the Redridge Mountains as well as aggressive Blackrock orc war parties.",al={"parker enemies","redridge threats"}},{q="What happens after Guard Parker gets his lunch?",a="Receiving Darcy's meal sparks Parker's gratitude, eventually prompting him to send the adventurer on further domestic errands between the guards and townspeople, beginning with a visit to the local herbalist.",al={"a free lunch next quest","parker follow up"},sp=1},{q="Why are Stormwind guards struggling to keep Redridge safe?",a="With King Varian Wrynn missing and the kingdom's political leadership preoccupied in Stormwind City, outlying settlements like Lakeshire have received little to no military support, leaving individual town guards heavily isolated.",al={"why is lakeshire undefended","stormwind neglect redridge"}},{q="What is Darcy's promised reward?",a="In exchange for carrying Parker's meal through dangerous wilderness, Darcy promises to prepare and serve a free lunch to the courier upon their return to town.",al={"what is the free lunch","darcy reward"}}},ang={["faction:Alliance"]="Delivering Darcy's food highlights the strain placed on everyday folk and line sentries in outlying Alliance settlements that have been left largely to fend for themselves.",["profession:Cooking"]="A warm, well-prepared ration in the field is often all that sustains an isolated sentry holding a hostile crossroads."},kw={"blackrock orcs","darcy","darkshire","free lunch","gnolls","guard parker","lakeshire","parker's lunch","redridge mountains"},rel={"quest:130","quest:131","subzone:lakeshire","zone:redridge","subzone:darkshire","topic:stormwind-guard","topic:gnoll","topic:stormwind-kingdom"},m={start="Darcy",["end"]="Guard Parker",level="15",faction="Alliance",id=129},src={"A Free Lunch"}}
E["quest:130"] = {t="quest",n="Visit the Herbalist",z="redridge",s="Following a meal delivery to his remote post, Guard Parker asks a favor before you return to the Lakeshire inn. Hoping to express his feelings for Darcy, he sends you to the local herbalist to purchase flowers. Parker insists that the herbalist not be told who ordered them or who they are intended for.",h="Following a meal delivery to his remote post, Guard Parker asks a favor before you return to the Lakeshire...",sec={{t="A Guard's Secret Request",b="Stationed along the lonely southern approach to Lakeshire, Guard Parker spends his watch keeping an eye out for blackrock orcs and gnolls. When you bring him a warm meal from Darcy at the Lakeshire Inn, he seizes the opportunity to reciprocate her kindness. Instead of letting you simply walk back, he asks you to stop by the local herbalist shop on the west end of town and purchase a bouquet of flowers for her.",sp=0},{t="Town Gossip and Secret Courting",b="Small-town life in Lakeshire leaves little room for secrecy, which explains why Parker explicitly warns you not to reveal to the herbalist, Martie Jainrose, whom the flowers are from or for whom they are destined. When you arrive at her shop, Martie cannot help teasing you, assuming you have swiftly found a sweetheart of your own in town. In a region beset by orc incursions and brigands, even a modest gesture of romance is a welcome distraction.",sp=0}},faq={{q="Who sends you to visit the herbalist?",a="Guard Parker gives you this task. He is stationed guarding the southern road leading into the Redridge Mountains, just north of the border with Duskwood.",al={"who gives this quest","quest giver","guard parker"}},{q="Who is the herbalist in Lakeshire?",a="Martie Jainrose is the local herbalist and florist in Lakeshire. Her shop is located at the western end of the town.",al={"who is martie jainrose","where is herbalist","lakeshire herbalist"}},{q="Why does Guard Parker want flowers?",a="Parker wants to send flowers to Darcy, the waitress at the Lakeshire Inn who sent him a free lunch, as a gesture of romantic interest and gratitude.",al={"why buy flowers","who are flowers for","parker motive"}},{q="Why does Parker want the purchase kept secret?",a="Lakeshire is a small, close-knit town where news travels fast. Parker is bashful about courting Darcy and wants to avoid gossip from Martie Jainrose and the other townsfolk.",al={"why secrecy","why hide who flowers are for","dont tell martie"}},{q="What happens after talking to Martie Jainrose?",a="Martie prepares a bouquet of daffodils, leading into the task of delivering the flowers directly to Darcy at the Lakeshire Inn.",al={"what comes next","delivering daffodils","after herbalist"},sp=1},{q="Where does this fit in the quest chain?",a="This quest is the bridge between 'A Free Lunch', where you bring lunch to Guard Parker, and 'Delivering Daffodils', where you carry the flowers back to Darcy.",al={"quest chain","prerequisite","free lunch chain"},sp=1}},ang={["profession:Herbalism"]="Visiting Martie Jainrose introduces gatherers to Lakeshire's primary herbalism and alchemy merchant at the town's western edge.",["faction:Alliance"]="Even amidst the constant threat of gnoll packs and blackrock orcs pressing into Redridge, small civilian romances still play out among Lakeshire's defenders."},kw={"daffodils","darcy","flowers","guard parker","lakeshire","martie jainrose","redridge","visit the herbalist"},rel={"quest:129","quest:131","npc:martie-jainrose","subzone:lakeshire","zone:redridge"},m={start="Guard Parker",["end"]="Martie Jainrose",level="15",faction="Alliance",id=130},src={"Visit the Herbalist"}}
E["quest:131"] = {t="quest",n="Delivering Daffodils",z="redridge",s="Delivering Daffodils concludes a small domestic errand running between the guard post and town square in Lakeshire. After fetching lunch for Guard Parker and picking up a bouquet from herbalist Martie Jainrose, you hand over the blooms to Darcy at the Lakeshire Inn, only to stumble straight into an awkward local rivalry.",h="Delivering Daffodils concludes a small domestic errand running between the guard post and town square in...",sec={{t="A Fragrant Errand",b="What began as a simple favor delivering a hot meal to Guard Parker turns into a delicate romantic gesture. Grateful for his lunch, Parker asks you to fetch flowers from Martie Jainrose as a surprise for Darcy, the cook who prepared his food. Martie arranges a fresh bouquet of her own favorite blooms—daffodils—unaware of who is intended to receive them.",sp=0},{t="Town Rivalries",b="Upon bringing the bouquet back to the Lakeshire Inn, Darcy's initial delight quickly curdles into suspicion. Recognizing daffodils as Martie's personal favorite, Darcy immediately suspects Parker dealt with a woman she considers a jealous vixen. While worried Martie might have spitefully poisoned the stems had she known the recipient, Darcy relieves you of blame and hands over a hot portion of sauteed sunfish for your trouble.",sp=1}},faq={{q="Who is Darcy?",a="Darcy works at the Lakeshire Inn in Redridge Mountains, preparing meals for locals and town guards. She is the cook who sent a lunch to Guard Parker, prompting Parker to send back a bouquet of flowers in gratitude.",al={"darcy","who is darcy in lakeshire","lakeshire cook darcy"}},{q="Who is Martie Jainrose?",a="Martie Jainrose is Lakeshire's resident herbalist and flower enthusiast. Guard Parker directs you to her to purchase a nice bouquet, and Martie happily assembles daffodils, noting they happen to be her own favorite flowers.",al={"martie jainrose","lakeshire herbalist","who gave the flowers"}},{q="Why is Darcy upset about the daffodils?",a="Darcy instantly recognizes daffodils as Martie's favorite flower. She considers Martie a jealous rival and fears Martie would have poisoned the stems had she known the bouquet was meant for Darcy.",al={"why is darcy angry","darcy martie feud","why poisoned flowers"},sp=1},{q="Did Martie actually poison the bouquet?",a="No. Martie had no idea the flowers were intended for Darcy, as Parker simply asked you to pick up an arrangement, and Martie casually chose her own favorites for the bundle.",al={"are daffodils poisoned","is bouquet poisoned"},sp=1},{q="What quests lead up to this delivery?",a="The chain starts with 'A Free Lunch', where you carry Darcy's meal to Guard Parker. Parker then gives you 'Visit the Herbalist' to buy a gift from Martie Jainrose, which ends with 'Delivering Daffodils'.",al={"quest chain","daffodils prerequisites","delivering daffodils chain"}},{q="What reward do you get for delivering the flowers?",a="Darcy thanks you with a hearty bundle of sauteed sunfish, some copper and experience, along with standing with the kingdom of Stormwind.",al={"quest reward","daffodils rewards"}}},ang={["profession:Cooking"]="Darcy rewards your delivery with seasoned sauteed sunfish, offering an example of simple Redridge lakeside home cooking.",["profession:Herbalism"]="The errand relies on Martie Jainrose's botanical knowledge and her eye for fresh lakeside blooms, showcasing the peaceful side of herb gathering.",["faction:Alliance"]="Assisting the town guard and innkeeper in Lakeshire helps maintain civilian morale while the town struggles under Blackrock and gnoll incursions."},kw={"daffodil bouquet","darcy","delivering daffodils","guard parker","lakeshire","martie jainrose","redridge","sauteed sunfish"},rel={"quest:130","quest:129","npc:martie-jainrose","zone:redridge","topic:stormwind-kingdom"},m={start="Martie Jainrose",["end"]="Darcy",level="15",faction="Alliance",id=131},src={"Delivering Daffodils"}}
E["quest:143"] = {t="quest",n="Messenger to Westfall",z="redridge",s="Messenger to Westfall is an Alliance errand carrying an urgent plea from Magistrate Solomon in Redridge across Elwynn to Westfall. Facing total abandonment by the Stormwind military, Lakeshire's leadership seeks mutual aid from Gryan Stoutmantle's newly formed People's Militia.",h="Messenger to Westfall is an Alliance errand carrying an urgent plea from Magistrate Solomon in Redridge...",sec={{t="A Desperate Appeal",b="Magistrate Solomon finds Lakeshire in a desperate situation. The Redridge Mountains are besieged by Blackrock orcs and gnolls, yet the Stormwind Army has failed to arrive in force. Recognizing that Lakeshire cannot survive on town guards and irregulars alone, Solomon writes a formal plea for assistance. With regular royal reserves nowhere in sight, he turns his eyes west, having heard word of a citizen defense group forming beyond Elwynn Forest.",sp=0},{t="Reaching Across Borders",b="The intended recipient of the dispatch is Gryan Stoutmantle, a veteran commander who has begun rallying volunteer fighters under the banner of the People's Militia. By sending a courier directly across the kingdom, Solomon hopes that Westfall's organized volunteers might spare troops to reinforce Lakeshire's borders until the Crown's armies finally mobilize. However, as messengers soon discover, Westfall is mired in its own catastrophic struggles against the Defias Brotherhood.",sp=0}},faq={{q="Why is Magistrate Solomon asking Westfall for help?",a="Stormwind has failed to send the military reinforcements Lakeshire urgently needs against the orcs and gnolls. Having heard reports of an armed citizen force gathering in Westfall, Solomon hopes Gryan Stoutmantle can spare troops to reinforce Redridge.",al={"why westfall","solomons plea","why ask gryan"}},{q="Who is Gryan Stoutmantle?",a="Gryan Stoutmantle is a veteran soldier stationed at Sentinel Hill in Westfall. In the absence of Crown authority and protection, he organized and leads the People's Militia to defend local farmsteads from brigands and the Defias Brotherhood.",al={"who is gryan","stoutmantle role","who leads westfall"}},{q="Where does this courier journey lead?",a="The message must be carried from the town hall in Lakeshire all the way west across Redridge and Elwynn Forest, ending at Sentinel Hill in central Westfall.",al={"where do i deliver","where is stoutmantle","redridge to westfall"}},{q="Why hasn't the Stormwind Army relieved Lakeshire?",a="Magistrate Solomon notes that something odd is afoot with the army, as promised troops have not materialized. Stormwind's leadership is gridlocked under the regency of Bolvar Fordragon and Lady Prestor, leaving outlying territories to fend for themselves.",al={"why no stormwind army","where are royal guards","stormwind army missing"}},{q="Can Westfall actually spare any troops for Redridge?",a="No. When you arrive at Sentinel Hill, you find that Westfall is barely holding together against the Defias Brotherhood. The People's Militia has no soldiers to spare and is struggling to protect its own borders.",al={"does westfall help","will militia come","can gryan help"},sp=1},{q="What comes after delivering the letter?",a="Gryan Stoutmantle receives the message and immediately drafts a response explaining Westfall's dire situation, sending you back on a return journey with a reply for Magistrate Solomon.",al={"what next","follow up quest","after messenger to westfall"},sp=1}},ang={["faction:Alliance"]="This dispatch highlights the complete collapse of central defense in the Kingdom of Stormwind, forcing border towns to negotiate private mutual defense pacts.",["race:Human"]="The message demonstrates the shared plight of human settlers across Redridge and Westfall, who must rely on volunteers and mercenaries while the capital sits idle."},kw={"gryan stoutmantle","lakeshire","magistrate solomon","peoples militia","redridge mountains","sentinel hill","solomons plea","westfall"},rel={"npc:magistrate-solomon","npc:gryan-stoutmantle","quest:12","subzone:lakeshire","zone:redridge","zone:westfall","topic:stormwind-kingdom","topic:stormwind-army"},m={start="Magistrate Solomon",["end"]="Gryan Stoutmantle",level="14",faction="Alliance",id=143},src={"Messenger to Westfall"}}
E["quest:145"] = {t="quest",n="Messenger to Darkshire",z="redridge",s="Messenger to Darkshire is an urgent diplomatic mission sent by Magistrate Solomon of Lakeshire to Lord Ello Ebonlocke in Duskwood. Desperate for military reinforcement against the Blackrock orcs and gnolls threatening Redridge, Solomon turns to his neighboring settlement for aid. The courier must brave the shadowed highways of Duskwood to deliver Solomon's formal plea to the mayor of Darkshire.",h="Messenger to Darkshire is an urgent diplomatic mission sent by Magistrate Solomon of Lakeshire to Lord Ello...",sec={{t="A Desperate Call for Aid",b="With Stormwind's royal court ignoring his pleas and neighboring Westfall bogged down in its own insurrection, Magistrate Solomon looks south to Duskwood. Redridge faces a mounting siege from the Blackrock orc clans and aggressive gnoll packs, leaving Lakeshire's local guards stretched to their breaking point. In desperation, Solomon pens a letter directly to Mayor Ello Ebonlocke, hoping to hire or borrow Darkshire's vaunted Night Watch to reinforce the town's perimeter.",sp=0},{t="The Road into the Gloom",b="Carrying Solomon's letter requires crossing the borders of the kingdom into Duskwood, a forested region shrouded in supernatural gloom. Solomon warns couriers to stick strictly to the roads, as the wilderness between Lakeshire and Darkshire has become notoriously perilous. Reaching Town Hall in Darkshire places the missive into the hands of Lord Ebonlocke, though whether Duskwood has any forces to spare remains an entirely separate question.",sp=0}},faq={{q="Why is Lakeshire asking Darkshire for help?",a="Stormwind has withheld formal military assistance, leaving towns like Lakeshire to defend themselves against overwhelming threats like the Blackrock orcs. Magistrate Solomon is trying every nearby Alliance ally, hoping Darkshire's civic militia, the Night Watch, might have trained fighters to lend.",al={"why ask duskwood","why darkshire","solomon darkshire plea"}},{q="Who is Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke is the mayor of Darkshire and the prominent civilian leader of Duskwood. He oversees the town from the town hall and coordinates civic affairs alongside Commander Althea Ebonlocke, who commands the Night Watch.",al={"ello ebonlocke","who is ebonlocke","mayor of darkshire"}},{q="What is the Night Watch?",a="The Night Watch is Darkshire's independent civilian militia, established to patrol the perimeter and fight off the undead, beasts, and shadows creeping through Duskwood in the absence of Stormwind garrison troops.",al={"night watch duskwood","who are night watch"}},{q="Why does Solomon warn me to stay on the roads?",a="Duskwood's wilderness is thick with undead horrors, spiders, and feral beasts. Straying into the underbrush off the paved highway exposes travelers to aggressive predators and ambushes.",al={"duskwood road warning","stay on roads duskwood"}},{q="Where did this questline start?",a="This quest is part of Magistrate Solomon's series of desperate missives. It follows his previous plea sent to Gryan Stoutmantle in Westfall, continuing his exhaustive effort to recruit aid for Lakeshire.",al={"previous quest","messenger quest order"}},{q="Does Darkshire actually have guards to spare?",a="Duskwood is dealing with its own existential crisis, beset by the risen dead, rogue worgen, and lurking monstrosities. The Night Watch barely possesses enough fighters to defend Darkshire itself, making Solomon's plea a bitter long shot.",al={"will darkshire help","does ebonlocke send guards"}}},ang={["faction:Alliance"]="Solomon's frantic letters highlight how fractured and neglected the outlying Alliance towns have become while Stormwind's royal court remains paralyzed.",["race:Human"]="The mission illustrates the shared plight of southern human settlements, each forced to rely on irregular local militias after the kingdom withdrew regular army patrols."},kw={"darkshire","duskwood","ebonlocke","lakeshire","messenger","night watch","redridge","solomon"},rel={"npc:magistrate-solomon","npc:lord-ello-ebonlocke","subzone:lakeshire","subzone:darkshire","zone:duskwood","zone:redridge","topic:night-watch","quest:56"},m={start="Magistrate Solomon",["end"]="Lord Ello Ebonlocke",level="18",faction="Alliance",id=145},src={"Messenger to Darkshire"}}
E["quest:150"] = {t="quest",n="Murloc Poachers",z="redridge",s="Dockmaster Baren of Lakeshire needs adventurers to thin the swelling ranks of murlocs along Lake Everstill before they deplete the town's primary food source. What begins as a practical pest-control bounty raises an unsettling ecological question: why are coastal creatures settling so deep into the inland mountains?",h="Dockmaster Baren of Lakeshire needs adventurers to thin the swelling ranks of murlocs along Lake Everstill...",sec={{t="A Threat to the Town's Pantry",b="Lake Everstill is the lifeblood of Lakeshire, keeping the mountain town fed and supplying its market with fresh catches. When large tribes of murlocs began dropping anchor along the shallows, Dockmaster Baren realized the town faced an ecological crisis. The ravenous fish-men were aggressively scouring the waters, threatening to wipe out the local fish populations entirely if left unchecked.",sp=0},{t="Strange Inland Migration",b="Murlocs are typically coastal scavengers, making their massive presence high up in the Redridge Mountains an unusual sight. Dockmaster Baren openly wonders why they have traveled so far from the open ocean. Whether driven inland by maritime predators, fleeing territorial squabbles, or drawn by Lake Everstill's bountiful waters, their displacement hints at deeper disruptions elsewhere in the region.",sp=0}},faq={{q="Who is Dockmaster Baren?",a="Dockmaster Baren oversees the docks and fishing traffic along the southern shore of Lake Everstill in Lakeshire. He handles waterborne supplies and hires adventurers to defend the lake's resources from aquatic threats.",al={"baren","who gives murloc poachers","dockmaster baren"}},{q="Why are murlocs in Redridge Mountains?",a="Murlocs usually inhabit coastal shores and marshlands, making their presence in the high-altitude Lake Everstill unusual. Dockmaster Baren speculates that these tribes migrated deep inland because they were fleeing something even worse along the coasts.",al={"why are murlocs in lake everstill","murlocs inland redridge","why fishmen in lake"}},{q="What threat do the murlocs pose to Lakeshire?",a="Lakeshire depends heavily on Lake Everstill for fishing and commerce. The murloc tribes are rapidly overfishing the waters, threatening to starve out the town's primary food supply and disrupt the local economy.",al={"why kill murlocs","murloc problem lakeshire","lake everstill fish depleted"}},{q="Why does Dockmaster Baren collect murloc fins?",a="Baren collects eight murloc fins as physical proof of the cull. The fins confirm that adventurers are actively thinning the population along the shores and deterring the encroaching tribes.",al={"why murloc fins","fin bounty lakeshire"}},{q="Are there other tasks involving Lake Everstill's murlocs?",a="Yes, Dockmaster Baren also offers a companion task, Selling Fish, which asks adventurers to gather fresh meat from the lake's fish and murlocs while clearing the waters.",al={"selling fish quest connection","other murloc quests redridge"}},{q="What reward does Dockmaster Baren give for clearing the poachers?",a="After receiving the eight fins, Dockmaster Baren rewards the adventurer with a well-crafted Dwarven Fishing Pole to encourage proper stewardship of the lake's waters.",al={"murloc poachers reward","dwarven fishing pole quest"}}},ang={["faction:Alliance"]="Lakeshire is already hard-pressed by blackrock orcs and gnolls, leaving the Alliance town with little defense to spare for securing its vital food supplies in Lake Everstill.",["race:Human"]="Redridge was once a tranquil vacation haven for the kingdom of Stormwind; seeing its pristine mountain waters overrun by hostile murlocs underscores how far order has deteriorated."},kw={"dockmaster baren","dwarven fishing pole","lake everstill","lakeshire","murloc fin","poachers","redridge"},rel={"quest:127","subzone:lake-everstill","subzone:lakeshire","topic:murloc","zone:redridge"},m={level="20",faction="Alliance",id=150},src={"Murloc Poachers"}}
E["quest:1618"] = {t="quest",n="Gearing Redridge",z="redridge",s="Gearing Redridge is an Alliance blacksmithing trade quest offered by Tormus Deepforge in Ironforge. Aspiring smiths forge sturdy copper equipment to relieve Lakeshire's besieged garrison and aid resident smith Verner Osgood in defending the region from hostile orcs and gnolls.",h="Gearing Redridge is an Alliance blacksmithing trade quest offered by Tormus Deepforge in Ironforge.",sec={{t="A Plea Across Kingdoms",b="While Ironforge’s Great Forge rarely sleeps, dwarven smiths recognize that the Alliance's frontline struggles stretch far beyond Dun Morogh. Down in the Redridge Mountains, the human settlement of Lakeshire finds itself constantly embattled, suffering routine incursions from Blackrock orcs marching out of Stonewatch Keep and roving packs of gnolls infesting the northern ridges. With royal reinforcements from Stormwind slow to arrive, local supplies stay dangerously depleted.",sp=0},{t="The Anvils of Lakeshire",b="Lakeshire's resident blacksmith, Verner Osgood, works practically alone at his outdoor forge trying to mend shattered armor and replace broken weapons. Recognizing the strain on his human counterpart, Tormus Deepforge directs developing smiths to deliver four Runed Copper Belts and four Heavy Copper Mauls straight to Lakeshire. In exchange for bolstering the militia's defensive reserves, Verner gladly passes along finer trade techniques to traveling craftsmen.",sp=0}},faq={{q="Who starts the Gearing Redridge quest?",a="Tormus Deepforge, one of the primary blacksmithing trainers located near the Great Forge in Ironforge, offers this quest to Alliance smiths who have reached adequate proficiency in their trade.",al={"gearing redridge questgiver","who gives gearing redridge","tormus quest"}},{q="Why does Lakeshire need weapons and armor from Ironforge?",a="Lakeshire faces continuous attacks from the Blackrock orcs occupying Stonewatch Keep as well as aggressive local gnolls. The town's solitary smith, Verner Osgood, is completely overwhelmed repairing arms and armoring the militia on his own.",al={"why redridge needs gear","why lakeshire needs weapons","redridge supply shortage"}},{q="Who receives the shipment in Redridge?",a="The shipment is delivered to Verner Osgood, the local blacksmith stationed near the forge in the lakeside town of Lakeshire.",al={"where to turn in gearing redridge","verner osgood location","redridge blacksmith turnin"}},{q="What equipment must be forged for the task?",a="You must supply four Runed Copper Belts and four Heavy Copper Mauls. These demonstrate both protective plating and heavy striking craftsmanship.",al={"gearing redridge items needed","materials for gearing redridge","what to craft for tormus"}},{q="What threats are troubling Redridge at this time?",a="The primary dangers pressing against Lakeshire are the Blackrock orc clans entrenching themselves within Stonewatch Keep and violent gnoll packs prowling throughout the northern foothills.",al={"redridge enemies","who is attacking lakeshire","redridge threats"}},{q="What reward does Verner Osgood offer in return?",a="Relieved from the frantic burden of outfitting every guardsman from scratch, Verner takes the time to teach you advanced blacksmithing techniques.",al={"verner osgood training","reward for gearing redridge","what do i get"}}},ang={["profession:Blacksmithing"]="This task marks a rite of passage for apprentice blacksmiths, testing your ability to mass-produce durable weapons and protective armor on demand for an active warfront.",["faction:Alliance"]="The delivery illustrates vital mutual aid between Ironforge and the beleaguered human townships of the south, stepping in where Stormwind's divided leadership has lagged.",["race:Dwarf"]="Dwarven craftsmanship is the backbone of the Alliance war effort, and Tormus ensures Ironforge's prodigies use their craft to aid beleaguered allies.",["race:Human"]="For humans of the southern kingdoms, receiving metalwork forged in Khaz Modan provides desperately needed relief against the aggressive Blackrock remnants."},kw={"blackrock orcs","blacksmithing","gnolls","heavy copper maul","lakeshire","redridge","runed copper belt","stonewatch","tormus deepforge","verner osgood"},rel={"npc:tormus-deepforge","npc:verner-osgood","zone:redridge","zone:ironforge","subzone:stonewatch-keep","topic:gnoll"},m={start="Tormus Deepforge",["end"]="Verner Osgood",faction="Alliance",id=1618},src={"Gearing Redridge"}}
E["quest:169"] = {t="quest",n="Wanted: Gath'Ilzogg",z="redridge",s="Wanted: Gath'Ilzogg is an Alliance bounty posted in Redridge Mountains targeting the warlord behind the Blackrock invasion of Stonewatch. Magistrate Solomon offers a generous reward for anyone daring enough to assault the conquered keep and bring back the commander's severed head.",h="Wanted: Gath'Ilzogg is an Alliance bounty posted in Redridge Mountains targeting the warlord behind the...",sec={{t="The Warlord of Stonewatch",b="Gath'Ilzogg is the brutal commander directing Blackrock clan raids across the Redridge Mountains. Under his direction, the orcs stormed and conquered Stonewatch Keep, turning a former human bastion into a fortified staging ground for assaults on the surrounding settlements. From the keep's highest ramparts, he plots further incursions into Lakeshire, threatening to cut Redridge off from the rest of the kingdom.",sp=0},{t="A Town Pushed to the Brink",b="With Stormwind's royal army failing to deploy reinforcements to the border regions, Magistrate Solomon has taken matters into his own hands. The township of Lakeshire simply lacks the military manpower to retake Stonewatch Keep by force. By posting a public bounty on Gath'Ilzogg, Solomon aims to decapitate the Blackrock leadership and spark the first stage of reclaiming the keep for the crown.",sp=0}},faq={{q="Who is Gath'Ilzogg?",a="Gath'Ilzogg is an orc warlord leading the Blackrock clan forces occupying Stonewatch. He directed the conquest of the keep and is responsible for frequent deadly raids against the human settlers of Lakeshire.",al={"gath'ilzogg lore","who is gathilzogg","blackrock leader redridge"}},{q="Where can Gath'Ilzogg be found?",a="He is entrenched at the very top of Stonewatch Keep, located in the eastern crags of the Redridge Mountains. He is heavily guarded by his Blackrock champions and bodyguards.",al={"gath'ilzogg location","where is gathilzogg","stonewatch boss location"}},{q="Why is Magistrate Solomon offering a bounty instead of sending soldiers?",a="Lakeshire's local town guard is stretched to the limit, and the crown in Stormwind has not sent the required troops to relieve the region. Magistrate Solomon has to rely on mercenaries and independent adventurers to handle major threats.",al={"why a bounty","where are stormwind soldiers","lakeshire guard help"}},{q="What happens after Gath'Ilzogg is killed?",a="Magistrate Solomon sees the warlord's death as the crucial first step toward clearing out the orc infestation and eventually reclaiming Stonewatch Keep for the Kingdom of Stormwind, though the Blackrock presence in the region remains heavy.",al={"is stonewatch retaken","after gath'ilzogg"}},{q="Why did the Blackrock orcs invade Stonewatch Keep?",a="The Blackrock clan uses Stonewatch Keep as a fortified forward base. Sitting high in the mountains above Redridge, it gives them strategic control over the passes and a direct launching point for raids against human settlements.",al={"why are blackrock in redridge","why stonewatch taken"}},{q="Who claims the bounty once Gath'Ilzogg is dead?",a="The bounty must be delivered directly to Magistrate Solomon in Lakeshire's town hall, accompanied by Gath'Ilzogg's head as definitive proof of his defeat.",al={"who to turn in gathilzogg","gathilzogg quest turn in"}}},ang={["faction:Alliance"]="Striking down Gath'Ilzogg eliminates one of the most immediate military threats to the kingdom's eastern borders, buying vital breathing room for the citizens of Lakeshire.",["race:Human"]="For the people of Stormwind, Stonewatch Keep was a hard-won fortification; Gath'Ilzogg's slaughter of innocents during its fall makes this bounty a matter of bitter vengeance.",["class:Warrior"]="Breaching the summit of Stonewatch Keep means facing the hardened veteran warriors and brute strength of the Dark Horde's frontline command."},kw={"blackrock","bounty","gath'ilzogg","lakeshire","magistrate solomon","redridge","stonewatch","wanted poster"},rel={"subzone:stonewatch-keep","subzone:stonewatch","npc:magistrate-solomon","topic:blackrock-clan","subzone:lakeshire","zone:redridge","topic:stormwind-kingdom"},m={start="Wanted: Gath'Ilzogg",["end"]="Magistrate Solomon",level="26",faction="Alliance",id=169},src={"Wanted: Gath'Ilzogg (quest)"}}
E["quest:1699"] = {t="quest",n="The Rethban Gauntlet",z="redridge",s="The Rethban Gauntlet is an eccentric endurance trial devised by the dwarven brewer Yorus Barleybrew in Lakeshire. Challengers must drink a potent swig of his family's fiery Barleybrew Scalder and sprint north into the gnoll-infested Rethban Caverns and back before an hour elapses.",h="The Rethban Gauntlet is an eccentric endurance trial devised by the dwarven brewer Yorus Barleybrew in...",sec={{t="A Dwarven Dare",b="In the town of Lakeshire, where grim talk of gnoll raids and missing town guards usually dominates the inn, the dwarf Yorus Barleybrew brings a distinctly dwarven flavor of entertainment. His self-styled challenge, the Rethban Gauntlet, tests an adventurer's mettle, speed, and liver all at once. Participants are required to down a draught of his family's signature concoction, Barleybrew Scalder, right before setting off on foot toward the northern foothills.",sp=0},{t="Running the Wild Hills",b="The trial is far more perilous than a simple drunken footrace. Between Lakeshire and the destination lies Redridge territory teeming with aggressive Redridge gnolls. To successfully complete the gauntlet, the runner must fight or slip past the packs, reach the first fork inside the dark tunnels of Rethban Caverns, and hustle back to Yorus within an hour—all while battling the overwhelming, staggering effects of the fiery dwarven alcohol.",sp=0}},faq={{q="Who issues the Rethban Gauntlet?",a="Yorus Barleybrew, a dwarven brewer staying in Lakeshire, challenges travelers to the run to prove their fortitude and test his brew.",al={"who gives rethban gauntlet","yorus barleybrew quest","who starts the gauntlet"}},{q="What makes this challenge particularly difficult?",a="Aside from navigating the gnoll packs roaming the Redridge foothills within a strict one-hour time limit, runners must first swallow Barleybrew Scalder, an intense beverage that leaves them severely intoxicated and struggling to maintain their balance.",al={"why is rethban gauntlet hard","barleybrew scalder effect"}},{q="Where are the Rethban Caverns located?",a="The caverns sit in the northern foothills of Redridge Mountains, northwest of Lakeshire. The path leads north past local homesteads toward the crags inhabited by gnoll packs.",al={"rethban caverns location","where is rethban","how to get to rethban caverns"}},{q="How far into the caves must a runner go?",a="Challengers do not need to clear the entire cavern; they only need to reach the first interior fork before turning around and racing back to Lakeshire.",al={"rethban caverns objective","how far inside rethban"}},{q="Who inhabits the hills and caverns along the route?",a="The area surrounding the route and inside the caverns is overrun by hostile Redridge gnolls, making stealth or swift combat essential for surviving the trek.",al={"what enemies in rethban","what is in rethban caverns"}},{q="Where does this challenge lead next?",a="Surviving the gauntlet proves your endurance to Yorus Barleybrew, opening the way to further tasks in the region such as seeking out the shieldsmith Furen Longbeard in Stormwind.",al={"rethban gauntlet follow up","what quest comes after rethban gauntlet"}}},ang={["race:Dwarf"]="Dwarves will feel right at home with Yorus's boisterous concept of fun: mixing potent family liquor with dangerous mountain sprints.",["faction:Alliance"]="While Lakeshire struggles under the threat of gnoll incursions, braving the gauntlet helps thin out enemy patrols prowling near the northern caves."},kw={"barleybrew scalder","gnolls","lakeshire","redridge","rethban caverns","rethban gauntlet","timed run","yorus barleybrew"},rel={"quest:1698","subzone:rethban-caverns","subzone:lakeshire","topic:gnoll","quest:1702","npc:martie-jainrose","zone:redridge"},m={start="Yorus Barleybrew",level="22",faction="Alliance",id=1699},src={"The Rethban Gauntlet"}}
E["quest:178"] = {t="quest",n="Theocritus' Retrieval",z="redridge",s="Theocritus' Retrieval begins when an adventurer in Redridge finds a magical trinket carried by the local gnolls, only to hear a distant voice echoing through it. The speaker is Theocritus, High Mage of Tower of Azora, who has successfully intercepted the gnolls' mystical network and urgently requests the pendant be brought to him for study.",h="Theocritus' Retrieval begins when an adventurer in Redridge finds a magical trinket carried by the local...",sec={{t="A Voice in the Stone",b="While fighting off the savage Shadowhide gnolls across the Redridge Mountains, travelers sometimes stumble across an enchanted trinket known as a Shadowhide Pendant. Instead of guttural barking or curses, touching the object triggers a calm, disembodied voice belonging to Theocritus, a human mage residing in Tower of Azora across the border in Elwynn Forest. The transmission is the result of long, painstaking research aimed at breaking into the dark sorceries directing the gnoll packs.",sp=0},{t="Subverting Morganth's Network",b="The Shadowhide gnolls are not acting purely on primal instinct; they answer to Morganth, a rogue dark caster hidden away in the mountains. Morganth crafts and distributes these enchanted pendants to transmit commands directly to his beastly pawns. Theocritus spent months unravelling the frequency of Morganth's sending spells. When an adventurer delivers the faded pendant back to Tower of Azora, the wizard confirms that his scrying reached the talisman, opening the door to reverse-engineering an attack to disable the gnolls entirely.",sp=1}},faq={{q="Who is Theocritus?",a="Theocritus is a high mage of the Alliance stationed at the Tower of Azora in eastern Elwynn Forest. He keeps a watchful eye over regional disturbances and dedicates much of his magical studies to countering dark magic encroaching from Redridge.",al={"theocritus lore","who is talking through the pendant","tower of azora mage"}},{q="Why were the Shadowhide gnolls carrying magical pendants?",a="The pendants are magical conduits crafted by the renegade wizard Morganth. Through them, he sends mental commands and orchestrates the movements of the Shadowhide clan from afar.",al={"why do gnolls have pendants","shadowhide pendant purpose","gnoll magic item"}},{q="Why was the voice delayed when Theocritus sent it?",a="Theocritus cast his message weeks before an adventurer recovered the stone, initially believing his spell had dissipated and failed. Penetrating Morganth's dark wards and establishing a link over such a vast distance caused a significant magical delay.",al={"delayed message","why did theocritus take weeks","faded pendant delay"}},{q="What does Theocritus hope to achieve with the retrieved pendant?",a="By deciphering the specific magical frequency tying the pendant to Morganth, Theocritus hopes to reverse the flow of magic. His ultimate ambition is to broadcast an offensive spell through the network that could instantly immobilize every gnoll wearing one.",al={"theocritus plan","what will theocritus do","why study the pendant"}},{q="Where does this quest chain lead next?",a="Delivering the pendant directly leads into 'A Watchful Eye', sending adventurers to observe Morganth's stronghold at the Tower of Ilgalar and eventually bringing an end to the rogue wizard's influence over Redridge.",al={"next quest after theocritus retrieval","morganth chain","what happens next"},sp=1}},ang={["class:Mage"]="Theocritus's work demonstrates an ingenious application of abjuration and divination, hacking another sorcerer's network to deliver counter-spells over vast distances.",["faction:Alliance"]="The coordination between Tower of Azora in Elwynn and the beleaguered defenders of Lakeshire shows how local mages step in where Stormwind's royal army has left garrisons understaffed."},kw={"elwynn","gnolls","morganth","pendant","redridge","shadowhide","theocritus","tower of azora"},rel={"quest:94","quest:248","quest:249","npc:theocritus","topic:gnoll","zone:redridge","zone:elwynn"},m={start="Glowing Shadowhide Pendant",["end"]="Theocritus",level="23",faction="Alliance",id=178},src={"Theocritus' Retrieval"}}
E["quest:180"] = {t="quest",n="Wanted: Lieutenant Fangore",z="redridge",s="Wanted: Lieutenant Fangore is a local bounty posted in Lakeshire by Magistrate Solomon. It calls on adventurers to hunt down Lieutenant Fangore, the vicious chieftain of the Shadowhide gnolls encroaching upon the Redridge Mountains. Eliminating him strikes a direct blow against the renegade sorcerer Morganth, whom the gnolls serve.",h="Wanted: Lieutenant Fangore is a local bounty posted in Lakeshire by Magistrate Solomon.",sec={{t="A Town Under Siege",b="Lakeshire sits in a desperate position. With Stormwind's army stretched thin and King Varian Wrynn mysteriously absent, Highlord Bolvar Fordragon has left frontier settlements like Redridge to look after themselves. The Shadowhide clan has grown increasingly bold, raiding trade routes, burning farmsteads, and pressing right up against the town's perimeter. Magistrate Solomon relies on posted bounties to draw mercenary blades where royal soldiers will not march.",sp=0},{t="Morganth's Lieutenant",b="Lieutenant Fangore is not merely a marauding beast; he operates as an enforcer for Morganth, a rogue dark wizard lurking in the hills of Redridge. Under Fangore's command, the Shadowhide gnolls coordinate their strikes rather than fighting as disjointed scavengers, threatening to completely sever Lakeshire from Elwynn Forest. Striking off Fangore's paw provides Magistrate Solomon with proof that Morganth's brute vanguard has been broken.",sp=0}},faq={{q="Who is Lieutenant Fangore?",a="Lieutenant Fangore is a powerful leader within the Shadowhide gnoll clan residing in Redridge. He coordinates the gnoll raiding parties and enforces the will of Morganth, a dark sorcerer threatening Lakeshire.",al={"lieutenant fangore","who is fangore","fangore lore"}},{q="Who posted the bounty for Lieutenant Fangore?",a="The bounty was issued by Magistrate Solomon, the town leader of Lakeshire, who is attempting to secure the perimeter of Redridge against hostile gnolls and dark spellcasters.",al={"who posted the bounty","who wants fangore dead","magistrate solomon fangore"}},{q="Why doesn't Stormwind send soldiers to handle the gnolls?",a="Stormwind is paralyzed by the sudden disappearance of King Varian Wrynn and domestic unrest. Highlord Bolvar Fordragon and the House of Nobles have refused to send regular army detachments to peripheral towns like Lakeshire, forcing Magistrate Solomon to hire mercenary adventurers.",al={"why no stormwind guard","where are stormwind soldiers","why isn't the army helping"}},{q="What proof is required to claim the bounty?",a="Magistrate Solomon requires the severed paw of Lieutenant Fangore as physical proof that the Shadowhide warlord has been slain.",al={"fangore proof","fangores paw","what item for turn in"}},{q="Who is Morganth and why does Fangore follow him?",a="Morganth is a rogue human spellcaster practicing dark magic from a tower in the Redridge Mountains. He has bent the Shadowhide gnolls to his will, using Lieutenant Fangore as an enforcer to terrorize the local countryside.",al={"who is morganth","why do gnolls follow morganth","fangore morganth"}},{q="What are the Shadowhide gnolls?",a="The Shadowhide clan is a ferocious tribe of gnolls inhabiting the crags and forests of the Redridge Mountains. Known for their aggression and brutal ambush tactics, they have plagued the settlers of Lakeshire for years.",al={"shadowhide clan","redridge gnolls","shadowhide lore"}}},ang={["faction:Alliance"]="Lakeshire stands as a critical bastion for the Alliance in Redridge; clearing out Fangore prevents the settlement from falling into total isolation.",["race:Human"]="Human defenders feel the bite of Stormwind's neglect firsthand in Redridge, making personal intervention against gnoll chieftains a matter of hometown survival."},kw={"fangore","gnoll","lakeshire","lieutenant fangore","magistrate solomon","morganth","redridge","shadowhide"},rel={"npc:magistrate-solomon","quest:249","subzone:lakeshire","zone:redridge","topic:gnoll","topic:stormwind-kingdom"},m={start="Wanted: Lieutenant Fangore",["end"]="Magistrate Solomon",level="26",faction="Alliance",id=180},src={"Wanted: Lieutenant Fangore (quest)"}}
E["quest:19"] = {t="quest",n="Tharil'zun",z="redridge",s="Marshal Marris places a bounty on Tharil'zun, the cunning leader of the Blackrock outrunners harassing the roads near Stonewatch Keep. Striking him down serves as a critical step in breaking the Blackrock clan's hold over northern Redridge. Bringing his severed head back to Lakeshire marks a hard-fought victory for the embattled town watch.",h="Marshal Marris places a bounty on Tharil'zun, the cunning leader of the Blackrock outrunners harassing the...",sec={{t="The Road to Stonewatch",b="The winding pass between Lakeshire and Stonewatch Keep has become a gauntlet of sudden ambushes. Blackrock outrunners and renegades prowl the rocky ridges, cutting off scouts and threatening any reinforcements attempting to push toward the fortress. Marshal Marris identifies Tharil'zun as the commander orchestrating these coordinated strikes, declaring his elimination necessary to prevent Lakeshire from being entirely hemmed in.",sp=0},{t="Decapitating the Outrunners",b="Tharil'zun represents a dangerous breed of battlefield leader: vicious, crafty, and capable of coordinating the disparate orc raiders into an effective raiding force. Taking his head inside the shadow of Stonewatch requires cutting through entrenched Blackrock outposts. His death breaks the cohesion of the outrunner patrols, clearing a path for the Alliance to confront the garrison entrenched within the keep itself.",sp=0}},faq={{q="Who is Tharil'zun?",a="Tharil'zun is a formidable Blackrock orc commander responsible for leading the outrunners and renegades staging ambushes along the trails between Lakeshire and Stonewatch Keep.",al={"who is tharilzun","tharil'zun lore","tharilzun boss"}},{q="Where can Tharil'zun be found?",a="Tharil'zun is stationed near Stonewatch Keep in northeastern Redridge, commanding the outrunners who patrol the surrounding passes and outposts.",al={"where is tharil'zun","tharilzun location","find tharil'zun"}},{q="Why does Marshal Marris want his head?",a="Marris recognizes Tharil'zun as the cunning tactician directing the ambushes harassing Redridge. Demanding his head ensures the outrunner leadership is severed and offers undeniable proof of the threat's elimination.",al={"why kill tharilzun","tharilzun bounty reason"}},{q="What happens after Tharil'zun is defeated?",a="Eliminating Tharil'zun cripples the outrunners' coordination, allowing Lakeshire's defenders and adventurers to push deeper into Stonewatch Keep to confront the main Blackrock garrison.",al={"quest after tharilzun","what follows tharil'zun"}},{q="Why are Blackrock orcs in Redridge Mountains?",a="Remnants of the Blackrock clan pushed south from the Burning Steppes into Redridge, fortifying old human outposts like Stonewatch Keep to threaten the Eastern Kingdoms while Stormwind's military remains stretched thin.",al={"why are blackrock orcs in redridge","stonewatch orcs background"}},{q="What prerequisite must be completed before hunting Tharil'zun?",a="Marshal Marris requires adventurers to first prove their mettle by thinning the invading forces in the quest 'Blackrock Menace' before sending them after Tharil'zun himself.",al={"tharilzun prereq","how to unlock tharilzun quest"}}},ang={["faction:Alliance"]="Lakeshire stands largely isolated without direct reinforcements from Stormwind, making the bounty on Tharil'zun a vital local measure to prevent the town from being besieged.",["race:Human"]="The Blackrock presence in Redridge is a painful reminder of the First and Second Wars, and slaying Tharil'zun reclaims ground stolen from the kingdom.",["race:Orc"]="Tharil'zun belongs to the dark remnants of the Old Horde under the Blackrock banner, serving masters who reject Thrall's new order across the sea."},kw={"blackrock","lakeshire","marshal marris","outrunners","redridge","stonewatch","stonewatch keep","tharil'zun","tharilzun"},rel={"npc:marshal-marris","quest:20","subzone:stonewatch-keep","subzone:stonewatch","zone:redridge"},m={start="Marshal Marris",level="25",faction="Alliance",id=19},src={"Tharil'zun (quest)"}}
E["quest:20"] = {t="quest",n="Blackrock Menace",z="redridge",s="Marshal Marris of Lakeshire tasks adventurers with culling the aggressive Blackrock orcs encroaching upon Redridge. By seizing their battleworn axes, the town's defenders hope to break the siege tightening around the settlement.",h="Marshal Marris of Lakeshire tasks adventurers with culling the aggressive Blackrock orcs encroaching upon...",sec={{t="A Town Under Siege",b="Lakeshire finds itself hemmed in on multiple fronts, but none pose so dire a threat as the Blackrock orcs spilling over from the fiery Burning Steppes. Having pushed south into Redridge, these veteran raiders have seized strongholds and roam the craggy passes. Their presence keeps the townspeople effectively penned inside the settlement, cutting off trade, foraging, and travel along the northern roads.",sp=0},{t="Striking the Vanguard",b="Marshal Marris, commander of the beleaguered Lakeshire guard, cannot spare a detachment to assault their positions outright. Instead, he enlists roaming adventurers to bleed the invaders' forward scouts and foot soldiers. By demanding their crude, battleworn axes as proof of death, Marris seeks to thin the invaders' numbers both around Stonewatch to the north and in the rugged pockets of southeastern Redridge.",sp=0}},faq={{q="Where did these Blackrock orcs come from?",a="They marched south across the jagged mountain passes leading out of the Burning Steppes, their ancestral stronghold around Blackrock Mountain.",al={"where are the orcs from","blackrock invasion redridge","why are orcs in redridge"}},{q="Who issues this task?",a="Marshal Marris, the senior military officer tasked with defending Lakeshire and maintaining order amid the town's growing encirclement.",al={"who gives blackrock menace","blackrock menace quest giver","marshal marris quest"}},{q="Where can the Blackrock invaders be found?",a="They occupy the northern highlands around Stonewatch Keep and have also established footholds in the southeastern pocket of the Redridge Mountains.",al={"where are blackrock orcs","battleworn axe locations","redridge orc camps"}},{q="Why does Marshal Marris ask for battleworn axes?",a="The battleworn axes serve as indisputable physical proof that an adventurer has actively engaged and slain the Blackrock marauders threatening the valley.",al={"why axes","proof of death","battleworn axe purpose"}},{q="What happens after these scouts are defeated?",a="Thinning the vanguard leads Marshal Marris to order a strike against the local Blackrock leader entrenched in the mountains, Tharil'zun.",al={"what comes after blackrock menace","next quest after blackrock menace","who leads the orcs"},sp=1},{q="Are the orcs affiliated with Thrall's Horde?",a="No. The Blackrock clan operating here consists of remnants from the Old Horde who remain violently hostile to the Alliance and operate independently of Thrall's new Horde in Kalimdor.",al={"are these horde orcs","is blackrock clan part of thrall horde","friendly orcs in redridge"}}},ang={["faction:Alliance"]="Defending Lakeshire is critical for holding the southern border of the kingdom of Stormwind against old-world adversaries.",["race:Human"]="The Blackrock clan destroyed the original Kingdom of Stormwind in the First War; facing them again in Redridge evokes bitter historical grief.",["class:Warrior"]="Clashing shield-to-shield against seasoned Blackrock marauders offers a brutal test of martial discipline and frontline fortitude."},kw={"axes","blackrock","burning steppes","lakeshire","marris","orcs","redridge","stonewatch","tharil'zun"},rel={"npc:marshal-marris","quest:19","subzone:lakeshire","subzone:stonewatch","subzone:stonewatch-keep","zone:redridge","zone:burningsteppes"},m={start="Marshal Marris",level="21",faction="Alliance",id=20},src={"Blackrock Menace"}}
E["quest:219"] = {t="quest",n="Missing In Action",z="redridge",s="Missing In Action is an Alliance escort mission in the Redridge Mountains to rescue Corporal Keeshan from Blackrock orc captivity. After his regiment was wiped out in the hills, Keeshan was knocked unconscious and dragged into a cave fortress. Guiding the wounded soldier safely back to Lakeshire helps the local garrison confirm the grim fate of their missing men.",h="Missing In Action is an Alliance escort mission in the Redridge Mountains to rescue Corporal Keeshan from...",sec={{t="A Regiment Overrun",b="The Redridge Mountains have grown increasingly perilous as Blackrock orcs descend from the northern peaks. Patrols sent out by the town guard frequently run into ambushes, and Corporal Keeshan's unit suffered the worst of it. Outnumbered and overwhelmed, most of the soldiers in his regiment were cut down on the spot. Keeshan survived only because a crushing blow knocked him cold before he could be executed, allowing the orcs to drag him back to their cave as a prisoner.",sp=0},{t="Escape from the Caves",b="Battered, concussed, and held deep within enemy territory, Keeshan could not make the trek back down the mountain alone. Escorting him down to the safety of Lakeshire takes him past swarming orc warbands that occupy the ridgelines. Reaching Town Hall alive brings sorely needed relief to Marshal Marris, who has been trying to piece together what happened to the missing regiment while bracing Lakeshire for further attacks.",sp=0}},faq={{q="Who is Corporal Keeshan?",a="Corporal Keeshan is an Alliance infantryman stationed in the Redridge Mountains. During a patrol in the rocky hills, his regiment was overwhelmed by Blackrock orcs, leaving him the sole known survivor before he was dragged away into captivity.",al={"corporal keeshan","who is keeshan","keeshan lore"}},{q="Where was Corporal Keeshan captured?",a="He is held captive deep inside an orc-infested cave in the northern hills of Redridge, surrounded by hostile Blackrock warriors.",al={"where is keeshan","keeshan location","keeshan cave"}},{q="What happened to the rest of Keeshan's unit?",a="According to Keeshan, the Blackrock orcs ambushed and overpowered his regiment, killing nearly all of the men during the initial skirmish.",al={"keeshan squad","what happened to the regiment","keeshan men"}},{q="Who sends players to rescue Keeshan?",a="The quest begins directly with Corporal Keeshan himself inside his prison cave when Alliance adventurers discover and liberate him.",al={"who starts missing in action","quest giver","where to pick up missing in action"}},{q="Where does Keeshan go after being freed?",a="He must be escorted down the mountainside to the town of Lakeshire, where he reports in to Marshal Marris at the town hall.",al={"turn in missing in action","where does keeshan run","keeshan destination"}},{q="Why are the Blackrock orcs in Redridge?",a="The Blackrock clan pushes south from their strongholds in the Burning Steppes into Redridge, threatening the poorly reinforced settlement of Lakeshire and ambushing Kingdom patrols.",al={"blackrock orcs redridge","why orcs in lakeshire","blackrock invasion"}}},ang={["faction:Alliance"]="Lakeshire's garrison is strained to the breaking point, making every rescued soldier vital for the Kingdom's defenses against the Blackrock clan.",["class:Warrior"]="Breaking Keeshan out of an armed orc encampment requires holding the frontline against waves of relentless Blackrock attackers while shielding a concussed comrade."},kw={"blackrock orcs","corporal keeshan","escort","keeshan","lakeshire","marshal marris","missing in action","redridge"},rel={"npc:marshal-marris","zone:redridge","topic:alliance"},m={start="Corporal Keeshan",["end"]="Marshal Marris",level="25",faction="Alliance",id=219},src={"Missing In Action"}}
E["quest:2282"] = {t="quest",n="Alther's Mill",z="redridge",s="Alther's Mill is a pivotal training assignment given to Alliance rogues by Lucius in Lakeshire. Dispatched to the nearby mill with a set of thieves' tools, initiates are tasked with infiltrating an area under Blackrock orc scrutiny to crack a locked chest and retrieve a token of thievery.",h="Alther's Mill is a pivotal training assignment given to Alliance rogues by Lucius in Lakeshire.",sec={{t="A Test of Grace and Finesse",b="In Lakeshire, rogue instructors do not bother with abstract lectures when a locked chest can teach the lesson faster. Lucius sends promising operatives northeast along the road to Alther's Mill, equipping them with their first set of thieves' tools. To earn their formal Certificate of Thievery, novices must slip into the abandoned mill, pick open Lucius's personal lockbox, and bring back the token cached within.",sp=0},{t="Shadows Around the Saws",b="While Alther's Mill was once an ordinary lumber outpost, it has recently drawn the dangerous attention of the Blackrock orcs encroaching upon Redridge. Lucius gleefully treats the encroaching warmongers as an added layer of practical examination. Prowling through enemy-held territory to pick locks undetected is precisely the kind of trial SI:7 expects its agents to survive.",sp=0}},faq={{q="What is the purpose of the mission to Alther's Mill?",a="It serves as the practical field examination for Alliance rogues learning the art of lockpicking. Lucius provides you with thieves' tools and requires you to retrieve a specific token from a locked footlocker to prove your finesse.",al={"why go to althers mill","quest purpose","what does this quest do"}},{q="Who is Lucius?",a="Lucius is a seasoned rogue trainer operating out of Lakeshire in the Redridge Mountains. He has spent years schooling roguish recruits sent his way by contacts throughout the Alliance, testing their stealth and manual dexterity.",al={"who is lucius","lucius lakeshire","who gives this quest"}},{q="Where is Alther's Mill located?",a="Alther's Mill lies just off the road slightly northeast and east of Lakeshire, nestled against the foothills before the higher mountain passes.",al={"where is the mill","althers mill location","how do i find althers mill"}},{q="Why are there orcs around Alther's Mill?",a="Blackrock clan orcs have descended from the heights of Stonewatch and the burning ridges above, raiding human settlements and establishing forward footholds throughout Redridge, including the area around the abandoned mill.",al={"why are orcs here","blackrock orcs redridge","who controls althers mill"}},{q="What reward does Lucius grant upon completing the task?",a="Lucius awards you the Certificate of Thievery, acknowledging that you have mastered the basics of tumblers and lockpicks and can now operate as a fully certified field rogue.",al={"what is the reward","certificate of thievery","quest completion reward"}},{q="How does this quest fit into rogue training across the Alliance?",a="Rogues across Alliance lands are directed by contacts like Mathias Shaw's SI:7 handlers in Stormwind to rendezvous with Lucius in Lakeshire. The assignment to Alther's Mill forms the practical climax of their fundamental field training.",al={"rogue quest chain","si7 connection","redridge rendezvous followup"}}},ang={["class:Rogue"]="This rite of passage provides your essential lockpicking tools and field credentials, testing your patience and stealth amidst patrolling Blackrock orcs.",["faction:Alliance"]="Training specialized thieves and infiltrators on the fringes of Lakeshire bolsters Alliance intelligence while keeping a close eye on Blackrock movements."},kw={"alther's mill","blackrock orcs","lakeshire","lockpicking","lucius","redridge mountains","si:7","thieves tools","token of thievery"},rel={"npc:lucius","quest:2281","quest:2300","subzone:lakeshire","zone:redridge"},m={start="Lucius",level="20",faction="Alliance",id=2282},src={"Alther's Mill (quest)"}}
E["quest:244"] = {t="quest",n="Encroaching Gnolls",z="redridge",s="Encroaching Gnolls is an Alliance task that alerts the town guard of Lakeshire to gnolls prowling dangerously close to the Elwynn border. Guard Parker discovers encampments clustering along the border pass, sending travelers ahead to warn Deputy Feldon. The news confirms Lakeshire's growing fears that the beastmen are threatening to cut off Redridge entirely.",h="Encroaching Gnolls is an Alliance task that alerts the town guard of Lakeshire to gnolls prowling dangerously...",sec={{t="Eyes on the Border",b="The road linking Elwynn Forest to Redridge Mountains should be one of the most secure transit routes in the kingdom, but Stormwind's thinned forces leave it minimally defended. Guard Parker is stationed along the western border trail to monitor movement. While he manages to keep the gravel road passable for supply wagons, his scouting sweeps north and east reveal that gnoll warbands have advanced from the crags, establishing camps alarmingly near the road.",sp=0},{t="A Town Under Siege",b="Upon receiving the alert near the Lakeshire bridge, Deputy Feldon realizes the situation is worse than anticipated. The Redridge gnolls are not merely raiding the town's perimeter; their forward presence near the Elwynn border implies they could encircle Lakeshire and push into the kingdom's heartland. With Stormwind ignoring pleas for reinforcements, Lakeshire's watch is ill-prepared to handle a two-front threat.",sp=0}},faq={{q="Who starts this quest?",a="Guard Parker offers this quest along the road in western Redridge Mountains, near the border crossing into Elwynn Forest.",al={"quest giver","where to start","guard parker location"}},{q="Where can I find Deputy Feldon?",a="Deputy Feldon is stationed in Lakeshire, patrolling the grounds just south of the town's large stone bridge.",al={"feldon location","who is deputy feldon","turn in location"}},{q="Why are the gnolls an issue on the road?",a="The road to Elwynn Forest is Lakeshire's only safe overland lifeline to the rest of the kingdom. If gnolls seize the western slopes, the town is effectively cut off from supplies and escape.",al={"why gnolls matter","redridge gnoll problem","road danger"}},{q="Why doesn't Stormwind send help to Lakeshire?",a="With King Varian Wrynn missing and the realm strained by unrest, Highlord Bolvar and the court have refused to commit royal troops to Redridge, leaving Lakeshire's defense entirely to local deputies and volunteers.",al={"where are stormwind guards","no reinforcements","lakeshire defense"}},{q="What happens after reporting the gnolls?",a="Deputy Feldon asks you to follow up by scouting the gnoll camps more closely in the quest Assessing the Threat to determine the true strength of their numbers.",al={"next quest","chain follow up"}},{q="Which gnoll packs are encroaching here?",a="The Redridge gnolls, gathering in the hills as the Redridge Gnoll Pack, have become increasingly bold and coordinated as human control over the region weakens.",al={"which gnolls","redridge gnoll clans"}}},ang={["race:Human"]="The encroachment of beastmen within sight of Elwynn Forest highlights how vulnerable the kingdom's core territories have become in the king's absence.",["faction:Alliance"]="Lakeshire's isolation threatens the Alliance's eastern front, making border intelligence critical for travelers and supply convoys."},kw={"assessing the threat","deputy feldon","elwynn border","encroaching gnolls","guard parker","lakeshire","redridge"},rel={"quest:246","npc:deputy-feldon","subzone:lakeshire","topic:gnoll","zone:redridge"},m={start="Guard Parker",["end"]="Deputy Feldon",level="16",faction="Alliance",id=244},src={"Encroaching Gnolls"}}
E["quest:246"] = {t="quest",n="Assessing the Threat",z="redridge",s="Assessing the Threat is a defensive scouting operation commissioned by Deputy Feldon in Lakeshire. With the local garrison stretched thin and denied reinforcements from Stormwind, adventurers are hired to cull encroaching gnoll packs along the southern road and measure the strength of the growing menace.",h="Assessing the Threat is a defensive scouting operation commissioned by Deputy Feldon in Lakeshire.",sec={{t="A Strained Frontier",b="The town of Lakeshire is fighting for its survival on multiple fronts. Between Blackrock orc warbands descending from the heights and aggressive gnoll packs harassing the valleys, the local defenders cannot spare troops for standard reconnaissance patrols. When initial reports confirmed gnolls encroaching on the border, Deputy Feldon turned to outside help. Rather than committing regular guardsmen to the wilderness, the town pays traveling champions to test the enemy's strength firsthand.",sp=0},{t="Reconnaissance by Force",b="The mission sends scouts along the southern road of Redridge, cutting into the encampments of Redridge Mongrels and Poachers. This is intelligence gathering by attrition: clearing out vanguard scouts, disrupting supply lines, and gauging whether the packs are simply roaming scavengers or part of an organized martial presence threatening the settlement. The bloody skirmishing provides Feldon the concrete numbers he needs to plan Lakeshire's strained defense.",sp=0}},faq={{q="Why does Deputy Feldon send adventurers instead of town guards?",a="Lakeshire's garrison is critically undermanned. With no reinforcements arriving from Stormwind City and hostile forces pressing in from all directions, the town guard cannot spare the soldiers required for extended patrols along the southern road.",al={"why hire adventurers","where are the guards","lakeshire guard shortage"}},{q="Where are the gnolls located for this mission?",a="The Redridge Mongrels and Poachers form loose warcamps along the southern road and low foothills of the Redridge Mountains, south of Lakeshire and near the border passes.",al={"where are redridge mongrels","gnoll locations redridge","southern road gnolls"}},{q="What is the strategic purpose of culling these gnolls?",a="The operation serves two purposes: it pushes back forward scouts encroaching on the road, and it brings back firsthand military intelligence regarding the size, weapons, and discipline of the Redridge gnolls.",al={"why kill gnolls","threat assessment goal","lakeshire defense"}},{q="Does Stormwind City help with the gnoll threat?",a="No. The Stormwind House of Nobles and regency council have withheld regular military support from outlying regions like Redridge, forcing local authorities such as Magistrate Solomon and Deputy Feldon to rely on paid mercenaries.",al={"stormwind reinforcements","why won't stormwind help","stormwind army lakeshire"}},{q="What does Deputy Feldon do with your report?",a="Deputy Feldon evaluates the strength and tenacity of the packs, confirming that the southern gnolls represent a serious military hazard rather than isolated beasts, and directs you to assist other town leaders in shore up defenses.",al={"feldon's reaction","what happens after assessing threat","turn in report"}},{q="How does this task connect to the prior quest?",a="It is the direct sequel to Encroaching Gnolls. After you first alerted the garrison to the gnoll movement, Feldon commissioned this combat patrol to assess just how bad the intrusion really is.",al={"quest line connection","encroaching gnolls followup","prerequisite quest"}}},ang={["faction:Alliance"]="Redridge showcases the cracks in the Alliance's heartland, where neglected border settlements must hire freelance champions to survive while the capital looks away.",["race:Human"]="For human defenders, protecting Lakeshire is personal; these frontier families are enduring the consequences of political paralysis in Stormwind Keep.",["class:Warrior"]="Deputy Feldon asks for aggressive combat reconnaissance, testing an armed fighter's ability to wade into fortified enemy camps and break their vanguard."},kw={"assessing","feldon","gnolls","lakeshire","mongrel","poacher","reconnaissance","redridge","threat"},rel={"quest:244","npc:deputy-feldon","subzone:lakeshire","zone:redridge","topic:gnoll","topic:stormwind-army","topic:stormwind-kingdom"},m={level="17",faction="Alliance",id=246},src={"Assessing the Threat"}}
E["quest:249"] = {t="quest",n="Morganth",z="redridge",s="Morganth is the climactic quest concluding a long investigation by the mage Theocritus into a sinister rival perched in Redridge. Entrusted with stopping a dark warlock seeking an ancient relic of horrific power, adventurers must breach the Tower of Ilgalar and put an end to his machinations.",h="Morganth is the climactic quest concluding a long investigation by the mage Theocritus into a sinister rival...",sec={{t="A Watcher Across the Border",b="From his sanctum at the Tower of Azora in eastern Elwynn Forest, the mage Theocritus kept a vigilant scrying eye trained upon the crags of Redridge. What he observed confirmed his deepest anxieties: the warlock Morganth, holed up in the Tower of Ilgalar, was actively seeking the legendary Scythe of Elune. Realizing the warlock stood on the precipice of securing this dark might, Theocritus called upon bold Alliance champions to intervene before Morganth's shadow fell across the entire kingdom of Stormwind.",sp=0},{t="Storming the Spire",b="The Tower of Ilgalar looms high above the Redridge basin, infested with gnolls and twisted arcane energies. Morganth awaited at its summit, wielding shadow magic and guarding his research. Confronting the warlock required ascending through hostile grounds to cut down the caster directly and claim his Pendant of Shadow as undeniable proof that the spire had fallen and the threat was broken.",sp=0},{t="The Scythe's Lingering Shadow",b="Though Morganth's defeat removes an immediate and catastrophic threat to Stormwind, his pursuit of the Scythe of Elune reveals just how far the artifact's dark legend reaches. While Theocritus breathes a sigh of relief upon receiving the Pendant of Shadow, the true whereabouts of the ancient scythe and the havoc it might bring remain an unsettling mystery across the surrounding provinces.",sp=1}},faq={{q="Who is Morganth?",a="Morganth is a powerful rogue warlock residing at the summit of the Tower of Ilgalar in the Redridge Mountains. He has spent his time studying dark arts and pursuing the Scythe of Elune, an artifact capable of wielding disastrous magic.",al={"morganth identity","who is morganth","morganth backstory"}},{q="Where is the Tower of Ilgalar?",a="The Tower of Ilgalar is located in the northeastern heights of the Redridge Mountains, north of Lake Everstill and past the gnoll-infested camps of the Ridgepoint area.",al={"tower of ilgalar location","where is morganth tower","redridge tower"}},{q="Why does Theocritus want Morganth dead?",a="Through his scrying spells, Theocritus learned that Morganth was hunting the Scythe of Elune and feared the warlock was close to obtaining it. Such dark power would pose a catastrophic threat to Redridge and the neighboring kingdom of Stormwind.",al={"theocritus motive","why kill morganth","theocritus quest reason"}},{q="What is the Scythe of Elune?",a="The Scythe of Elune is an ancient artifact steeped in mystery, renowned for immense, chaotic power that can warp beasts, summon nightmarish horrors, and corrupt magic. Warlocks and dark spellcasters covet it for the vast shadow energies it unleashes.",al={"scythe of elune lore","what is the scythe","why is the scythe dangerous"}},{q="What is the Pendant of Shadow?",a="The Pendant of Shadow is Morganth's magical talisman, functioning both as a focus for his dark arts and as definitive proof of his defeat when brought back to Theocritus at the Tower of Azora.",al={"pendant of shadow","morganth pendant","proof of morganth death"}},{q="What quest chain leads up to this?",a="This quest is the finale of a four-part chain starting with 'Theocritus' Retrieval' in Elwynn Forest, followed by 'A Watchful Eye' and 'Looking Further', which involve recovering tools and setting up scrying to observe Morganth's tower.",al={"morganth quest chain","morganth prerequisites","how to unlock morganth"}}},ang={["class:Mage"]="Theocritus represents the diligent, scholarly tradition of human mages watching from high towers to safeguard the realm from rogue spellcasters.",["class:Warlock"]="Morganth represents the danger of unchecked fel and shadow ambitions, proving that grasping for relics like the Scythe of Elune invites swift destruction.",["race:NightElf"]="Whispers of the Scythe of Elune in human hands should deeply alarm the kaldorei, as the relic's name touches upon sacred and volatile mysteries.",["faction:Alliance"]="Defeating Morganth protects the exposed eastern borders of Stormwind, ensuring that the Redridge region does not collapse into dark sorcery."},kw={"elwynn","morganth","pendant of shadow","redridge","scythe of elune","theocritus","tower of azora","tower of ilgalar"},rel={"quest:248","quest:94","quest:178","npc:theocritus","subzone:tower-of-ilgalar","subzone:tower-of-azora","quest:1043","topic:stormwind-kingdom"},m={start="Old Lion Statue / Theocritus",["end"]="Theocritus",level="26",faction="Alliance",id=249},src={"Morganth (quest)"}}
E["quest:3741"] = {t="quest",n="Nida's Necklace",z="redridge",s="While fishing on the docks of Lakeshire, young Nida lost a cherished necklace given to her by her father. Forbidden by their parents from braving the treacherous waters of Lake Everstill, her friend Shawn asks passing adventurers to dive in and retrieve the sunken keepsake.",h="While fishing on the docks of Lakeshire, young Nida lost a cherished necklace given to her by her father.",sec={{t="A Day at the Docks",b="Lakeshire's children often spend their days fishing along the lakefront, trying to carry on a normal childhood amidst the mounting threats encircling the Redridge Mountains. During one of these outings, young Nida accidentally dropped her treasured necklace into the depths of Lake Everstill. Having searched the wooden piers and shores in vain, her companion Shawn turns to capable adventurers for help.",sp=0},{t="Perils of Lake Everstill",b="The town's parents strictly forbid their children from swimming in the lake, and for good reason. Lake Everstill teems with aggressive murlocs and hungry threshedons lurking just beneath the surface. For a couple of town kids, recovering an item lost in the glinting mud at the lake bottom is impossible, making outside help the only hope of recovering the family gift.",sp=0}},faq={{q="Who lost the necklace?",a="The necklace belongs to Nida, a young girl living in Lakeshire. It was a special present given to her by her father, which is why its loss upsets her so much.",al={"who is nida","who lost it","necklace owner"}},{q="Why can't Shawn or Nida swim down and get it themselves?",a="Their parents strictly forbid them from swimming in Lake Everstill due to the dangers lurking beneath the surface. Aggressive murlocs and predatory threshedons make the waters far too perilous for unsupervised children.",al={"why not get it themselves","why kids not swimming"}},{q="Where did the necklace end up?",a="The necklace slipped off the docks and settled into a mound of glinting mud on the western lake bed of Lake Everstill.",al={"necklace location","where is necklace","where did it fall"}},{q="Who is Effsee?",a="Effsee is Nida's pet kitten who keeps her company in Lakeshire and happily joins her in thanking travelers who recover her necklace.",al={"effsee","nida cat"}},{q="Who starts the request to find the necklace?",a="Shawn, Nida's friend who was fishing alongside her on the docks, approaches travelers on her behalf because he knows how much the gift means to her.",al={"who gives quest","shawn role"}},{q="Why does this task matter to Lakeshire?",a="While simple compared to fighting gnolls or Blackrock orcs, small favors like this provide comfort and normalcy to the families struggling to live peacefully in a town under constant threat.",al={"lakeshire importance","why help kids"}}},ang={["faction:Alliance"]="Helping the beleaguered citizens of Lakeshire with small, personal hardships reinforces the Alliance's commitment to protecting everyday townsfolk, not just fighting larger strategic threats."},kw={"effsee","glinting mud","lake everstill","lakeshire","necklace","nida","redridge","shawn"},rel={"npc:nida","subzone:lakeshire","zone:redridge","quest:938"},m={start="Shawn",["end"]="Nida",faction="Alliance",id=3741},src={"Nida's Necklace (quest)"}}
E["quest:89"] = {t="quest",n="The Everstill Bridge",z="redridge",s="The Everstill Bridge is a rebuilding effort led by Foreman Oslow in Lakeshire to repair the town's damaged stone bridge. Progress has ground to a halt because iron meant for the project was redirected into weapons during the last orc invasion, and the replacement caravan from Stormwind was ambushed by Redridge gnolls.",h="The Everstill Bridge is a rebuilding effort led by Foreman Oslow in Lakeshire to repair the town's damaged...",sec={{t="A Town Cut Off",b="The stone bridge spanning Lake Everstill is the lifeblood of Lakeshire, connecting the western roads back toward Elwynn Forest with the far bank and the northern passes. During the recent orc incursions, the town was pushed to the brink. With survival hanging in the balance, Lakeshire melted down its structural iron supplies to forge munitions, blades, and plate armor to repel the Blackrock invaders, leaving the bridge incomplete and vulnerable.",sp=0},{t="Stolen Shipments",b="Foreman Oslow petitioned the House of Nobles and Stormwind for fresh construction materials to finish repairs. A supply caravan laden with iron was dispatched, but it never arrived. A warband of Redridge gnolls ambushed the convoy along the road, carting away vital iron pikes and rivets into their camps in the northern hills. Without adventurous travelers willing to reclaim the stolen hardware, the bridge project remains stalled while gnolls and orcs tighten their grip on the mountains.",sp=0}},faq={{q="Why is the Everstill Bridge unfinished?",a="Lakeshire had to melt down its construction iron into weapons, bullets, and armor to survive the recent orc invasion. A replacement supply shipment sent from Stormwind was subsequently ambushed and looted by local gnolls, leaving Foreman Oslow without the materials needed to finish the work.",al={"why broken bridge","who broke everstill bridge","lakeshire bridge broken"}},{q="Who is Foreman Oslow?",a="Foreman Oslow is the master builder supervising the reconstruction of the bridge across Lake Everstill. Stranded without support or materials from the capital, he relies on passing adventurers to recover stolen building supplies from the hills.",al={"foreman oslow","who is oslow"}},{q="Who stole the bridge supplies?",a="The Redridge gnolls ambushed the supply caravan coming from Stormwind and carried the iron pikes and rivets off into their encampments in the hills behind Lakeshire.",al={"who stole iron rivets","who took the bridge iron"}},{q="Why didn't Stormwind send guards to protect the caravan?",a="With King Varian Wrynn missing, the Stormwind House of Nobles has largely withheld military aid from outlying territories. Redridge Mountains has been left to fend for itself against gnolls and Blackrock orcs with only minimal support from town militias.",al={"stormwind help lakeshire","why no guards"}},{q="Why did Lakeshire melt down their iron?",a="During the last orc invasion, the defenders of Lakeshire ran desperately low on war materiel. To survive the onslaught, the town melted down its stockpiles of construction iron into armor, swords, and ammunition.",al={"why melt iron","orc invasion redridge"}},{q="What supplies are needed to repair the bridge?",a="Foreman Oslow specifically needs heavy iron pikes and iron rivets to securely shore up and anchor the bridge spans across Lake Everstill.",al={"bridge materials","what does oslow need"}}},ang={["profession:Blacksmithing"]="The shortage shows how desperate Lakeshire's defenders were: forging weapons out of structural pikes and rivets was a last-ditch effort that saved lives at the expense of vital infrastructure.",["faction:Alliance"]="Lakeshire's stranded supply lines are another glaring symptom of Stormwind's neglect of its outer territories, leaving local foremen to rely on hired blades to safeguard road commerce."},kw={"everstill bridge","foreman oslow","iron pikes","iron rivets","lakeshire","redridge","redridge gnolls"},rel={"npc:foreman-oslow","subzone:lakeshire","zone:redridge","quest:124","topic:gnoll","topic:stormwind-kingdom"},m={start="Foreman Oslow",level="20",faction="Alliance",id=89},src={"The Everstill Bridge"}}
E["quest:91"] = {t="quest",n="Solomon's Law",z="redridge",s="Solomon's Law is a local decree issued through Bailiff Conacher in the Lakeshire Town Hall. It condemns the Shadowhide gnolls of Redridge to death for colluding with Morganth, an exiled enemy of Stormwind. Adventurers are tasked with enforcing the town's harsh frontier justice by bringing back pendants taken from the gnolls.",h="Solomon's Law is a local decree issued through Bailiff Conacher in the Lakeshire Town Hall.",sec={{t="Frontier Justice in Lakeshire",b="Lakeshire stands largely isolated from Stormwind's immediate military support, forcing Magistrate Solomon and his town officials to govern Redridge with strict frontier authority. Operating out of the town hall, Bailiff Conacher serves as the arm of the local magistrate court. When external threats menace the township, the court has little recourse other than putting bounties on offenders' heads, relying on freelance mercenaries and traveling defenders to uphold the kingdom's statutes.",sp=0},{t="Aiding an Enemy of the Crown",b="The legal justification for exterminating the Shadowhide clan rests on their alliance with Morganth, a rogue spellcaster entrenched in the eastern hills. Under the laws of Lakeshire and the Kingdom of Stormwind, directly aiding a declared enemy of the realm carries a mandatory sentence of death. Because the gnolls actively carry out Morganth's bidding, the court regards them not merely as wild scavengers, but as treasonous belligerents subject to execution.",sp=0}},faq={{q="Who is Solomon and what is his law?",a="Solomon refers to Magistrate Solomon, the civilian leader of Lakeshire. 'Solomon's Law' reflects his local edicts and the statutes of Stormwind, which state that aiding a declared criminal of the kingdom is a treasonous offense punishable by death.",al={"who is solomon","solomon law meaning","what is solomons law"}},{q="Who is Morganth and why does Lakeshire care about him?",a="Morganth is a rogue practitioner of the Arcane living in the eastern foothills of Redridge. Branded an enemy of Stormwind, he uses foul magic to terrorize the local townsfolk and has bent the Shadowhide gnolls to his dark will.",al={"who is morganth","morganth backstory","why morganth dangerous"}},{q="Why are the Shadowhide gnolls being hunted specifically?",a="While gnolls are always dangerous to local settlers, the Shadowhide clan has entered the direct service of the dark wizard Morganth. This active alliance makes them lawful targets for execution under town decree.",al={"why kill shadowhides","shadowhide gnolls redridge","why gnolls targeted"}},{q="What are the pendants for?",a="The pendants worn by the Shadowhide gnolls serve as proof of their death. Bailiff Conacher requires adventurers to turn in ten of them to certify that the court's sentence has been carried out before awarding any bounty.",al={"why shadowhide pendants","purpose of pendants","pendants proof"}},{q="Where does Bailiff Conacher conduct his business?",a="Bailiff Conacher is stationed inside the Lakeshire Town Hall, alongside Magistrate Solomon and other civil administrators managing Redridge's affairs.",al={"conacher location","where is bailiff conacher","lakeshire court"}},{q="Why doesn't Stormwind send royal soldiers to deal with this?",a="The Kingdom of Stormwind is stretched thin and currently troubled by political paralysis and unrest across its territories. Lakeshire's requests for formal military reinforcements have repeatedly been overlooked, leaving Magistrate Solomon to hire adventurers.",al={"where is stormwind army","why no guards for gnolls","lakeshire abandoned by stormwind"}}},ang={["faction:Alliance"]="Upholding Solomon's decree strengthens the rule of law on the eastern frontier where Stormwind's regular forces are conspicuously absent.",["class:Paladin"]="Punishing vile gnolls who willingly serve a dark sorcerer satisfies the call to bring holy justice and protection to besieged frontier towns.",["class:Mage"]="Morganth represents the perversion of Arcane knowledge turned toward dark terror, making his agents a priority target for disciplined spellcasters."},kw={"conacher","gnolls","lakeshire","morganth","pendants","redridge","shadowhide","solomon","town hall"},rel={"npc:bailiff-conacher","subzone:lakeshire-town-hall","subzone:lakeshire","quest:249","topic:gnoll","zone:redridge","topic:stormwind-kingdom"},m={start="Bailiff Conacher",level="23",faction="Alliance",id=91},src={"Solomon's Law"}}
E["quest:92"] = {t="quest",n="Redridge Goulash",z="redridge",s="Redridge Goulash is a local culinary tradition kept alive by Chef Breanna in the lakeside settlement of Lakeshire. After exhausting her pantry to feed the defending Stormwind garrison during the recent Blackrock orc incursions, Breanna turns to traveling adventurers to replenish her supply of hearty mountain ingredients.",h="Redridge Goulash is a local culinary tradition kept alive by Chef Breanna in the lakeside settlement of...",sec={{t="A Bare Mountain Pantry",b="Lakeshire sits perpetually under siege from Blackrock orcs, gnolls, and ferocious wild beasts. When the recent orc uprising broke out along the ridges, Chef Breanna shouldered the task of feeding the entire brigade of Stormwind troops stationed in town. Sustaining an active military garrison rapidly cleared out her cupboards, leaving the town cook with plenty of appetite to satisfy but empty larders.",sp=0},{t="Mountain Bounty",b="Rather than relying on distant supply wagons from Elwynn Forest that rarely arrive, Chef Breanna turns to the dangerous wilderness outside Lakeshire's gates. The signature goulash demands a rugged blend of local meats: tough cuts from mountain condors, seasoned snouts from the formidable Great Goretusks, and crisp leg meat harvested from giant tarantulas prowling the hills.",sp=0}},faq={{q="Why is Chef Breanna out of food supplies?",a="During the recent Blackrock orc uprising, Breanna had to feed the entire brigade of Stormwind troops deployed to defend Lakeshire, completely emptying her cupboards.",al={"why empty pantry","breanna pantry","why no food"}},{q="What ingredients are used to make Redridge Goulash?",a="Authentic Redridge Goulash requires five pieces of Tough Condor Meat, five Great Goretusk Snouts, and five helpings of Crisp Spider Meat, all harvested from creatures native to the surrounding mountains.",al={"goulash ingredients","what is in redridge goulash","goulash meat"}},{q="Where is Chef Breanna located?",a="Chef Breanna can be found tending her hearth and cooking kettles in the town of Lakeshire, nestled along the northern shores of Lake Everstill in the Redridge Mountains.",al={"breanna location","where is chef breanna","lakeshire chef"}},{q="Why doesn't Lakeshire just import food from Stormwind City?",a="With orcs, Blackrock raiders, and gnolls choking the mountain passes and Stormwind's resources stretched thin, Lakeshire must frequently rely on local wildlife and visiting adventurers to stay fed.",al={"stormwind supplies","why not trade with stormwind","lakeshire food shortage"}},{q="Is Redridge Goulash considered a delicacy?",a="While the combination of spider meat, boar snouts, and leathery condor flesh sounds harsh to outsiders, Chef Breanna and the frontier folk of Lakeshire consider the finished dish a hearty mountain delicacy.",al={"is goulash good","tasty goulash","redridge delicacy"}},{q="What brigade did Breanna have to feed?",a="Breanna cooked for the Stormwind soldiers stationed in Lakeshire to push back against the Blackrock orc forces pressing down from the northern ridges.",al={"stormwind brigade","who defended lakeshire","troops in lakeshire"}}},ang={["profession:Cooking"]="For culinarians exploring the Eastern Kingdoms, Chef Breanna's goulash demonstrates how resourceful frontier cooks transform fierce mountain beasts into sustaining, savory fare.",["faction:Alliance"]="The meager state of Lakeshire's stores is a stark reminder of the toll the Blackrock orc invasion has taken on local Alliance garrisons and civilian infrastructure."},kw={"blackrock orcs","chef breanna","condor meat","goretusk snout","lakeshire","redridge goulash","redridge mountains","spider meat"},rel={"npc:chef-breanna","subzone:lakeshire","zone:redridge","topic:stormwind-kingdom"},m={start="Chef Breanna",level="18",faction="Alliance",id=92},src={"Redridge Goulash (quest)"}}
E["subzone:alther-s-mill"] = {t="subzone",n="Alther's Mill",z="redridge",s="Alther's Mill is a ruined lumber mill tucked into the rugged hills northeast of Lakeshire in the Redridge Mountains. Once a vital source of processed timber for local builders, the abandoned grounds have deteriorated into a haven for feral scavengers and prowling predators. For adventurers traveling east toward Stonewatch, the dilapidated structures serve as a grim landmark marking the boundary of safe frontier territory.",h="Alther's Mill is a ruined lumber mill tucked into the rugged hills northeast of Lakeshire in the Redridge...",sec={{t="An Abandoned Frontier Mill",b="Before the region fell prey to invading predators and orc raids, Alther's Mill bustled with timber trade that supplied the construction of Lakeshire and surrounding settlements. Its quiet clearing northeast of Lake Everstill provided ready access to mountain timber stands. As turmoil mounted across the kingdom of Stormwind and the Blackrock clan pushed down from the heights of Stonewatch, local millers abandoned the facility, leaving the dry timber buildings and wheel to decay into rot.",sp=0},{t="Shadows and Scrap",b="In the absence of human workers, the mill became infested with monstrous tarantulas, carrion vultures, and opportunistic raiders. Travelers cutting through the path to the eastern passes must skirt its shadowed perimeter carefully. In recent years, shadowy operatives and thieves have also taken advantage of the abandoned compound, using its discarded storage boxes and hidden corners to hone illicit lockpicking crafts and covert trades far from the eyes of the Lakeshire Town Watch.",sp=0}},faq={{q="What is Alther's Mill?",a="Alther's Mill is a ruined lumber mill located northeast of Lakeshire in the Redridge Mountains. It previously harvested and processed timber for the surrounding settlements until mounting wilderness dangers forced its abandonment.",al={"alther's mill","althers mill","what is this place","what was alther's mill"}},{q="Why is the mill abandoned?",a="As regional defenses weakened following the First and Second Wars, aggressive wildlife like giant spiders and encroachment by Blackrock orcs made frontier operations too perilous for ordinary laborers to maintain without royal military protection.",al={"why abandoned","who abandoned althers mill","what happened to the millers"}},{q="What creatures roam around the mill?",a="The grounds and surrounding scrublands are primarily overrun by giant mountain tarantulas, scavenger buzzards, and roving predators, along with stray marauders moving between Stonewatch and Lake Everstill.",al={"enemies at althers mill","creatures at mill","what lives here"}},{q="Why do rogues visit Alther's Mill?",a="The isolated, debris-strewn grounds make it a favored proving ground for Alliance rogues, who are directed here by their trainers to practice picking locked footlockers and retrieve valuable thieving certifications.",al={"rogue quest mill","althers mill lockpicking","thieving certificate"}}},ang={["class:Rogue"]="Alliance scoundrels know Alther's Mill well, as thieves' syndicates use the scattered, forgotten lockboxes and secluded grounds of the mill as a quiet training ground to practice delicate lockpicking.",["faction:Alliance"]="The ruined mill stands as another stark reminder of Stormwind's strained frontier garrisons, where valuable industry lies broken and abandoned within sight of Lakeshire."},kw={"alther's mill","althers mill","lakeshire","lockpicking","lumber mill","redridge","spiders","stonewatch"},rel={"zone:redridge","subzone:lakeshire","subzone:stonewatch","topic:stormwind-kingdom","topic:alliance","subzone:stonewatch-keep"},src={"Alther's Mill"}}
E["subzone:galardell-valley"] = {t="subzone",n="Galardell Valley",z="redridge",s="Galardell Valley is a rugged, dangerous canyon nestled in the northeastern heights of the Redridge Mountains. The gorge is overrun by aggressive gnoll packs and sits beneath the shadow of the infamous Tower of Ilgalar.",h="Galardell Valley is a rugged, dangerous canyon nestled in the northeastern heights of the Redridge Mountains.",sec={{t="A Den of Beasts and Shadow",b="Carved into the northeastern cliffs of Redridge, Galardell Valley has fallen completely out of the control of Lakeshire's defenders. Fierce Redridge gnolls prowl the lowlands and camp along the canyon floor, organized under brutal pack leaders such as Lieutenant Fangore. Towering high above the ravines stands the dark spire of the Tower of Ilgalar, the stronghold of the renegade mage Morganth, making the entire valley a persistent source of dread for the surrounding settlements.",sp=0}},faq={{q="Where is Galardell Valley located?",a="Galardell Valley is situated in the far northeastern corner of the Redridge Mountains, tucked behind the high crags beyond the roads leading north from Lake Everstill.",al={"galardell valley location","where is galardell valley","how to find galardell valley"}},{q="What creatures live in the valley?",a="The valley is overrun by bloodthirsty gnoll packs who patrol the trails in dense clusters, led by dangerous brutes like Lieutenant Fangore.",al={"mobs in galardell valley","who lives in galardell valley","galardell enemies"}},{q="What is the dark tower overlooking the valley?",a="That is the Tower of Ilgalar, an imposing stone structure that serves as the base of operations for the rogue sorcerer Morganth.",al={"galardell valley tower","spire above galardell","tower near gnolls redridge"}},{q="Who is Lieutenant Fangore?",a="Lieutenant Fangore is a formidable gnoll leader stationed within the valley. Known for his cunning and ferocity, he will howl for aid from nearby gnoll packs when challenged, quickly overwhelming unwary travelers.",al={"fangore","lieutenant fangore","galardell valley boss"}}},ang={["faction:Alliance"]="Lakeshire's overwhelmed town guard cannot secure the northeast road as long as gnoll packs and Morganth's dark presence hold Galardell Valley."},kw={"fangore","galardell valley","gnolls","morganth","redridge","tower of ilgalar"},rel={"subzone:tower-of-ilgalar","zone:redridge","quest:249","topic:gnoll"},src={"Galardell Valley"}}
E["subzone:lake-everstill"] = {t="subzone",n="Lake Everstill",z="redridge",s="Lake Everstill is the expansive azure body of water dominating the heart of the Redridge Mountains, flanking the town of Lakeshire. Once celebrated for tranquil fishing and clean mountain runoff, its shores and waters have lately turned treacherous due to aggressive murloc tribes and predatory lake beasts.",h="Lake Everstill is the expansive azure body of water dominating the heart of the Redridge Mountains, flanking...",sec={{t="Heart of the Valley",b="Spanning the central basin of Redridge, Lake Everstill provides the scenic backdrop and vital waterway for the township of Lakeshire. Its crystal-clear waters drain eastward toward the looming heights of Stonewatch. Spanned by the town's central bridge, the lake has long sustained local trade and quiet anglers, though anyone walking the shoreline today will find its peaceful reputation thoroughly shattered by encroaching wilderness threats.",sp=0},{t="Trouble in the Depths",b="In recent times, hostile murlocs have established camps along the northern and eastern shallows, disrupting trade and harrying fishermen. Below the surface, aquatic hazards lurk as well, including dangerous threshers such as Ol' Gummers that patrol the deeper waters. Adding to the town's grievances, an errant mage accidentally tore open an unfiltered portal beneath the lake just a year ago in 24 ADP, momentarily draining water into Ironforge and sparking both the Great Lakeshire Drought and the Great Ironforge Flood.",sp=0}},faq={{q="What dangerous creatures live in Lake Everstill?",a="The shallows are crawling with hostile murloc tribes, including scouts, tidecallers, and flesheaters. Swimming deeper poses its own hazards, as giant threshers and aggressive muckdwellers patrol beneath the surface.",al={"what is in the lake","lake everstill monsters","redridge lake mobs"}},{q="What was the Great Lakeshire Drought?",a="In 24 ADP, a reckless mage opened an unfiltered portal between the lakebed and the mountain city of Ironforge. A massive deluge surged into the dwarven capital, nearly draining Lake Everstill dry in what locals recall as the Great Lakeshire Drought.",al={"lake everstill portal","ironforge flood","lake drained"}},{q="Where does the water from Lake Everstill flow?",a="The lake is drained by an eastern river that flows out past the slopes beneath the Blackrock-held stronghold of Stonewatch.",al={"lake everstill river","where does the lake go"}},{q="Can you fish safely in Lake Everstill?",a="While the waters teem with catfish and sagefish, fishing has become extremely dangerous. Murloc raiding parties camp right along the water's edge, and large threshers attack anyone straying too far into the deep.",al={"fishing lake everstill","is it safe to fish lakeshire"}}},ang={["class:Mage"]="The lake serves as a cautionary tale in arcane academy texts on portal hygiene, following the disaster in 24 ADP where an unfiltered underwater gateway simultaneously flooded Ironforge and desiccated Lakeshire.",["faction:Alliance"]="Controlling the lake and its crossings is vital for Lakeshire's survival against the coordinated incursions of Redridge murlocs and nearby Blackrock orcs."},kw={"everstill bridge","ironforge flood","lake everstill","lakeshire","murlocs","ol gummers","redridge"},rel={"subzone:lakeshire","zone:redridge","topic:murloc","subzone:stonewatch","zone:ironforge"},src={"Lake Everstill"}}
E["subzone:lakeridge-highway"] = {t="subzone",n="Lakeridge Highway",z="redridge",s="Lakeridge Highway is an old thoroughfare running along the southern shore of Lake Everstill in the Redridge Mountains. Once a vital and heavily traveled artery prior to the First War, it has fallen into ruin and disuse. Today, roving packs of gnolls and Blackrock orcs make passage along the road perilous for travelers.",h="Lakeridge Highway is an old thoroughfare running along the southern shore of Lake Everstill in the Redridge...",sec={{t="A Fallen Artery",b="Before the devastation of the First War, the Lakeridge Highway served as a bustling trade corridor through Redridge, carrying goods and folk along the southern banks of Lake Everstill. In those peaceful days, travelers could journey between the valley settlements and the eastern heights under the protection of the Kingdom of Stormwind. That safety shattered when the Horde marched through the region, leaving eastern Redridge contested and desolate.",sp=0},{t="Peril on the Road",b="Following the seizure of Stonewatch Keep by Blackrock orcs, regular maintenance and patrols along the highway ceased entirely. The road quickly deteriorated into an overgrown track contested by savage gnoll packs. With Stormwind's military spread thin and unable to reinforce Lakeshire, the highway remains officially unsafe. Any traveler seeking to reach the eastern ridges must now carve a path through gnoll ambushes.",sp=0}},faq={{q="Where does the Lakeridge Highway lead?",a="The road tracks along the southern edge of Lake Everstill, heading eastward out of the Lakeshire area toward the foothills surrounding Stonewatch Keep and the eastern mountains of Redridge.",al={"where does lakeridge highway go","lakeridge highway path","where is lakeridge highway"}},{q="Why is the highway abandoned?",a="The highway fell into disuse after the First War, particularly when Blackrock orcs fortified Stonewatch Keep. Without the manpower to secure the road, Stormwind could not maintain it, allowing hostile gnolls to move in and choke off civilian travel.",al={"why is it abandoned","why is lakeridge highway empty","lakeridge highway fallen into disuse"}},{q="What threats wander the road today?",a="The highway is primarily haunted by aggressive gnolls that ambush anyone wandering away from Lakeshire, as well as lingering Blackrock orc scouts operating out of the eastern strongholds.",al={"dangers on lakeridge highway","mobs on lakeridge highway","who controls lakeridge highway"}},{q="Was the highway always dangerous?",a="No. In the peaceful era before the First War, the Lakeridge Highway was a well-maintained, highly traveled route that safely connected the heart of Redridge to its eastern outposts.",al={"lakeridge highway history","highway before the war"}}},ang={["faction:Alliance"]="The highway is a visible reminder of Stormwind's neglected frontiers, where local roads just outside Lakeshire have been surrendered to gnolls and orcs due to a lack of reinforcements."},kw={"gnolls","highway","lake everstill","lakeridge","redridge","road","stonewatch"},rel={"zone:redridge","subzone:lake-everstill","subzone:lakeshire","subzone:stonewatch-keep","subzone:stonewatch","topic:gnoll","topic:first-war"},src={"Lakeridge Highway"}}
E["subzone:lakeshire"] = {t="subzone",n="Lakeshire",z="redridge",s="Lakeshire is the primary human settlement in the Redridge Mountains, nestled along the northern shores of Lake Everstill. Led by Magistrate Solomon and guarded by Marshal Marris, the picturesque town is currently on the brink of collapse due to relentless assaults by Blackrock orcs, aggressive gnoll packs, and shoreline murlocs.",h="Lakeshire is the primary human settlement in the Redridge Mountains, nestled along the northern shores of...",sec={{t="A Town Under Siege",b="Once a peaceful haven in the foothills east of Stormwind, Lakeshire has become the kingdom's most embattled frontier. The town's garrison at Stonewatch Keep was brutally overrun by Blackrock clan orcs sweeping down from the north, and dark wizardry has riled local Shadowhide gnoll packs into organized raiding parties. Blackrock saboteurs have even shattered parts of the Everstill Bridge, leaving Foreman Oslow and his crew struggling to repair the span while under constant threat of attack. With murlocs choking the lake's shores and gnolls stalking the high passes, Lakeshire's defenders are stretched to their breaking point.",sp=0},{t="Abandoned by the Crown",b="Despite Magistrate Solomon's repeated and desperate pleas sent across the mountains, Stormwind City has provided virtually no military support. The kingdom's resources are drained by internal strife, and royal councilors dismiss Redridge's plight as exaggerated border skirmishes. Dwarven reinforcements dispatched from Ironforge were ambushed and vanished in the Burning Steppes, leaving Marshal Marris and his handful of remaining guards to hold the barricades alone. Lakeshire now survives solely on the courage of roving mercenaries and freelance adventurers hired straight out of the town hall.",sp=1}},faq={{q="Who governs Lakeshire?",a="Civic authority rests with Magistrate Solomon, who directs town administration from the town hall. Local defense and policing fall under Marshal Marris and the battered remnants of the town guard.",al={"lakeshire leader","who is in charge of lakeshire","magistrate of lakeshire"}},{q="Why won't Stormwind send soldiers to help Lakeshire?",a="Stormwind's forces are thinly stretched dealing with regional unrest, while royal councilors—notably Lady Katrana Prestor—have actively persuaded Highlord Bolvar Fordragon against committing standing troops to Redridge, forcing the Crown to rely on deputized adventurers instead.",al={"why no stormwind reinforcements","stormwind army lakeshire","why is lakeshire abandoned"},sp=1},{q="What happened to the Everstill Bridge?",a="Blackrock orcs damaged the massive stone bridge during their raids across the lake, severely disrupting trade and transport. Foreman Oslow oversees repairs, though missing tools and ongoing attacks keep work proceeding at a crawl.",al={"broken bridge redridge","who broke everstill bridge","foreman oslow bridge"}},{q="What threats currently surround the town?",a="The town faces a three-front siege: Blackrock orcs occupying Stonewatch Keep to the east, Shadowhide gnolls directed by the rogue sorcerer Morganth in the northern hills, and aggressive murlocs infesting the waters and banks of Lake Everstill.",al={"who is attacking lakeshire","redridge threats","lakeshire enemies"}}},ang={["faction:Alliance"]="Lakeshire stands as Stormwind's eastern bulwark; if it falls to the Blackrock clan, the heartlands of Elwynn will face orcish incursions directly.",["race:Human"]="Rebuilt by the Alliance of Lordaeron following the devastation of the Second War, Lakeshire represents hard-won resilience for Stormwind refugees who refuse to flee their homeland a second time."},kw={"blackrock orcs","everstill bridge","lake everstill","lakeshire","magistrate solomon","marshal marris","redridge","stonewatch"},rel={"zone:redridge","subzone:lake-everstill","npc:magistrate-solomon","npc:marshal-marris","npc:foreman-oslow","quest:89","subzone:stonewatch","topic:stormwind-kingdom"},src={"Lakeshire"}}
E["subzone:lakeshire-inn"] = {t="subzone",n="Lakeshire Inn",z="redridge",s="The Lakeshire Inn is the social hub and primary refuge in the beleaguered town of Lakeshire. Situated in the heart of the Redridge Mountains, it provides warmth, ale, and safe lodging for local townsfolk and weary travelers contending with the surrounding perils.",h="The Lakeshire Inn is the social hub and primary refuge in the beleaguered town of Lakeshire.",sec={{t="A Beacon of Warmth",b="Perched on the shore of Lake Everstill, the Lakeshire Inn offers a brief respite from the gnoll bands and Blackrock orcs pressing in on the town. Despite Lakeshire's increasingly desperate military situation, the tavern maintains a cozy, bustling atmosphere. Barkeep Daniels and Innkeeper Brianna attend to the locals and travelers, serving up flagons of ale, wine, and warm meals. It is a vital meeting point where townspeople trade news, drown their sorrows, and seek hired blades to help defend the eastern border of the kingdom.",sp=0},{t="Patrons and Whispers",b="Beyond ordinary patrons nursing drinks at the counter, the inn draws a variety of colorful figures. Wiley the Black watches the room from a table, keeping his own counsel and keeping tabs on regional dangers. Traveling brewers like Yorus Barleybrew make stops here, while Darcy Parker and other townsfolk frequent the common room. For adventurers venturing further into the jagged peaks or heading south toward Duskwood, the inn is the final bastion of civilization and safety before entering contested wilderness.",sp=0}},faq={{q="What services does the Lakeshire Inn provide?",a="The inn functions as the primary rest stop in Redridge. Innkeeper Brianna binds hearthstones and rents rooms to weary travelers, while Barkeep Daniels supplies refreshments, food, and drink for the road.",al={"lakeshire inn services","what can I do at lakeshire inn","innkeeper lakeshire"}},{q="Why is the inn so crowded despite the nearby attacks?",a="With orcs from the Blackrock clan descending from the northern crags and gnolls raiding local farms, townspeople and displaced settlers seek safety within the town center. The tavern provides both physical shelter and a place to share news of the defense.",al={"why is lakeshire inn full","lakeshire refugees inn","redridge tavern crowd"}},{q="Who is Wiley the Black?",a="Wiley the Black is a somber local figure found seated inside the inn. He keeps a sharp eye on the threats facing Lakeshire and provides insight and tasks to capable adventurers looking to push back the enemy presence in Redridge.",al={"wiley the black","guy in lakeshire tavern","wiley npc"}},{q="Where is the inn located within Lakeshire?",a="The inn sits right near the western entrance of Lakeshire along the northern bank of Lake Everstill, just off the main road leading into town from Elwynn Forest.",al={"where is lakeshire inn","lakeshire tavern location","find lakeshire inn"}}},ang={["faction:Alliance"]="The Lakeshire Inn is an indispensable stronghold of Alliance hospitality, serving as the staging ground for anyone fighting to protect Stormwind's vulnerable eastern flank.",["profession:Cooking"]="The common room is a lively spot to procure culinary staples, local recipes, and fresh drink from Barkeep Daniels while traveling through the mountains."},kw={"barkeep daniels","darcy parker","innkeeper brianna","lake everstill","lakeshire inn","redridge inn","wiley the black","yorus barleybrew"},rel={"subzone:lakeshire","zone:redridge","npc:wiley-the-black","npc:barkeep-daniels","npc:darcy-parker","quest:1698","subzone:three-corners"},src={"Lakeshire Inn"}}
E["subzone:lakeshire-town-hall"] = {t="subzone",n="Lakeshire Town Hall",z="redridge",s="Lakeshire Town Hall serves as the administrative seat of the Redridge Mountains, standing at the heart of the lakeside settlement. Inside, Magistrate Solomon oversees local governance while wrestling with relentless threats from Blackrock orcs and gnolls.",h="Lakeshire Town Hall serves as the administrative seat of the Redridge Mountains, standing at the heart of the...",sec={{t="Seat of Redridge Governance",b="Lakeshire Town Hall is an aging stone structure that has been diligently refurbished multiple times over the years. Positioned prominently within Lakeshire, it houses Magistrate Solomon, a kind and dedicated civil leader tasked with maintaining order in the eastern reaches of the Kingdom of Stormwind. With Stormwind's military resources stretched thin and royal aid scarce, the hall has transformed from a quiet administrative office into an active command center where desperate appeals for volunteer defenders and mercenaries are processed daily.",sp=0},{t="Under Siege and Overwhelmed",b="The halls are consistently crowded with anxious citizens seeking council and answers regarding raids, missing kin, and lost caravans. Gnoll incursions from the surrounding hills and the encroaching presence of the Blackrock orcs have pushed Solomon and his local guard to their limits. With official reinforcements from the capital failing to materialize, the magistrate relies on independent adventurers walking through the town hall doors to safeguard the region from total collapse.",sp=0}},faq={{q="Who is in charge at Lakeshire Town Hall?",a="Magistrate Solomon oversees the town hall. He is a kind and well-meaning administrator who serves as the primary governing authority for Lakeshire and the surrounding Redridge valley.",al={"who leads lakeshire","magistrate solomon","who is in town hall"}},{q="Why is the town hall seeking so much outside help?",a="Lakeshire faces severe, mounting threats from local gnoll packs and hostile Blackrock orc warbands. Because Stormwind has provided minimal military reinforcements, Magistrate Solomon must hire passing adventurers to defend the region.",al={"why does solomon need help","lakeshire problems","why are there so many quests here"}},{q="Why are there concerned citizens gathered inside?",a="Local residents gather in the town hall to demand answers from Magistrate Solomon regarding recent attacks, property losses, and the disappearance of loved ones taken during orc and gnoll raids.",al={"citizens in town hall","town hall crowd","people waiting in line"}},{q="Has Lakeshire Town Hall stood for a long time?",a="Yes, it is an older building that has survived turbulent decades and undergone diligent repairs and refurbishments to keep it functioning as the civic center of Redridge.",al={"town hall age","how old is lakeshire town hall","town hall history"}}},ang={["faction:Alliance"]="Lakeshire Town Hall represents the eastern frontier of the Alliance in Redridge, standing as a beleaguered outpost desperately holding the line without royal support from Stormwind.",["race:Human"]="For humans of Stormwind, this refurbished hall reflects both the enduring spirit of rural settlements and the frustrating abandonment felt by regional administrators when the capital turns a blind eye."},kw={"blackrock","gnolls","lakeshire","magistrate solomon","redridge","redridge mountains","stormwind","town hall"},rel={"subzone:lakeshire","zone:redridge","topic:gnoll"},src={"Lakeshire Town Hall"}}
E["subzone:render-s-rock"] = {t="subzone",n="Render's Rock",z="redridge",s="Render's Rock is a cavern stronghold tucked into the northwestern crags of the Redridge Mountains, sitting near the high pass leading toward the Burning Steppes. Controlled by the fierce Blackrock orcs, it serves as a forward redoubt and an active staging ground for their raids on the valleys below.",h="Render's Rock is a cavern stronghold tucked into the northwestern crags of the Redridge Mountains, sitting...",sec={{t="A Blackrock Bastion in the Heights",b="Carved into the rugged heights north of Lakeshire, Render's Rock serves as a fortified cave system for the invading Blackrock clan. From this defensible redoubt near the mountain pass to the Burning Steppes, veteran Blackrock orcs orchestrate attacks against the local defenders of Redridge. Its shadowed depths are strictly guarded, making any foray inside a perilous undertaking for those seeking to disrupt the orcish supply lines or recover captives lost in the ongoing conflict.",sp=0},{t="A Hostage in the Shadows",b="Beyond its strategic value to the orcs, Render's Rock holds grim importance for the defenders of Lakeshire. The wounded Bravo Company veteran, Corporal Keeshan, is held captive within its recesses. Deep behind enemy lines and isolated from his companions, Keeshan's captivity represents both the audacity of the Blackrock incursions and the high price the local garrison has paid trying to keep the mountain road open.",sp=1}},faq={{q="Where is Render's Rock located?",a="Render's Rock is situated in the far northwestern peaks of the Redridge Mountains, nestled near the path leading north into the Burning Steppes.",al={"renders rock location","where is renders rock","find renders rock"}},{q="Who controls Render's Rock?",a="The cave is occupied by formidable Blackrock orcs who use the crag as a redoubt to coordinate attacks and oversee the mountain passes bordering the Burning Steppes.",al={"who lives in renders rock","renders rock enemies","who holds renders rock"}},{q="Who is imprisoned inside the cave?",a="Corporal Keeshan, a wounded veteran soldier of the Alliance garrison, is held captive inside Render's Rock and requires assistance to safely escape back to Lakeshire.",al={"keeshan location","captive in renders rock","who is trapped in renders rock"}},{q="Why is this cave important to Lakeshire's defense?",a="Because it harbors experienced Blackrock warriors right above the Redridge valley, Render's Rock poses an immediate threat to the town of Lakeshire and allows the orcs to maintain a foothold south of the Burning Steppes.",al={"why attack renders rock","renders rock threat","importance of renders rock"}}},ang={["faction:Alliance"]="For Alliance fighters, Render's Rock represents one of the most entrenched Blackrock positions in Redridge, and clearing it is vital for freeing Corporal Keeshan and protecting Lakeshire."},kw={"blackrock orcs","burning steppes","corporal keeshan","keeshan","redridge","render's rock","renders rock"},rel={"zone:redridge","subzone:lakeshire","zone:burningsteppes"},src={"Render's Rock"}}
E["subzone:render-s-valley"] = {t="subzone",n="Render's Valley",z="redridge",s="Render's Valley is a tucked-away encampment held by Blackrock orcs in the southeastern Redridge Mountains. Far less entrenched than the massive fortresses of Stonewatch, it nonetheless poses a persistent threat to nearby travelers and hosts captives taken from surrounding lands.",h="Render's Valley is a tucked-away encampment held by Blackrock orcs in the southeastern Redridge Mountains.",sec={{t="A Foothold in the Southeast",b="Tucked among the rocky ridges southeast of Lake Everstill, Render's Valley serves as an auxiliary camp for the Blackrock orcs operating in Redridge. Unlike the heavily fortified keeps and stone towers of the northern cliffs, the valley consists of a modest cluster of war tents, banners, and sentry outposts. Despite being smaller and less armed than the clan's core forces, the warriors here raid local roads, harass travelers, and keep captured prisoners in crude cages under guard.",sp=0},{t="Secret Paths and Captives",b="Beyond the war parties roaming its dirt paths, the valley holds unexpected points of interest for intrepid scouts. Human prisoners have occasionally been sighted within the camp, including a captive servant connected to the Tower of Azora who managed to trade specialist goods right under his captors' noses. Additionally, rugged and unmarked pathways through the high southern bluffs behind the valley allow daring pathfinders to slip across the border into the murky bogs of the Swamp of Sorrows.",sp=0}},faq={{q="Who controls Render's Valley?",a="The valley is occupied by the Blackrock clan, an aggressive orcish faction that has pushed south from the Burning Steppes into Redridge to conquer territory and harass human settlements.",al={"who is in renders valley","renders valley orcs","what clan is in renders valley"}},{q="Are the orcs here as dangerous as the ones at Stonewatch?",a="No. The Blackrock warriors stationed in Render's Valley are generally younger or less formidable skirmishers compared to the hardened elite forces garrisoning Stonewatch Keep to the north.",al={"renders valley difficulty","how strong are the orcs here"}},{q="Who is the prisoner kept in the camp?",a="A servant affiliated with the Tower of Azora in Elwynn Forest was captured by the Blackrock clan and held here in a cage. Those brave enough to reach him can acquire specialized tailoring supplies.",al={"renders valley captive","servant of azora redridge","renders valley tailor"}},{q="Can you reach the Swamp of Sorrows from here?",a="Yes. A steep, unofficial mountain trail winds through the southern bluffs just past Render's Valley, offering a hidden shortcut directly into the northern marches of the Swamp of Sorrows.",al={"path to swamp of sorrows","renders valley mountain pass","redridge to swamp shortcut"}}},ang={["faction:Alliance"]="The camp is a secondary Blackrock raiding outpost that threatens southern Redridge, making its clearing vital for securing trade and travel in Lakeshire.",["profession:Tailoring"]="The Captured Servant of Azora imprisoned in the orc camp offers unique tailoring patterns and materials to craftsmen willing to fight through the sentries to reach him."},kw={"blackrock orcs","redridge","render's valley","renders valley","servant of azora","swamp of sorrows pass"},rel={"zone:redridge","zone:swampofsorrows"},src={"Render's Valley"}}
E["subzone:rethban-caverns"] = {t="subzone",n="Rethban Caverns",z="redridge",s="Rethban Caverns is an extensive cave system tucked into the northwestern cliffs of the Redridge Mountains. Infested with aggressive Redridge gnolls, it is best known as the sole source of uncommon Rethban ore.",h="Rethban Caverns is an extensive cave system tucked into the northwestern cliffs of the Redridge Mountains.",sec={{t="A Gnoll Warren",b="Carved deep into the northwestern mountains overlooking Lake Everstill, Rethban Caverns serves as a fortified redoubt for the local gnolls. Under the cunning leadership of Ardo Dirtpaw, the pack fiercely guards the twisting passages and subterranean chambers, attacking any wanderers who stray too close to their hillside entrance.",sp=0},{t="The Veins of Rethban",b="The caverns take their name from Bart Rethban, though today they are primarily remembered for Rethban ore, a distinct mineral found within the rock walls and carried by the Dirtpaw pack. Blacksmiths and researchers in Lakeshire often send travelers into the dangerous, winding tunnels to recover samples of this rare mountain ore.",sp=0}},faq={{q="Where are Rethban Caverns located?",a="The caverns lie along the jagged bluffs in the northwestern region of the Redridge Mountains, north of the main road heading toward Lakeshire.",al={"rethban caverns location","where is rethban","how to find rethban caverns"}},{q="What creatures dwell inside Rethban Caverns?",a="The tunnels are overrun by Redridge gnolls of the Dirtpaw clan, who answer to the cunning chieftain Ardo Dirtpaw.",al={"rethban mobs","who lives in rethban caverns","rethban enemies"}},{q="Why do adventurers venture into the caverns?",a="Travelers and townsfolk from Lakeshire seek out Rethban ore, an uncommon mineral vein found deep inside the caves and held by the residing gnolls.",al={"rethban cavern quests","why go to rethban caverns","rethban ore quest"}},{q="Who is Rethban Caverns named after?",a="The cavern system is believed to have been named after an individual known as Bart Rethban.",al={"who was rethban","bart rethban","origin of rethban name"}}},ang={["profession:Mining"]="The caverns are famed for yielding Rethban ore, a mineral deposit fiercely contested by the local gnoll tribes.",["faction:Alliance"]="The aggressive gnoll pack entrenched inside the caverns poses an ongoing threat to travelers in northern Redridge, requiring Lakeshire's defenders to keep the bluffs secure."},kw={"ardo dirtpaw","bart rethban","dirtpaw","gnolls","lakeshire","redridge","rethban","rethban caverns","rethban ore"},rel={"quest:347","zone:redridge","topic:gnoll"},src={"Rethban Caverns"}}
E["subzone:shalewind-canyon"] = {t="subzone",n="Shalewind Canyon",z="redridge",s="Shalewind Canyon is a rugged ravine in the eastern crags of the Redridge Mountains, tucked close to Stonewatch Falls. Bordered by towering rock faces and hostile Blackrock orc encampments, it serves as a secluded and perilous pass within Redridge's eastern wilderness.",h="Shalewind Canyon is a rugged ravine in the eastern crags of the Redridge Mountains, tucked close to...",sec={{t="A Rugged Redridge Pass",b="Carved into the eastern heights of the Redridge Mountains, Shalewind Canyon lies in close proximity to the roaring cascades of Stonewatch Falls and the shadowed foothills leading toward the Blackrock stronghold of Stonewatch. Unlike the peaceful waters of Lake Everstill, the canyon is an unforgiving landscape of sheer stone and high-altitude winds. With the local human settlements hard-pressed by invading Blackrock orcs, the surrounding cliffs present constant dangers from roving raiders, whelps, and hostile mountain beasts.",sp=0}},faq={{q="Where is Shalewind Canyon located?",a="Shalewind Canyon is situated in the eastern reaches of the Redridge Mountains, nestled near Stonewatch Falls and south of the rocky trails that approach Stonewatch Keep.",al={"shalewind canyon location","where is shalewind","shalewind canyon redridge"}},{q="Who controls Shalewind Canyon?",a="The canyon is a contested wilderness territory. While nominally part of the Kingdom of Stormwind's Redridge borders, the nearby presence of Blackrock orc warbands and predatory wildlife makes it largely ungoverned and treacherous.",al={"who lives in shalewind canyon","who owns shalewind","shalewind canyon enemies"}},{q="Why is this area so dangerous for travelers?",a="The canyon sits dangerously close to the stronghold of Stonewatch, where Blackrock orcs orchestrate assaults against Lakeshire. Any traveler caught traversing the narrow passes risks ambush by orcish scouting parties or the aggressive beasts native to the crags.",al={"is shalewind canyon safe","shalewind canyon threats"}}},ang={["faction:Alliance"]="For Alliance forces seeking to scout Blackrock movements around Stonewatch Falls, Shalewind Canyon serves as a treacherous eastern frontier where vigilance is vital."},kw={"blackrock","canyon","falls","redridge","shalewind","stonewatch"},rel={"subzone:stonewatch-falls","subzone:stonewatch","zone:redridge"},src={"Shalewind Canyon"}}
E["subzone:stonewatch"] = {t="subzone",n="Stonewatch",z="redridge",s="Stonewatch is a fortified stronghold in central Redridge Mountains, built to defend the surrounding human lands from northern invasions. Formerly manned by Stormwind soldiers, the fortress has fallen under the brutal control of the Blackrock orcs, posing an immediate threat to nearby Lakeshire.",h="Stonewatch is a fortified stronghold in central Redridge Mountains, built to defend the surrounding human...",sec={{t="A Bastion Overrun",b="Positioned over the cliffs near Stonewatch Falls, Stonewatch comprises a heavily built tower and keep designed to guard the approaches from the Burning Steppes. Originally held by Lakeshire's defenders, the fortification fell when the rogue warlock Morganth forged an alliance with the Blackrock clan. Infused with dark magic, the invading orcs overwhelmed the local human garrison—the 12th Sabre Regiment—and claimed the fortress. Although Morganth eventually turned on his allies and withdrew to the nearby Tower of Ilgalar with an army of Shadowhide gnolls, the Blackrock orcs retained a stranglehold over the keep under the command of General Gath'Ilzogg and Lieutenant Tharil'zun.",sp=0},{t="The Threat to Lakeshire",b="With Stonewatch firmly garrisoned by hostile orcs, Lakeshire sits directly in the crosshairs of an impending conquest. Cut off from substantial military reinforcements by an indifferent or paralyzed Stormwind House of Nobles, Magistrate Solomon and Marshal Marris have been forced to hire mercenary aid and volunteers. Decapitating the fortress's leadership—targeting both Tharil'zun and Gath'Ilzogg—remains the town's desperate primary hope for relieving the siege on the region.",sp=0}},faq={{q="Who controls Stonewatch right now?",a="Stonewatch is occupied by the Blackrock clan of orcs, under the command of General Gath'Ilzogg and his lieutenant, Tharil'zun. They drove out the kingdom's garrison and now use the stronghold as a staging ground for attacks across Redridge.",al={"who is in stonewatch","who holds stonewatch","stonewatch enemies"}},{q="How did the humans lose Stonewatch?",a="The keep fell during a concerted invasion by the Blackrock clan, empowered by the dark sorcery of the rogue human warlock Morganth. Together, they crushed the defenders of the 12th Sabre Regiment and captured the entire complex.",al={"fall of stonewatch","how did stonewatch fall","stonewatch backstory"}},{q="Why isn't Stormwind sending an army to take it back?",a="Stormwind has refused to allocate sufficient troops to the border regions, leaving Magistrate Solomon and Marshal Marris to defend Redridge alone. Lakeshire relies on visiting adventurers and mercenaries to mount counterattacks against Stonewatch.",al={"why no stormwind help","lakeshire reinforcements"}},{q="What is the relationship between Stonewatch and the Tower of Ilgalar?",a="Morganth originally aided the Blackrock orcs in taking Stonewatch, but shortly after their victory, he betrayed his allies. He constructed the nearby Tower of Ilgalar to amass his own retinue of magical thralls and Shadowhide gnolls, attacking orc and human alike.",al={"tower of ilgalar connection","morganth stonewatch"}}},ang={["faction:Alliance"]="Stonewatch represents one of the most perilous forward incursions of hostile orcs into core Alliance territory, making its recovery vital to the safety of Redridge.",["race:Human"]="The slaughter of the 12th Sabre Regiment and the fall of the keep stand as painful reminders of Lakeshire's vulnerability and Stormwind's political neglect."},kw={"blackrock orcs","gath'ilzogg","lakeshire","morganth","redridge","stonewatch","stonewatch keep","tharil'zun"},rel={"subzone:stonewatch-keep","subzone:stonewatch-tower","subzone:stonewatch-falls","subzone:lakeshire","zone:redridge","subzone:tower-of-ilgalar","quest:169","quest:19"},src={"Stonewatch"}}
E["subzone:stonewatch-falls"] = {t="subzone",n="Stonewatch Falls",z="redridge",s="Stonewatch Falls is a scenic waterfall and deep mountain pool situated in the eastern reaches of the Redridge Mountains, fed by the outflow of Lake Everstill. Cascading down the hillside beneath the looming heights of Stonewatch, its isolated waters are claimed by a hostile tribe of murlocs.",h="Stonewatch Falls is a scenic waterfall and deep mountain pool situated in the eastern reaches of the Redridge...",sec={{t="A Perilous Mountain Basin",b="Pouring from the eastern river of Lake Everstill, Stonewatch Falls cascades down the rugged terrain beneath the Shadowhide gnoll stronghold of Stonewatch. The plunging water carves out a deep pool tucked against the mountainside. Despite its natural beauty, travelers rarely linger to admire the view; a vicious band of murlocs infests the pool, building crude reed hovels and preying upon any foolish enough to trespass along the water's edge.",sp=0}},faq={{q="Where does the water from Stonewatch Falls come from?",a="The falls are fed by the river draining out of the eastern side of Lake Everstill, tumbling downhill into a secluded mountain basin beneath the cliffs of Stonewatch.",al={"where does stonewatch falls start","falls water source","stonewatch river source"}},{q="What creatures live around Stonewatch Falls?",a="A local tribe of murlocs occupies the shores of the falls. They subsist on fish drawn from the deep mountain pool and build rough lean-tos and shoreline shelters along the banks.",al={"what is at stonewatch falls","murlocs at stonewatch falls","mobs near falls"}},{q="Is Stonewatch Falls connected to Stonewatch Keep?",a="The falls sit at the foot of the hillside directly below Stonewatch and its ruined keep. While Shadowhide gnolls command the fortified heights above, the murlocs dominate the water basin below.",al={"falls connection to keep","is stonewatch keep near the falls","stonewatch relationship"}}},ang={["faction:Alliance"]="The murloc settlement at Stonewatch Falls represents yet another dangerous pocket of monsters harassing travelers in the already beleaguered eastern Redridge countryside."},kw={"lake everstill","murlocs","redridge","stonewatch","stonewatch falls","waterfall"},rel={"zone:redridge","subzone:lake-everstill","subzone:stonewatch","subzone:stonewatch-keep","topic:murloc"},src={"Stonewatch Falls"}}
E["subzone:stonewatch-keep"] = {t="subzone",n="Stonewatch Keep",z="redridge",s="Stonewatch Keep is a fortified stone stronghold looming in eastern Redridge Mountains, once built and manned by the Kingdom of Stormwind. It has fallen to an invading host of Blackrock orcs, serving as the forward operational base from which their warlords terrorize Lakeshire.",h="Stonewatch Keep is a fortified stone stronghold looming in eastern Redridge Mountains, once built and manned...",sec={{t="A Fallen Bastion",b="Stonewatch Keep originally defended the eastern ridges and guarded the settlers of Lakeshire against hostile incursions. That peace shattered when the renegade warlock Morganth struck an alliance with the Blackrock clan. Bolstered by dark magic, the orcs stormed the fortress with vicious ferocity, overwhelming the human defenders and taking the keep for themselves. Although Morganth later abandoned his allies to raise the nearby Tower of Ilgalar and subjugate local gnolls, the Blackrock invaders successfully consolidated their grip over Stonewatch, transforming a former bastion of the Alliance into a fortified staging ground for their assault on the valley.",sp=0},{t="The Warlord's Seat",b="Now occupied by a heavy garrison of Blackrock warriors, the keep is overseen by the formidable orcish warlord Gath'Ilzogg and his brutal lieutenant, Tharil'zun. From the stone ramparts, these commanders coordinate raids across Redridge, taking prisoners such as Stormwind's Corporal Keeshan. With the kingdom's military spread thin and unable to dispatch a full regiment to liberate the fortress, Magistrate Solomon and Marshal Marris have been forced to hire mercenary champions to infiltrate the stronghold and execute the Blackrock leadership before Lakeshire is completely overrun.",sp=0}},faq={{q="Who owns Stonewatch Keep right now?",a="The keep is currently occupied by the Blackrock clan, led on-site by Warlord Gath'Ilzogg and his lieutenant Tharil'zun. It was formerly an Alliance stronghold defending the town of Lakeshire before it was captured.",al={"who controls stonewatch keep","who lives in stonewatch keep","stonewatch keep enemies"}},{q="How did the Blackrock orcs capture the keep?",a="The Blackrock clan allied with the rogue human warlock Morganth. Empowered by Morganth's dark sorcery, the orcs launched a ferocious assault that overwhelmed the human defenders stationed at Stonewatch.",al={"how did orcs get stonewatch","fall of stonewatch keep","why did stonewatch fall"}},{q="Why doesn't the Stormwind Army retake Stonewatch Keep?",a="The Stormwind Army has left Redridge largely neglected due to internal politics and troop shortages across the kingdom. As a result, Lakeshire's town leaders must rely on independent adventurers to deal with the threat.",al={"why no stormwind army","where are the guards","lakeshire army help"}},{q="What is Morganth's connection to this fortress?",a="Morganth helped the Blackrock clan conquer Stonewatch Keep, but betrayed them shortly after their victory. He relocated to construct his own lair, the Tower of Ilgalar, using ensorcelled Shadowhide gnolls rather than orcs to do his bidding.",al={"morganth stonewatch","is morganth inside stonewatch keep"}}},ang={["faction:Alliance"]="Stonewatch Keep is a painful reminder of Stormwind's strained borders; clearing its ramparts is essential to protecting Lakeshire's vulnerable townsfolk.",["race:Human"]="Human defenders shed blood defending these walls, and liberating the keep helps avenge the fallen soldiers and captives taken by the Blackrock clan."},kw={"blackrock clan","gath'ilzogg","keeshan","lakeshire","morganth","redridge mountains","stonewatch keep","tharil'zun"},rel={"subzone:stonewatch","subzone:stonewatch-tower","quest:169","quest:19","subzone:tower-of-ilgalar","subzone:lakeshire","npc:marshal-marris","npc:magistrate-solomon"},src={"Stonewatch Keep"}}
E["subzone:stonewatch-tower"] = {t="subzone",n="Stonewatch Tower",z="redridge",s="Stonewatch Tower is a stone guard tower standing within the overrun stronghold of Stonewatch in northeastern Redridge. Once maintained by the defenders of Lakeshire, the outpost was captured by the Blackrock clan to monitor the surrounding ridges and secure their mountain bastion.",h="Stonewatch Tower is a stone guard tower standing within the overrun stronghold of Stonewatch in northeastern...",sec={{t="A Fallen Watchpost",b="Built by the Kingdom of Stormwind to guard the high mountain passes above Lake Everstill, Stonewatch Tower served as the forward scouting sibling to Stonewatch Keep. From its elevated vantage point, sentries could easily watch the eastern ridges and alert Lakeshire to any threats advancing from the Burning Steppes. That early warning network collapsed when General Gath'Ilzogg's Blackrock orcs swept down from the heights, overrunning the human defenders and claiming the stronghold for their own war effort. Today, the tower bristles with Blackrock sentinels, ensuring no Alliance scouts approach the fortress undetected.",sp=0}},faq={{q="What is Stonewatch Tower?",a="It is a fortified human watchtower located inside the greater Stonewatch complex in northeastern Redridge Mountains. Originally built to protect the region, it is currently held by invaders from the Blackrock clan.",al={"stonewatch tower lore","what is this tower","stonewatch lookout"}},{q="Who controls Stonewatch Tower right now?",a="The tower is occupied by orcs of the Blackrock clan serving under General Gath'Ilzogg, who captured the stronghold from the local humans of Redridge.",al={"who owns stonewatch tower","who is in stonewatch tower","stonewatch tower enemies"}},{q="Why is the tower important to the Blackrock orcs?",a="Its high elevation allows the Blackrock clan to spot approaching Alliance forces and safeguard the approach to their primary fortress, Stonewatch Keep.",al={"why do orcs want stonewatch tower","strategic importance of stonewatch tower"}},{q="Can Lakeshire reclaim the tower?",a="Lakeshire lacks the military manpower to retake Stonewatch on its own and relies on wandering adventurers to thin out the Blackrock garrison holding the tower and keep.",al={"will lakeshire take it back","lakeshire plans for stonewatch tower"}}},ang={["faction:Alliance"]="Stonewatch Tower is a grim reminder of how far the Blackrock clan has pushed into Stormwind territory while the kingdom's central army remains absent.",["race:Human"]="For the folk of Lakeshire, seeing orcish standards flying above Stonewatch's towers is an ongoing threat to their very survival."},kw={"blackrock clan","gath'ilzogg","lakeshire","redridge","scout tower","stonewatch","stonewatch tower"},rel={"subzone:stonewatch","subzone:stonewatch-keep","subzone:lakeshire","topic:blackrock-clan","zone:redridge"},src={"Stonewatch Tower"}}
E["subzone:three-corners"] = {t="subzone",n="Three Corners",z="redridge",s="Three Corners is a vital crossroads nestled just inside the western border of the Redridge Mountains. Branching toward the three neighboring towns of Goldshire, Lakeshire, and Darkshire, it marks the boundary between the heart of the kingdom and Redridge's perilous wilderness. A Stormwind Guard watchtower stands over the intersection, holding the line against encroaching gnoll packs.",h="Three Corners is a vital crossroads nestled just inside the western border of the Redridge Mountains.",sec={{t="A Crossroads of Three Shires",b="Situated at the western edge of the Redridge Mountains, Three Corners connects three key Alliance settlements: Goldshire in Elwynn Forest to the west, Lakeshire to the northeast, and Darkshire in Duskwood to the south. Because of this strategic junction, Stormwind erected Tower Watch at the center of the crossroads. Manning the post, local guards and scouts attempt to keep the thoroughfares clear of Redridge's aggressive gnolls, who constantly threaten travelers and supply wagons passing between the regions.",sp=0}},faq={{q="Why is this place called Three Corners?",a="The crossroads splits into three distinct roads heading toward the 'Three Shires' of southern Stormwind: Goldshire in Elwynn Forest, Lakeshire in Redridge, and Darkshire in Duskwood.",al={"three corners name meaning","why three corners","three corners history"}},{q="Who guards the tower at Three Corners?",a="The outpost, known as Tower Watch, is manned by members of the Stormwind Guard. They serve as an early warning post and defensive bulwark against gnolls venturing down from the Redridge peaks toward the Elwynn border.",al={"who controls three corners","tower watch guards","who is in the tower"}},{q="What threats are active around Three Corners?",a="Gnolls from the surrounding hills constantly prowl the roadway, ambushing travelers and couriers. The guards stationed here regularly call upon passing adventurers to cull the gnoll packs and keep the roads passable.",al={"three corners monsters","dangers at three corners","three corners gnolls"}}},ang={["faction:Alliance"]="For Alliance travelers leaving the relative safety of Elwynn Forest, Three Corners is the first fortified outpost and a stark reminder that Stormwind's grip on its borderlands is stretched thin.",["race:Human"]="The watchtower links the southern human heartlands, serving as a critical junction for couriers and trade moving between Elwynn, Duskwood, and Redridge."},kw={"crossroads","darkshire","gnolls","goldshire","lakeshire","redridge","three corners","tower watch"},rel={"zone:redridge","zone:elwynn","zone:duskwood","subzone:lakeshire","subzone:goldshire","subzone:darkshire","topic:stormwind-guard","topic:gnoll"},src={"Three Corners"}}
E["subzone:tower-of-ilgalar"] = {t="subzone",n="Tower of Ilgalar",z="redridge",s="The Tower of Ilgalar is an isolated spire perched high in the crags of the eastern Redridge Mountains. Once a wizard's retreat, it has fallen into shadow as the hideout of Morganth, a banished sorcerer from Stormwind who now commands the region's feral gnolls and practices dark magic.",h="The Tower of Ilgalar is an isolated spire perched high in the crags of the eastern Redridge Mountains.",sec={{t="A Bastion of Dark Sorcery",b="Looming over eastern Redridge, the Tower of Ilgalar serves as the personal sanctum of Morganth. Cast out from the Mage Quarter of Stormwind for dabbling in forbidden magic, the rogue sorcerer retreated into these rugged heights to delve deeper into the dark arts without imperial interference. Rather than living in solitude, Morganth asserted dominion over the local Shadowhide gnoll clan, employing them as savage sentries around the base of the spire. Inside, the tower crawls with conjured demonic hounds and crackles with shadowy power, posing a constant, brooding menace to the beleaguered town of Lakeshire below.",sp=0},{t="The Rivalry with Azora",b="Scholars often draw parallels between the Tower of Ilgalar and the Tower of Azora in Elwynn Forest. While the true identity of Ilgalar remains shrouded in mystery, the two towers stand in quiet, magical opposition. In Elwynn, the Kirin Tor mage Theocritus maintains careful watch over Ilgalar through enchanted scrying devices like the Eye of Azora, monitoring Morganth's sinister experiments and plotting to neutralize the renegade before his corruption spreads further through the kingdom.",sp=0}},faq={{q="Who lives in the Tower of Ilgalar?",a="The tower is held by Morganth, a renegade human sorcerer who was exiled from Stormwind City for practicing forbidden dark magic. He now rules the tower alongside summoned demonic darkhounds and commands the local Shadowhide gnolls.",al={"who is in tower of ilgalar","tower of ilgalar boss","who controls the tower"}},{q="Why did Morganth flee to Redridge?",a="Morganth was cast out of the Mage Quarter in Stormwind after pursuing the dark arts. He retreated to the remote crags of Redridge to conduct his forbidden experiments far away from the scrutiny of the realm's authorities and the Kirin Tor.",al={"why is morganth here","morganth backstory","why was morganth exiled"}},{q="What is the connection between this tower and the Tower of Azora?",a="Both towers are prominent magical spires in southern Stormwind, seemingly mirrored in purpose. From the Tower of Azora in Elwynn Forest, the mage Theocritus actively scries upon the upper sanctum of Ilgalar using the Eye of Azora to keep watch over Morganth's dark rituals.",al={"tower of azora connection","ilgalar and azora","eye of azora redridge"}},{q="Why are there gnolls guarding the tower?",a="Morganth used his magical influence to subjugate the local Shadowhide clan of gnolls. They act as outer sentries and muscle, keeping intruders, scouts, and the Lakeshire militia from scaling the cliffs to his sanctum.",al={"why are gnolls here","shadowhide gnolls tower","gnolls around tower"}}},ang={["class:Mage"]="The tower serves as a stark warning of what happens when arcane studies delve into forbidden dark magic, drawing the watchful eye of Kirin Tor veterans like Theocritus.",["class:Warlock"]="Morganth's reliance on summoned darkhounds and shadowy hexes mirrors demonic arts, making his mountain retreat an intriguing example of rogue spellcraft outside of city covens."},kw={"azora","darkhounds","ilgalar","lakeshire","morganth","redridge","shadowhide","theocritus","tower of ilgalar"},rel={"zone:redridge","npc:theocritus","subzone:tower-of-azora","subzone:mage-quarter","zone:stormwind","topic:gnoll"},src={"Tower of Ilgalar"}}
E["zone:redridge"] = {t="zone",n="Redridge Mountains",z="redridge",s="East of Elwynn Forest, the Redridge Mountains feature rushing rivers, wooded slopes, and the serene expanse of Lake Everstill. Despite its scenic heights, the region is besieged by hostile Shadowhide gnolls and the encroaching Blackrock orcs of the Dark Horde. With the kingdom's military tied up by internal strife in Stormwind, the lakeside town of Lakeshire must rely on wandering mercenaries to hold the line.",h="East of Elwynn Forest, the Redridge Mountains feature rushing rivers, wooded slopes, and the serene expanse...",sec={{t="A Bastion Under Siege",b="The Redridge range was once among the most peaceful corners of the kingdom, supplying Stormwind with timber, freshwater fish, and crops. Today, that quiet life has eroded. The lakeside township of Lakeshire sits perpetually fortified against aggressive incursions. To the east, Stonewatch Keep—once a proud bastion of the kingdom—has fallen under the control of renegade Blackrock orcs and gnolls, cutting off roads and threatening to overrun the eastern valleys entirely.",sp=0},{t="The Divided Range",b="Geographically, these peaks form part of the spine running down the subcontinent of Azeroth. Centuries ago, the mountain chain reached much farther north until the Dark Iron clan inadvertently summoned the Firelord Ragnaros, tearing the earth asunder and creating the fiery crater of Blackrock Mountain. That cataclysm severed the northern peaks into the ash-choked Burning Steppes, leaving only the southern Redridge valleys lush, green, and vulnerable to attacks descending from the slopes above.",sp=0},{t="Neglected by the Crown",b="While Magistrate Solomon and Marshal Marris plead for reinforcements, the regency council in Stormwind has effectively abandoned Lakeshire to fend for itself. Desperate entreaties sent to Sentinel Hill and Darkshire yield nothing, as both sister settlements are crippled by their own crises. With regular royal forces nowhere in sight, local magistrates must hire any capable sellsword willing to brave the Lakeridge Highway, clear the gnoll camps, and push back the shadow looming over Lake Everstill.",sp=0}},faq={{q="Why won't Stormwind send soldiers to help Lakeshire?",a="With King Varian Wrynn missing, the court of Stormwind is paralyzed by factional squabbling and court intrigue under Highlord Bolvar Fordragon and Lady Prestor. The crown refuses to commit regular garrison troops to outlying territories, leaving towns like Lakeshire, Sentinel Hill, and Darkshire to scrape together local militias and hire wandering adventurers.",al={"why no stormwind guards","why is redridge abandoned","where is stormwind army"}},{q="Who controls Stonewatch Keep?",a="Stonewatch Keep has been overrun by Blackrock orcs affiliated with the Dark Horde, alongside allied Shadowhide gnolls and the renegade human warlock Morganth. From this fortified mountain stronghold, they threaten the entire eastern half of the zone and choke off travel along the Lakeridge Highway.",al={"who is in stonewatch","stonewatch enemies","what happened to stonewatch"}},{q="What threats dwell in Lake Everstill?",a="While tranquil from the shoreline, Lake Everstill's waters are infested with hostile murloc tribes that raid the nearby docks and ruins. Swimmers must also contend with predatory threshadons lurking beneath the surface, giving rise to persistent rumors of aquatic monsters prowling the depths.",al={"lake everstill monsters","redridge lake dangers","everstill murlocs"}},{q="Are there any Horde outposts in Redridge?",a="No. The Redridge Mountains contain no Horde settlements, vendors, or flight paths. Horde travelers passing through the zone are generally en route between the Burning Steppes to the north and the Swamp of Sorrows to the southeast, having to navigate Alliance-held roads and hostile wilderness.",al={"horde towns redridge","is redridge horde or alliance","horde flight path redridge"}},{q="What is the Three Corners?",a="The Three Corners is a vital crossroads in the southwest corner of Redridge. It connects the Lakeridge Highway with the eastern border of Elwynn Forest and the northern road into Duskwood, making it an essential transit hub frequently targeted by wandering gnolls and wild beasts.",al={"three corners","three corners crossroads","redridge intersection"}},{q="Why is the northern path to the Burning Steppes so perilous?",a="The trail leading north past Render's Valley climbs directly into the Burning Steppes, a desolate volcanic wasteland dominated by powerful Blackrock orcs, fire elementals, and dragonkin. The sudden shift in danger makes the northern mountain pass one of the deadliest geographic ascents in southern Azeroth.",al={"redridge north road","burning steppes border redridge","redridge pass north"}}},ang={["faction:Alliance"]="Lakeshire serves as a critical frontline hub for young Alliance soldiers honing their skills against organized orcish and gnoll forces.",["faction:Horde"]="The Blackrock orcs entrenched in Redridge belong to the hostile Dark Horde, making them enemies of Thrall's Horde just as much as the humans in Lakeshire.",["profession:Mining"]="The rocky crags and valleys surrounding Lake Everstill provide abundant outcroppings of copper, tin, and rare silver veins, particularly near the Rethban Caverns.",["profession:Herbalism"]="The temperate mountain slopes foster steady growths of Briarthorn, Bruiseweed, Mageroyal, and Swiftthistle."},kw={"blackrock orcs","lake everstill","lakeshire","magistrate solomon","marshal marris","redridge","redridge mountains","render's valley","shadowhide","stonewatch","stonewatch keep","verner osgood"},rel={"subzone:lakeshire","subzone:lake-everstill","subzone:stonewatch-keep","npc:magistrate-solomon","npc:marshal-marris","zone:burningsteppes","zone:elwynn","zone:duskwood"},m={levels="15-25"},src={"Redridge Mountains (Classic)","Redridge Mountains"}}
